routine:collect_admin_access.account_sta.source:
declare a collect_admin_access.whatsapp_approvals%rowtype; approved boolean; granted boolean;
begin
  select * into a from collect_admin_access.whatsapp_approvals where user_id=p_user;
  approved := collect_admin_access.approved_identity(p_user);
  granted := exists(select 1 from public.admin_user_roles ur join public.admin_roles r on r.id=ur.role_id
    where ur.user_id=p_user and ur.revoked_at is null and r.name='platform_owner');
  return jsonb_build_object('user_id',p_user,
    'phone_masked',public.mask_phone(coalesce(a.phone_e164,collect_admin_access.verified_phone(p_user))),
    'approved_at',a.approved_at,'expires_at',a.expires_at,
    'status',case when a.user_id is null then 'not_approved' when a.revoked_at is not null then 'revoked'
      when a.expires_at <= statement_timestamp() then 'expired'
      when not approved then 'identity_changed' else 'approved' end,
    'approved',approved,'role_granted',granted,'admin_access',approved and granted,
    'access_status',case when approved and granted then 'active' when granted then 'approval_required'
      when approved then 'approved' else 'revoked' end);
end;

routine:collect_admin_access.approval_st.source:
begin
  perform public.assert_admin_permission('admin_users.read');
  if not exists(select 1 from public.profiles where id=p_user) then
    raise exception 'Account unavailable' using errcode='22023';
  end if;
  return collect_admin_access.account_state(p_user);
end;

routine:collect_admin_access.approve_wha.source:
declare
  phone text := btrim(coalesce(p_phone,''));
  reason_text text := btrim(coalesce(p_reason,''));
  prior collect_admin_access.whatsapp_approvals%rowtype;
begin
 perform public._lock_notification_session_gate();
  -- All access/approval mutations serialize, and caller authority is checked
  -- AFTER waiting so a revoked operator cannot finish a queued grant.
  perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
  if p_bootstrap then
    if auth.jwt()->>'role' is distinct from 'service_role' then
      raise exception 'Service role required' using errcode='42501';
    end if;
    if exists(select 1 from public.admin_user_roles ur join public.admin_roles r on r.id=ur.role_id
      where ur.revoked_at is null and r.name='platform_owner'
        and collect_admin_access.approved_identity(ur.user_id)) then
      raise exception 'An approved Admin already exists' using errcode='42501';
    end if;
  else
    perform public.assert_admin_permission('admin_users.manage');
    if p_user=auth.uid() then
      raise exception 'Another Admin must approve your identity' using errcode='42501';
    end if;
  end if;
  if length(reason_text) not between 1 and 1000
    or phone !~ '^\+[1-9][0-9]{7,14}$'
    or (p_expires_at is not null and p_expires_at <= clock_timestamp()) then
    raise exception 'Verified international WhatsApp number and reason required' using errcode='22023';
  end if;
  perform 1 from auth.users where id=p_user for update;
  if phone is distinct from collect_admin_access.verified_phone(p_user) then
    raise exception 'WhatsApp identity could not be verified' using errcode='22023';
  end if;
  select * into prior from collect_admin_access.whatsapp_approvals where user_id=p_user;
  if prior.user_id is not null and prior.revoked_at is null and prior.phone_e164=phone
    and prior.expires_at is not distinct from p_expires_at
    and (prior.expires_at is null or prior.expires_at > statement_timestamp()) then
    return jsonb_build_object('ok',true,'status','approved','user_id',p_user);
  end if;
  insert into collect_admin_access.whatsapp_approvals(user_id,phone_e164,approved_by,reason,expires_at)
  values(p_user,phone,auth.uid(),reason_text,p_expires_at)
  on conflict(user_id) do update set phone_e164=excluded.phone_e164,
    approved_at=clock_timestamp(),approved_by=excluded.approved_by,reason=excluded.reason,
    expires_at=excluded.expires_at,revoked_at=null,revoked_by=null,revoke_reason=null;
  insert into public.audit_logs(actor_user_id,action,entity_type,entity_id,metadata)
  values(auth.uid(),'admin.whatsapp.approved','profile',p_user,
    jsonb_build_object('phone_masked',public.mask_phone(phone),'reason',reason_text,
      'expires_at',p_expires_at,'service_bootstrap',p_bootstrap));
  -- Approval alone never creates or reactivates an Admin role.
  return jsonb_build_object('ok',true,'status','approved','user_id',p_user);
end;

routine:collect_admin_access.bootstrap_o.source:
declare v_role_id uuid;
begin
 perform public._lock_notification_session_gate();
  perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
  if auth.jwt()->>'role' is distinct from 'service_role' then
    raise exception 'Service role required' using errcode='42501';
  end if;
  if length(btrim(coalesce(p_reason,''))) not between 1 and 1000
    or not collect_admin_access.approved_identity(p_user) then
    raise exception 'Pre-approved verified identity and reason required' using errcode='42501';
  end if;
  select id into v_role_id from public.admin_roles where name='platform_owner';
  if not exists(select 1 from public.admin_user_roles ur where ur.user_id=p_user
    and ur.role_id=v_role_id and ur.revoked_at is null) then
    insert into public.admin_user_roles(user_id,role_id,reason,created_at)
    values(p_user,v_role_id,p_reason,clock_timestamp());
    insert into public.audit_logs(action,entity_type,entity_id,metadata)
    values('admin.bootstrap.platform_owner','profile',p_user,jsonb_build_object('reason',p_reason));
  end if;
  return jsonb_build_object('ok',true);
end;

routine:collect_admin_access.caller_elig.source:
declare session_key text := auth.jwt()->>'session_id';
begin
  if not collect_admin_access.approved_identity(p_user) then return false; end if;
  if auth.jwt()->>'role' = 'service_role' then return true; end if;
  if p_user is distinct from auth.uid() or session_key is null
    or session_key !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
    return false;
  end if;
  return exists(select 1 from auth.sessions s
    join collect_admin_access.whatsapp_approvals a on a.user_id=s.user_id
    where s.id=session_key::uuid and s.user_id=p_user
      and s.created_at >= a.approved_at
      and exists(select 1 from public.admin_user_roles ur join public.admin_roles r on r.id=ur.role_id
        where ur.user_id=p_user and r.name='platform_owner' and ur.revoked_at is null
          and s.created_at >= ur.created_at)
      and (s.not_after is null or s.not_after > statement_timestamp()));
end;

routine:collect_admin_access.current_ide.source:
begin
  if not collect_admin_access.permission_allowed('overview.read',auth.uid()) then return '{}'::jsonb; end if;
  return coalesce((select jsonb_build_object('user_id',p.id,'display_name','Collect ID '||p.public_id,
    'phone_masked',public.mask_phone(collect_admin_access.verified_phone(p.id)),
    'roles','["admin"]'::jsonb,'permissions',(select coalesce(jsonb_agg(rp.permission_name order by rp.permission_name),'[]'::jsonb)
      from public.admin_role_permissions rp join public.admin_roles r on r.id=rp.role_id where r.name='platform_owner'))
    from public.profiles p where p.id=auth.uid()),'{}'::jsonb);
end;

routine:collect_admin_access.get_admin_u.source:
begin
  perform public.assert_admin_permission('admin_users.read');
  return coalesce((select s.state || jsonb_build_object(
    'id',p.id,'public_id',p.public_id,'created_at',p.created_at,
    'status',s.state->>'access_status','whatsapp_approval',s.state->>'status',
    'active_roles',case when (s.state->>'admin_access')::boolean then '["admin"]'::jsonb else '[]'::jsonb end)
    from public.profiles p cross join lateral (select collect_admin_access.account_state(p.id) state) s
    where p.id=p_user and (exists(select 1 from public.admin_user_roles where user_id=p.id)
      or exists(select 1 from collect_admin_access.whatsapp_approvals where user_id=p.id))), '{}'::jsonb);
end;

routine:collect_admin_access.list_admin_.source:
declare result jsonb;
begin
  perform public.assert_admin_permission('admin_users.read');
  with accounts as (
    select p.id,p.public_id,p.created_at,collect_admin_access.account_state(p.id) state
    from public.profiles p where exists(select 1 from public.admin_user_roles where user_id=p.id)
      or exists(select 1 from collect_admin_access.whatsapp_approvals where user_id=p.id)
  ), filtered as (
    select * from accounts where (p_search is null or public_id=p_search
      or state->>'phone_masked' ilike '%'||p_search||'%')
      and (p_status is null or state->>'access_status'=p_status
        or (p_status='admin' and state->>'access_status'='active'))
  ), ordered as (
    select *,row_number() over(order by
      case when p_sort='created_at_asc' then created_at end asc nulls last,created_at desc,id) rank
    from filtered order by rank limit least(greatest(coalesce(p_limit,25),1),100) offset greatest(coalesce(p_offset,0),0)
  )
  select jsonb_build_object('total',(select count(*) from filtered),'rows',coalesce(jsonb_agg(
    public._admin_row(id,'Collect ID '||public_id,'',state->>'access_status','Admin',created_at,
      state || jsonb_build_object('public_id',public_id)) order by rank),'[]'::jsonb)) into result from ordered;
  return result;
end;

routine:collect_admin_access.revoke_what.source:
declare reason_text text := btrim(coalesce(p_reason,''));
begin
 perform public._lock_notification_session_gate();
  perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
  perform public.assert_admin_permission('admin_users.manage');
  if p_user=auth.uid() then
    raise exception 'You cannot revoke your own WhatsApp approval' using errcode='42501';
  end if;
  if length(reason_text) not between 1 and 1000 then
    raise exception 'Reason required' using errcode='22023';
  end if;
  update collect_admin_access.whatsapp_approvals set revoked_at=clock_timestamp(),revoked_by=auth.uid(),revoke_reason=reason_text
    where user_id=p_user and revoked_at is null;
  if found then
    perform collect_admin_access.set_user_access(p_user,false,reason_text);
    insert into public.audit_logs(actor_user_id,action,entity_type,entity_id,metadata)
    values(auth.uid(),'admin.whatsapp.revoked','profile',p_user,jsonb_build_object('reason',reason_text));
  end if;
  return jsonb_build_object('ok',true,'status','revoked','user_id',p_user);
end;

routine:collect_admin_access.set_user_ac.source:
declare v_role_id uuid; reason_text text := btrim(coalesce(p_reason,''));
begin
 perform public._lock_notification_session_gate();
  perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
  perform public.assert_admin_permission('admin_users.manage');
  if p_active is null or length(reason_text) not between 1 and 1000 then
    raise exception 'Active state and reason are required' using errcode='22023';
  end if;
  select id into v_role_id from public.admin_roles where name='platform_owner';
  if v_role_id is null or not exists(select 1 from public.profiles where id=p_user) then
    raise exception 'Admin account unavailable' using errcode='22023';
  end if;
  if p_active then
    perform 1 from auth.users where id=p_user for update;
    if not collect_admin_access.approved_identity(p_user) then
      raise exception 'Pre-approved verified WhatsApp identity required' using errcode='42501';
    end if;
    if not exists(select 1 from public.admin_user_roles ur
      where ur.user_id=p_user and ur.role_id=v_role_id and ur.revoked_at is null) then
      insert into public.admin_user_roles(user_id,role_id,granted_by,reason,created_at)
      values(p_user,v_role_id,auth.uid(),reason_text,clock_timestamp());
      insert into public.audit_logs(actor_user_id,action,entity_type,entity_id,metadata)
      values(auth.uid(),'admin.access.activated','profile',p_user,jsonb_build_object('reason',reason_text));
    end if;
    return jsonb_build_object('ok',true,'status','active');
  end if;
  if p_user=auth.uid() then
    raise exception 'You cannot deactivate your own Admin access' using errcode='42501';
  end if;
  -- The caller is an approved active Admin, so deactivating a different account
  -- cannot remove the last approved Admin. This remains true under the lock.
  update public.admin_user_roles ur set revoked_at=clock_timestamp(),revoked_by=auth.uid(),revoke_reason=reason_text
    where ur.user_id=p_user and ur.revoked_at is null;
  if found then
    insert into public.audit_logs(actor_user_id,action,entity_type,entity_id,metadata)
    values(auth.uid(),'admin.access.deactivated','profile',p_user,jsonb_build_object('reason',reason_text));
  end if;
  return jsonb_build_object('ok',true,'status','revoked');
end;

routine:collect_hybrid._create_roster_im.source:
declare s collect_hybrid.roster_import_sources; result collect_hybrid.roster_import_results;
 fingerprint text; extraction uuid; replayed boolean:=false; ai boolean:=p_source_kind in ('pdf','image');
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'service_role' then raise exception 'roster_service_required' using errcode='42501'; end if;
 perform collect_hybrid.require_roster_actor(p_actor_id,p_session_id);
 if p_request_id is null or p_source_kind is null or p_source_kind not in ('text','csv','txt','xlsx','pdf','image')
   or p_original_sha256 is null or p_original_sha256 !~ '^[a-f0-9]{64}$'
   or p_original_size is null or p_original_size not between 1 and (case when p_source_kind in ('text','csv','txt') then 512000 else 5242880 end)
   or p_client_filename is null or p_client_filename !~ '^[A-Za-z0-9][A-Za-z0-9._ -]{0,159}$'
   or p_declared_mime is null or length(p_declared_mime) not between 1 and 128 or p_declared_mime ~ '[[:cntrl:]]'
   or p_detected_type is null
   or (p_source_kind in ('text','txt') and p_detected_type<>'utf8_text')
   or (p_source_kind='csv' and p_detected_type<>'utf8_csv')
   or (p_source_kind='xlsx' and p_detected_type<>'zip_container')
   or (p_source_kind='pdf' and p_detected_type<>'application/pdf')
   or (p_source_kind='image' and p_detected_type not in ('image/png','image/jpeg','image/webp'))
   or (p_source_kind='xlsx' and (p_derived_sha256 is null or p_derived_sha256 !~ '^[a-f0-9]{64}$' or p_derived_size is null or p_derived_size not between 1 and 512000))
   or (p_source_kind<>'xlsx' and (p_derived_sha256 is not null or p_derived_size is not null))
   or p_ai_consent is distinct from ai
   or (not ai and (p_consent_version is not null or p_ai_metadata is not null)) then
  raise exception 'roster_input_invalid' using errcode='22023'; end if;
 if ai then
  if p_consent_version is distinct from 'roster-ai-extraction-v1' or p_ai_metadata is null
    or jsonb_typeof(p_ai_metadata)<>'object' or p_ai_metadata->>'provider' is distinct from 'openai'
    or p_ai_metadata->>'prompt_version' is distinct from 'roster-extraction-v1'
    or jsonb_typeof(p_ai_metadata->'model') is distinct from 'string'
    or length(btrim(p_ai_metadata->>'model')) not between 1 and 128 or (p_ai_metadata->>'model') ~ '[[:cntrl:]]'
    or exists(select 1 from jsonb_object_keys(p_ai_metadata) k where k not in ('provider','model','prompt_version')) then
   raise exception 'roster_input_invalid' using errcode='22023'; end if;
 end if;
 fingerprint:=collect_hybrid.roster_digest(jsonb_build_array(p_actor_id,p_session_id,p_source_kind,p_original_sha256,p_original_size,
   p_client_filename,p_declared_mime,p_detected_type,p_derived_sha256,p_derived_size,p_ai_consent,p_consent_version,p_ai_metadata));
 select * into s from collect_hybrid.roster_import_sources where request_id=p_request_id;
 if s.id is not null then
  if s.input_sha256<>fingerprint then raise exception 'roster_request_conflict' using errcode='55000'; end if;
  select * into result from collect_hybrid.roster_import_results where import_id=s.id;
  if result.import_id is null then raise exception 'roster_import_in_progress' using errcode='55000'; end if;
  replayed:=true;
 else
  if (select count(*) from collect_hybrid.roster_import_sources where actor_id=p_actor_id and created_at>clock_timestamp()-interval '24 hours')>=100 then
   raise exception 'roster_import_limit' using errcode='55000'; end if;
  insert into collect_hybrid.roster_import_sources(request_id,actor_id,session_id,source_kind,source_sha256,source_size,
   client_filename,declared_mime,detected_type,derived_sha256,derived_size,ai_consent,consent_version,input_sha256)
  values(p_request_id,p_actor_id,p_session_id,p_source_kind,p_original_sha256,p_original_size,p_client_filename,p_declared_mime,
   p_detected_type,p_derived_sha256,p_derived_size,p_ai_consent,p_consent_version,fingerprint) returning * into s;
  if ai then
   insert into collect_hybrid.roster_import_extractions(import_id,actor_id,session_id,provider,model,prompt_version,consent_version)
   values(s.id,p_actor_id,p_session_id,'openai',p_ai_metadata->>'model','roster-extraction-v1',p_consent_version);
  end if;
 end if;
 select id into extraction from collect_hybrid.roster_import_extractions where import_id=s.id;
 return jsonb_build_object('contract_version',1,'ok',true,'request_id',s.request_id,'import_id',s.id,
  'source_sha256',s.source_sha256,'source_size',s.source_size,'source_kind',s.source_kind,'extraction_id',extraction,
  'expires_at',s.expires_at,'derived_sha256',s.derived_sha256,'derived_assurance',case when s.source_kind='xlsx' then 'client_derived_tsv' end,
  'state',coalesce(result.state,'awaiting_preview'),'replayed',replayed,
  'completed_preview',collect_hybrid.roster_revision_receipt(result.revision_id),'error_code',result.error_code);
end

routine:collect_hybrid.add_roster(uuid,j.source:
declare
  row_data jsonb;
  phone text;
  registered_name text;
  display_name text;
  identity_row collect_hybrid.member_momo_identities;
  record_id uuid;
  result_rows jsonb := '[]'::jsonb;
  response jsonb;
  old_batch collect_hybrid.roster_batches;
  input_digest text;
begin
  perform collect_hybrid.assert_onboarding();
  if p_request_id is null
     or p_reason is null
     or char_length(btrim(p_reason)) not between 8 and 500
     or p_rows is null
     or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'Invalid reviewed roster request';
  end if;
  if jsonb_array_length(p_rows) not between 1 and 500 then
    raise exception 'Roster must contain 1 to 500 reviewed rows';
  end if;
  perform 1
  from public.collections collection
  where collection.id = p_collection_id
    and collection.creation_origin = 'admin_assisted'
    and collection.archived_at is null
    and collection.public_status = 'private'
    and not collection.diaspora_enabled
  for update;
  if not found then
    raise exception 'Active private assisted Rwanda group required';
  end if;
  input_digest := encode(extensions.digest(
    p_collection_id::text || p_rows::text || btrim(p_reason),
    'sha256'
  ), 'hex');
  perform pg_advisory_xact_lock(hashtextextended(
    'hybrid-roster:' || p_request_id::text,
    0
  ));
  select batch.* into old_batch
  from collect_hybrid.roster_batches batch
  where batch.request_id = p_request_id;
  if old_batch.request_id is not null then
    if old_batch.input_hash <> input_digest or old_batch.actor_id <> auth.uid() then
      raise exception 'Roster idempotency key conflict';
    end if;
    return old_batch.result || jsonb_build_object('replay', true);
  end if;

  perform pg_advisory_xact_lock(hashtextextended('collect-numeric-member-id', 0));
  for row_data in select value from jsonb_array_elements(p_rows) loop
    if jsonb_typeof(row_data) <> 'object' then
      raise exception 'Invalid roster row';
    end if;
    phone := collect_hybrid.canonical_momo_number(row_data->>'momo_number');
    registered_name := btrim(row_data->>'momo_name');
    display_name := btrim(coalesce(
      nullif(row_data->>'member_name', ''),
      registered_name
    ));
    if phone is null
       or registered_name is null
       or char_length(registered_name) not between 2 and 120
       or display_name is null
       or char_length(display_name) not between 2 and 120
       or registered_name ~ '[[:cntrl:]]'
       or display_name ~ '[[:cntrl:]]' then
      raise exception 'Each row requires a valid full MoMo number and names';
    end if;
    select identity.* into identity_row
    from collect_hybrid.member_momo_identities identity
    where identity.momo_number = phone;
    if identity_row.member_id is not null then
      if identity_row.normalized_name <>
          collect_hybrid.normalize_momo_name(registered_name)
         or identity_row.member_name <> display_name then
        raise exception 'Existing MoMo identity differs; review before updating';
      end if;
      record_id := identity_row.member_id;
      if not exists (
        select 1 from collect_hybrid.member_records member
        where member.id = record_id and member.lifecycle = 'active'
      ) then
        raise exception 'Existing member is inactive';
      end if;
    else
      if exists (
        select 1 from public.profiles profile
        where regexp_replace(coalesce(profile.momo_number, ''), '^0', '+250') = phone
      ) then
        raise exception 'Existing app MoMo number requires reviewed identity linking';
      end if;
      insert into collect_hybrid.member_records(collect_id, origin, created_by)
      values (public.generate_public_id(), 'admin_assisted', auth.uid())
      returning id into record_id;
      insert into collect_hybrid.member_momo_identities(
        member_id,
        member_name,
        momo_name,
        momo_number
      ) values (record_id, display_name, registered_name, phone);
    end if;
    if exists (
      select 1 from public.collection_members membership
      where membership.collection_id = p_collection_id
        and membership.member_record_id = record_id
        and membership.role = 'member'
        and membership.status <> 'active'
    ) then
      raise exception 'Existing membership is not active; review before reactivation';
    end if;
    insert into public.collection_members(
      collection_id,
      member_record_id,
      role,
      status
    ) values (p_collection_id, record_id, 'member', 'active')
    on conflict do nothing;
    result_rows := result_rows || jsonb_build_array(jsonb_build_object(
      'member_id', record_id,
      'collect_id', (
        select member.collect_id
        from collect_hybrid.member_records member
        where member.id = record_id
      )
    ));
  end loop;
  response := jsonb_build_object(
    'ok', true,
    'collection_id', p_collection_id,
    'rows', result_rows,
    'replay', false
  );
  insert into collect_hybrid.roster_batches(
    request_id,
    collection_id,
    actor_id,
    input_hash,
    result
  ) values (p_request_id, p_collection_id, auth.uid(), input_digest, response);
  perform public.create_audit_log(
    'collection.assisted.roster_added',
    'collection',
    p_collection_id,
    jsonb_build_object(
      'reason', btrim(p_reason),
      'request_id', p_request_id,
      'row_count', jsonb_array_length(p_rows)
    )
  );
  return response;
end;

routine:collect_hybrid.admin_commit_rost.source:
declare sid uuid; s collect_hybrid.roster_import_sources; r collect_hybrid.roster_import_revisions;
 prior collect_hybrid.roster_import_commits; fingerprint text; result jsonb; group_result jsonb; roster_result jsonb;
 group_id uuid; title text:=btrim(p_title); reason text:=btrim(p_reason); validation jsonb;
begin
 sid:=collect_hybrid.require_roster_caller();
 if p_request_id is null or p_import_id is null or p_revision_id is null or p_reviewed_rows_sha256 is null
  or p_reviewed_rows_sha256 !~ '^[a-f0-9]{64}$' or p_human_affirmed is distinct from true
  or p_mode is null or p_mode not in ('create','existing') or reason is null or length(reason) not between 8 and 500 or reason ~ '[[:cntrl:]]'
  or (p_mode='create' and (p_collection_id is not null or title is null or length(title) not between 3 and 120 or title ~ '[[:cntrl:]]'))
  or (p_mode='existing' and (p_collection_id is null or p_title is not null)) then
  raise exception 'roster_input_invalid' using errcode='22023'; end if;
 fingerprint:=collect_hybrid.roster_digest(jsonb_build_array(p_import_id,p_revision_id,p_reviewed_rows_sha256,p_human_affirmed,
  p_mode,p_collection_id,title,reason,auth.uid(),sid));
 select * into prior from collect_hybrid.roster_import_commits where request_id=p_request_id;
 if prior.request_id is not null then
  if prior.input_sha256<>fingerprint then raise exception 'roster_request_conflict' using errcode='55000'; end if;
  return prior.response||jsonb_build_object('replayed',true);
 end if;
 select * into s from collect_hybrid.roster_import_sources where id=p_import_id for update;
 if s.id is null or s.actor_id<>auth.uid() or s.session_id<>sid then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 if exists(select 1 from collect_hybrid.roster_import_commits where import_id=s.id) then raise exception 'roster_import_committed' using errcode='55000'; end if;
 if s.expires_at<=clock_timestamp() then raise exception 'roster_import_expired' using errcode='55000'; end if;
 select * into r from collect_hybrid.roster_import_revisions where import_id=s.id order by revision_number desc limit 1;
 if r.id is null or r.id<>p_revision_id or r.processing_method<>'human_review' then raise exception 'roster_revision_superseded' using errcode='55000'; end if;
 validation:=collect_hybrid.roster_preview(r.normalized_rows,true);
 if r.reviewed_rows_sha256<>p_reviewed_rows_sha256 or collect_hybrid.roster_digest(validation->'normalized_rows')<>p_reviewed_rows_sha256 then
  raise exception 'roster_request_conflict' using errcode='55000'; end if;
 begin
 if p_mode='create' then
  group_result:=collect_hybrid.create_assisted_group_with_share(title,reason,gen_random_uuid());
  group_id:=(group_result->>'collection_id')::uuid;
 else
  group_id:=p_collection_id;
  perform 1 from public.collections where id=group_id and currency='RWF' and creation_origin='admin_assisted'
   and archived_at is null and visibility='private' and public_status='private' and not diaspora_enabled for update;
  if not found then raise exception 'roster_collection_unavailable' using errcode='22023'; end if;
 end if;
 insert into public.collection_share_secrets(collection_id,rotated_by) values(group_id,auth.uid()) on conflict(collection_id) do nothing;
 roster_result:=collect_hybrid.add_roster(group_id,r.normalized_rows,gen_random_uuid(),reason);
 exception when sqlstate 'P0001' then
  raise exception 'roster_commit_conflict' using errcode='55000';
 end;
 if roster_result->>'ok' is distinct from 'true' or roster_result->>'collection_id' is distinct from group_id::text
   or jsonb_typeof(roster_result->'rows') is distinct from 'array'
   or jsonb_array_length(roster_result->'rows')<>jsonb_array_length(r.normalized_rows) then
  raise exception 'roster_commit_failed' using errcode='55000'; end if;
 result:=jsonb_build_object('contract_version',1,'ok',true,'request_id',p_request_id,'import_id',s.id,'revision_id',r.id,
  'reviewed_rows_sha256',r.reviewed_rows_sha256,'collection_id',group_id,'mode',p_mode,'roster_count',jsonb_array_length(r.normalized_rows),
  'share_code_ready',exists(select 1 from public.collection_share_secrets where collection_id=group_id),'replayed',false);
 insert into collect_hybrid.roster_import_commits(request_id,import_id,revision_id,collection_id,actor_id,session_id,input_sha256,response)
 values(p_request_id,s.id,r.id,group_id,auth.uid(),sid,fingerprint,result);
 perform public.create_audit_log('roster.import.committed','collection',group_id,jsonb_build_object('request_id',p_request_id,
  'import_id',s.id,'revision_id',r.id,'source_sha256',s.source_sha256,'reviewed_rows_sha256',r.reviewed_rows_sha256,
  'human_affirmed',true,'mode',p_mode,'row_count',jsonb_array_length(r.normalized_rows),'reason',reason));
 return result;
end

routine:collect_hybrid.admin_execute_ros.source:
declare sid uuid; i collect_hybrid.roster_import_recovery_intents; v jsonb; result jsonb; begin
 sid:=collect_hybrid.require_roster_caller();
 if p_human_affirmed is distinct from true then raise exception 'roster_confirmation_required' using errcode='22023'; end if;
 select * into i from collect_hybrid.roster_import_recovery_intents where request_id=p_request_id;
 if i.request_id is null or i.actor_id<>auth.uid() or i.session_id<>sid then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 if i.expires_at<=clock_timestamp() then raise exception 'roster_import_expired' using errcode='55000'; end if;
 if i.payload_sha256 is distinct from p_payload_sha256 then raise exception 'roster_request_conflict' using errcode='55000'; end if;
 v:=collect_hybrid.roster_recovery_payload(i.payload,i.payload_sha256,i.kind);
 if i.kind='review' then
  result:=public.admin_review_roster_import(i.import_id,(v->>'p_parent_revision_id')::uuid,v->'p_rows',v->>'p_reason',i.request_id);
 else
  result:=public.admin_commit_roster_import(i.request_id,i.import_id,(v->>'p_revision_id')::uuid,v->>'p_reviewed_rows_sha256',
   (v->>'p_human_affirmed')::boolean,v->>'p_mode',(v->>'p_collection_id')::uuid,v->>'p_title',v->>'p_reason');
 end if;
 return jsonb_build_object('contract_version',1,'ok',true,'request_id',i.request_id,'import_id',i.import_id,
  'kind',i.kind,'payload_sha256',i.payload_sha256,'result',result);
end

routine:collect_hybrid.admin_get_roster_.source:
declare sid uuid; s collect_hybrid.roster_import_sources; result collect_hybrid.roster_import_results;
 revision uuid; committed jsonb;
begin
 sid:=collect_hybrid.require_roster_caller();
 select * into s from collect_hybrid.roster_import_sources where id=p_import_id;
 if s.id is null or s.actor_id<>auth.uid() or s.session_id<>sid then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 select * into result from collect_hybrid.roster_import_results where import_id=s.id;
 select id into revision from collect_hybrid.roster_import_revisions where import_id=s.id order by revision_number desc limit 1;
 select response into committed from collect_hybrid.roster_import_commits where import_id=s.id;
 return jsonb_build_object('contract_version',1,'ok',true,'import_id',s.id,
  'state',case when committed is not null then 'committed' else coalesce(result.state,'awaiting_preview') end,
  'expires_at',s.expires_at,'preview',collect_hybrid.roster_revision_receipt(revision),'commit',committed,'error_code',result.error_code);
end

routine:collect_hybrid.admin_recover_ros.source:
declare sid uuid; s collect_hybrid.roster_import_sources; i collect_hybrid.roster_import_recovery_intents;
 d collect_hybrid.roster_import_editor_drafts; state jsonb; initial uuid; answer jsonb; intent jsonb; draft jsonb; phase text; begin
 sid:=collect_hybrid.require_roster_caller();
 if p_upload_request_id is null then raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 select * into s from collect_hybrid.roster_import_sources where request_id=p_upload_request_id for update;
 if s.id is null then
  -- No file bytes or unsent content can be reconstructed from this reference.
  return jsonb_build_object('contract_version',1,'ok',true,'upload_request_id',p_upload_request_id,
   'import_id',null,'source_sha256',null,'state','missing_source','initial_preview',null,'status',null,
   'requested_intent_id',p_pending_request_id,'intent',null,'draft',null);
 end if;
 if s.actor_id<>auth.uid() or s.session_id<>sid then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 state:=public.admin_get_roster_import(s.id);
 phase:=state->>'state';
 select id into initial from collect_hybrid.roster_import_revisions where import_id=s.id and revision_number=1;
 if p_pending_request_id is not null then
  select * into i from collect_hybrid.roster_import_recovery_intents where request_id=p_pending_request_id;
  if i.request_id is not null then
   if i.import_id<>s.id or i.actor_id<>auth.uid() or i.session_id<>sid then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
   if i.kind='review' then select collect_hybrid.roster_revision_receipt(id) into answer from collect_hybrid.roster_import_revisions where request_id=i.request_id;
   else select response into answer from collect_hybrid.roster_import_commits where request_id=i.request_id; end if;
   intent:=jsonb_build_object('request_id',i.request_id,'kind',i.kind,'payload_sha256',i.payload_sha256,
    'payload',case when i.expires_at>clock_timestamp() then i.payload else null end,'result',answer,
    'expired',i.expires_at<=clock_timestamp());
  end if;
 end if;
 if s.expires_at<=clock_timestamp() and phase<>'committed' then
  -- Original142 provenance remains intact, but expired recovery must not reopen editor rows.
  phase:='expired'; state:=null; initial:=null; intent:=null;
 else
  select * into d from collect_hybrid.roster_import_editor_drafts where import_id=s.id and expires_at>clock_timestamp();
  if d.import_id is not null then
   draft:=jsonb_build_object('checkpoint_id',d.checkpoint_id,'payload_sha256',d.payload_sha256,'payload',d.payload);
  end if;
 end if;
 return jsonb_build_object('contract_version',1,'ok',true,'upload_request_id',s.request_id,'import_id',s.id,
  'source_sha256',s.source_sha256,'state',phase,'initial_preview',collect_hybrid.roster_revision_receipt(initial),'status',state,
  'requested_intent_id',p_pending_request_id,'intent',intent,'draft',draft);
end

routine:collect_hybrid.admin_review_rost.source:
declare sid uuid; s collect_hybrid.roster_import_sources; parent collect_hybrid.roster_import_revisions;
 prior collect_hybrid.roster_import_revisions; preview jsonb; fingerprint text; revision uuid; reason text:=btrim(p_reason);
begin
 sid:=collect_hybrid.require_roster_caller();
 if p_request_id is null or p_parent_revision_id is null or reason is null or length(reason) not between 8 and 500 or reason ~ '[[:cntrl:]]' then
  raise exception 'roster_input_invalid' using errcode='22023'; end if;
 select * into s from collect_hybrid.roster_import_sources where id=p_import_id for update;
 if s.id is null or s.actor_id<>auth.uid() or s.session_id<>sid then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 preview:=collect_hybrid.roster_preview(p_rows,true);
 fingerprint:=collect_hybrid.roster_digest(jsonb_build_array(s.id,p_parent_revision_id,preview->'normalized_rows',reason,auth.uid(),sid));
 select * into prior from collect_hybrid.roster_import_revisions where request_id=p_request_id;
 if prior.id is not null then
  if prior.input_sha256<>fingerprint then raise exception 'roster_request_conflict' using errcode='55000'; end if;
  return collect_hybrid.roster_revision_receipt(prior.id);
 end if;
 if exists(select 1 from collect_hybrid.roster_import_commits where import_id=s.id) then raise exception 'roster_import_committed' using errcode='55000'; end if;
 if s.expires_at<=clock_timestamp() then raise exception 'roster_import_expired' using errcode='55000'; end if;
 select * into parent from collect_hybrid.roster_import_revisions where import_id=s.id order by revision_number desc limit 1;
 if parent.id is null or parent.id<>p_parent_revision_id then raise exception 'roster_revision_superseded' using errcode='55000'; end if;
 if parent.revision_number>=20 then raise exception 'roster_revision_limit' using errcode='55000'; end if;
 insert into collect_hybrid.roster_import_revisions(import_id,parent_revision_id,extraction_id,revision_number,request_id,
  actor_id,session_id,processing_method,preview,normalized_rows,reviewed_rows_sha256,input_sha256,reason)
 values(s.id,parent.id,parent.extraction_id,parent.revision_number+1,p_request_id,auth.uid(),sid,'human_review',preview,
  preview->'normalized_rows',collect_hybrid.roster_digest(preview->'normalized_rows'),fingerprint,reason) returning id into revision;
 perform public.create_audit_log('roster.import.reviewed','roster_import',s.id,
  jsonb_build_object('revision_id',revision,'parent_revision_id',parent.id,'request_id',p_request_id,'row_count',preview->'row_count','reason',reason));
 return collect_hybrid.roster_revision_receipt(revision);
end

routine:collect_hybrid.admin_save_roster.source:
declare sid uuid; s collect_hybrid.roster_import_sources; d collect_hybrid.roster_import_editor_drafts; v jsonb; latest uuid; begin
 sid:=collect_hybrid.require_roster_caller();
 select * into s from collect_hybrid.roster_import_sources where id=p_import_id for update;
 if s.id is null or s.actor_id<>auth.uid() or s.session_id<>sid then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 if s.expires_at<=clock_timestamp() then raise exception 'roster_import_expired' using errcode='55000'; end if;
 if p_checkpoint_id is null then raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 v:=collect_hybrid.roster_recovery_payload(p_payload,p_payload_sha256,'draft');
 select * into d from collect_hybrid.roster_import_editor_drafts where import_id=s.id for update;
 if d.checkpoint_id=p_checkpoint_id then
  if d.payload<>p_payload or d.payload_sha256<>p_payload_sha256 then raise exception 'roster_request_conflict' using errcode='55000'; end if;
 else
  if d.checkpoint_id is distinct from p_previous_checkpoint_id then raise exception 'roster_draft_superseded' using errcode='55000'; end if;
  if exists(select 1 from collect_hybrid.roster_import_commits where import_id=s.id) then raise exception 'roster_import_committed' using errcode='55000'; end if;
  if d.import_id is null and ((select count(*) from collect_hybrid.roster_import_editor_drafts where actor_id=auth.uid() and expires_at>clock_timestamp())>=40
    or (select count(*) from collect_hybrid.roster_import_editor_drafts where session_id=sid and expires_at>clock_timestamp())>=20) then raise exception 'roster_recovery_limit' using errcode='55000'; end if;
  select id into latest from collect_hybrid.roster_import_revisions where import_id=s.id order by revision_number desc limit 1;
  if latest is null or latest::text<>v->>'parent_revision_id' then raise exception 'roster_revision_superseded' using errcode='55000'; end if;
  insert into collect_hybrid.roster_import_editor_drafts(import_id,checkpoint_id,actor_id,session_id,payload,payload_sha256,expires_at)
   values(s.id,p_checkpoint_id,auth.uid(),sid,p_payload,p_payload_sha256,s.expires_at)
   on conflict(import_id) do update set checkpoint_id=excluded.checkpoint_id,payload=excluded.payload,
    payload_sha256=excluded.payload_sha256,updated_at=clock_timestamp();
 end if;
 return jsonb_build_object('contract_version',1,'ok',true,'import_id',s.id,'checkpoint_id',p_checkpoint_id,
  'payload_sha256',p_payload_sha256,'expires_at',s.expires_at);
end

routine:collect_hybrid.admin_stage_roste.source:
declare sid uuid; s collect_hybrid.roster_import_sources; prior collect_hybrid.roster_import_recovery_intents; v jsonb; begin
 sid:=collect_hybrid.require_roster_caller();
 select * into s from collect_hybrid.roster_import_sources where id=p_import_id for update;
 if s.id is null or s.actor_id<>auth.uid() or s.session_id<>sid then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 if p_request_id is null or p_kind not in ('review','commit') or p_kind is null then raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 v:=collect_hybrid.roster_recovery_payload(p_payload,p_payload_sha256,p_kind);
 if v->>'p_request_id' is distinct from p_request_id::text or v->>'p_import_id' is distinct from s.id::text then
  raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 select * into prior from collect_hybrid.roster_import_recovery_intents where request_id=p_request_id;
 if s.expires_at<=clock_timestamp() then raise exception 'roster_import_expired' using errcode='55000'; end if;
 if prior.request_id is not null then
  if prior.actor_id<>auth.uid() or prior.session_id<>sid or prior.import_id<>s.id or prior.kind<>p_kind
   or prior.payload<>p_payload or prior.payload_sha256<>p_payload_sha256 then raise exception 'roster_request_conflict' using errcode='55000'; end if;
 else
  if s.expires_at<=clock_timestamp() then raise exception 'roster_import_expired' using errcode='55000'; end if;
  if exists(select 1 from collect_hybrid.roster_import_commits where import_id=s.id) then raise exception 'roster_import_committed' using errcode='55000'; end if;
  if (select count(*) from collect_hybrid.roster_import_recovery_intents where import_id=s.id)>=40
   or (select count(*) from collect_hybrid.roster_import_recovery_intents where actor_id=auth.uid() and expires_at>clock_timestamp())>=200
   or (select count(*) from collect_hybrid.roster_import_recovery_intents where session_id=sid and expires_at>clock_timestamp())>=100 then raise exception 'roster_recovery_limit' using errcode='55000'; end if;
  -- Staging is storage only. Frozen142 validates all authority and rows at execution.
  insert into collect_hybrid.roster_import_recovery_intents(request_id,import_id,actor_id,session_id,kind,payload,payload_sha256,expires_at)
   values(p_request_id,s.id,auth.uid(),sid,p_kind,p_payload,p_payload_sha256,s.expires_at);
 end if;
 return jsonb_build_object('contract_version',1,'ok',true,'import_id',s.id,'request_id',p_request_id,'kind',p_kind,
  'payload_sha256',p_payload_sha256,'expires_at',s.expires_at);
end

routine:collect_hybrid.assert_momo_journ.source:
declare
  target_entry_id uuid;
  entry_amount bigint;
  debit_total bigint;
  credit_total bigint;
  line_count integer;
begin
  if tg_table_name = 'momo_journal_entries' then
    target_entry_id := new.id;
  else
    target_entry_id := new.journal_entry_id;
  end if;
  select entry.amount_rwf into entry_amount
  from collect_hybrid.momo_journal_entries entry
  where entry.id = target_entry_id;
  select
    coalesce(sum(line.amount_rwf) filter (where line.direction = 'debit'), 0),
    coalesce(sum(line.amount_rwf) filter (where line.direction = 'credit'), 0),
    count(*)
  into debit_total, credit_total, line_count
  from collect_hybrid.momo_journal_lines line
  where line.journal_entry_id = target_entry_id;
  if line_count <> 2 or debit_total <> entry_amount or credit_total <> entry_amount then
    raise exception 'MoMo journal entry must contain exactly one balanced debit and credit';
  end if;
  return new;
end;

