routine:collect_hybrid.bank_scheduler_re.source:
declare
  canonical_command constant text := $command$select public.run_daily_bank_reconciliation(current_date, 'scheduled daily reconciliation');$command$;
  candidate record;
  launcher record;
  history_count bigint;
  history_hash text;
  nonterminal bigint;
  live_commands bigint;
  cron_zone text := current_setting('cron.timezone', true);
  observed timestamptz := clock_timestamp();
  local_time time;
begin
  if current_user not in ('postgres', 'supabase_admin')
    or not exists (select 1 from pg_catalog.pg_roles where rolname = current_user and (rolsuper or rolbypassrls)) then
    raise exception 'bank_scheduler_owner_required' using errcode = '42501';
  end if;
  if current_setting('transaction_isolation') <> 'serializable' then
    raise exception 'bank_scheduler_serializable_required' using errcode = '25001';
  end if;
  if not pg_catalog.pg_has_role(current_user, 'pg_read_all_stats', 'USAGE')
    and not exists (select 1 from pg_catalog.pg_roles where rolname = current_user and rolsuper) then
    raise exception 'bank_scheduler_stats_visibility_required' using errcode = '42501';
  end if;
  perform pg_catalog.set_config('row_security', 'off', true);
  if (select extversion from pg_catalog.pg_extension where extname = 'pg_cron') is distinct from '1.6.4'
    or current_setting('cron.log_run', true) is distinct from 'on'
    or cron_zone is null or cron_zone not in ('GMT', 'UTC', 'Etc/UTC') then
    raise exception 'bank_scheduler_runtime_review_required' using errcode = '55000';
  end if;
  -- Daily fixed UTC schedule. A five-minute margin excludes launch/catch-up
  -- boundaries. No canonical run can still be recent, queued or executing.
  local_time := (observed at time zone cron_zone)::time;
  if local_time >= time '21:25:00' and local_time <= time '21:35:00' then
    raise exception 'bank_scheduler_schedule_window' using errcode = '55000';
  end if;
  if (select count(*) from cron.job where jobname = 'collect-daily-bank-reconciliation') <> 1 then
    raise exception 'bank_scheduler_identity_review_required' using errcode = '55000';
  end if;
  select * into strict candidate from cron.job where jobname = 'collect-daily-bank-reconciliation';
  if candidate.command is distinct from canonical_command
    or candidate.schedule is distinct from '30 21 * * *'
    or candidate.username is distinct from current_user::text
    or candidate.database is distinct from current_database()
    or candidate.nodename is distinct from 'localhost'
    or candidate.nodeport is distinct from current_setting('port')::integer then
    raise exception 'bank_scheduler_identity_review_required' using errcode = '55000';
  end if;
  if (select count(*) from pg_catalog.pg_stat_activity where backend_type = 'pg_cron launcher') <> 1 then
    raise exception 'bank_scheduler_launcher_review_required' using errcode = '55000';
  end if;
  select pid, backend_start into strict launcher from pg_catalog.pg_stat_activity where backend_type = 'pg_cron launcher';
  select count(*), encode(extensions.digest(coalesce(string_agg(hashes.h, '' order by hashes.h), ''), 'sha256'), 'hex')
    into history_count, history_hash
    from (select encode(extensions.digest(to_jsonb(d)::text, 'sha256'), 'hex') h from cron.job_run_details d where d.jobid = candidate.jobid) hashes;
  select count(*) into nonterminal from cron.job_run_details d where d.jobid = candidate.jobid
    and (d.end_time is null or d.status is null or d.status not in ('succeeded', 'failed'));
  select count(*) into live_commands from pg_catalog.pg_stat_activity a
    where a.pid <> pg_catalog.pg_backend_pid() and a.datname = current_database()
      and a.state is distinct from 'idle' and a.query ~* '^\s*(select|call)\s+(public\.)?run_daily_bank_reconciliation\s*\(';
  if nonterminal <> 0 or live_commands <> 0 or exists (
    select 1 from cron.job_run_details d where d.jobid = candidate.jobid
      and greatest(d.start_time, d.end_time) > observed - interval '5 minutes'
  ) then
    raise exception 'bank_scheduler_drain_required' using errcode = '55000';
  end if;
  return jsonb_build_object('contract_version', 2, 'job_id', candidate.jobid,
    'active', candidate.active, 'job_owner', candidate.username,
    'metadata_sha256', encode(extensions.digest(to_jsonb(candidate)::text, 'sha256'), 'hex'),
    'observed_at', observed, 'observed_by', current_user,
    'cron_timezone', cron_zone, 'log_run', true,
    'launcher_pid', launcher.pid, 'launcher_started_at', launcher.backend_start,
    'history_rows', history_count, 'history_sha256', history_hash,
    'nonterminal_runs', nonterminal, 'live_bank_commands', live_commands);
end;

routine:collect_hybrid.bind_app_membersh.source:
declare registered_id uuid;
begin
  if new.user_id is not null then
    select id into registered_id from collect_hybrid.member_records where linked_user_id = new.user_id;
    if registered_id is null or (new.member_record_id is not null and new.member_record_id <> registered_id) then
      raise exception 'Membership account and record do not match';
    end if;
    new.member_record_id := registered_id;
  end if;
  return new;
end;

routine:collect_hybrid.bind_payment_chil.source:
declare expected_member_id uuid;
begin
  select payment.member_record_id into expected_member_id
  from public.payments payment
  where payment.id = new.payment_id;
  if not found then raise exception 'Payment required'; end if;
  if new.member_record_id is not null
     and new.member_record_id is distinct from expected_member_id then
    raise exception 'Payment child member record does not match payment';
  end if;
  new.member_record_id := expected_member_id;
  return new;
end;

routine:collect_hybrid.bind_payment_memb.source:
declare
  resolved_member_id uuid;
  resolved_collect_id char(6);
begin
  if new.member_record_id is null and new.contributor_user_id is not null then
    select member.id, member.collect_id
    into resolved_member_id, resolved_collect_id
    from collect_hybrid.member_records member
    where member.linked_user_id = new.contributor_user_id
      and member.lifecycle = 'active';
  elsif new.member_record_id is null and new.contributor_public_id is not null then
    select member.id, member.collect_id
    into resolved_member_id, resolved_collect_id
    from collect_hybrid.member_records member
    where member.collect_id = new.contributor_public_id
      and member.lifecycle = 'active';
  elsif new.member_record_id is not null then
    select member.id, member.collect_id
    into resolved_member_id, resolved_collect_id
    from collect_hybrid.member_records member
    where member.id = new.member_record_id
      and member.lifecycle = 'active';
  end if;

  if new.member_record_id is not null and resolved_member_id is null then
    raise exception 'Active member record required';
  end if;
  if resolved_member_id is not null then
    if new.contributor_user_id is not null
       and not collect_hybrid.member_record_belongs_to_user(
         resolved_member_id, new.contributor_user_id
       ) then
      raise exception 'Payment account and member record do not match';
    end if;
    if new.contributor_public_id is not null
       and new.contributor_public_id <> resolved_collect_id then
      raise exception 'Payment Collect ID and member record do not match';
    end if;
    new.member_record_id := resolved_member_id;
    new.contributor_public_id := coalesce(
      new.contributor_public_id, resolved_collect_id
    );
  end if;
  return new;
end;

routine:collect_hybrid.canonical_momo_nu.source:
declare clean text := regexp_replace(btrim(value), '[[:space:]-]', '', 'g');
begin
  if clean ~ '^07[2389][0-9]{7}$' then return '+250' || substr(clean, 2); end if;
  if clean ~ '^\+2507[2389][0-9]{7}$' then return clean; end if;
  raise exception 'Invalid Rwanda MoMo number';
end;

routine:collect_hybrid.claim_verified_cu.source:
declare
  actor uuid := auth.uid();
  verified_phone text;
  phone_hash text;
  identity collect_hybrid.member_momo_identities;
  member collect_hybrid.member_records;
  existing collect_hybrid.member_account_claims;
  updated_payments integer := 0;
  suppressed_jobs integer := 0;
begin
  if actor is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  if not coalesce((
    select flag.enabled from public.feature_flags flag
    where flag.key = 'hybrid_verified_account_claim'
  ), false) then
    raise exception 'Verified offline-member account claiming is disabled';
  end if;
  verified_phone := collect_admin_access.verified_phone(actor);
  if verified_phone is null
     or verified_phone !~ '^\+2507[2389][0-9]{7}$' then
    return jsonb_build_object('ok', true, 'status', 'no_match');
  end if;
  phone_hash := encode(extensions.digest(verified_phone, 'sha256'), 'hex');
  perform pg_advisory_xact_lock(hashtextextended(
    'hybrid-account-claim:' || phone_hash, 0
  ));
  select item.* into identity
  from collect_hybrid.member_momo_identities item
  where item.momo_number = verified_phone
  for update;
  if identity.member_id is null then
    return jsonb_build_object('ok', true, 'status', 'no_match');
  end if;
  select item.* into member
  from collect_hybrid.member_records item
  where item.id = identity.member_id
  for update;
  if member.id is null or member.lifecycle <> 'active' then
    raise exception 'Matching member record requires review';
  end if;
  if member.linked_user_id = actor then
    return jsonb_build_object(
      'ok', true, 'status', 'already_linked', 'collect_id', member.collect_id
    );
  end if;
  if member.linked_user_id is not null then
    raise exception 'Matching member record is linked to another account';
  end if;
  select claim.* into existing
  from collect_hybrid.member_account_claims claim
  where claim.member_record_id = member.id
  for update;
  if existing.user_id = actor
     and existing.identity_revision = identity.revision
     and existing.verified_phone_sha256 = phone_hash then
    return jsonb_build_object(
      'ok', true, 'status', 'already_claimed',
      'member_record_id', member.id, 'collect_id', member.collect_id
    );
  end if;
  if existing.user_id is not null then
    raise exception 'Matching member record is claimed by another account';
  end if;
  if exists (
    select 1 from collect_hybrid.member_account_claims claim
    where claim.user_id = actor and claim.member_record_id <> member.id
  ) then
    raise exception 'Account already claims another member record';
  end if;
  insert into collect_hybrid.member_account_claims(
    member_record_id, user_id, verified_phone_sha256, identity_revision
  ) values (
    member.id, actor, phone_hash, identity.revision
  )
  on conflict (member_record_id) do update
  set user_id = excluded.user_id,
      verified_phone_sha256 = excluded.verified_phone_sha256,
      identity_revision = excluded.identity_revision,
      claim_revision = collect_hybrid.member_account_claims.claim_revision + 1,
      last_claimed_at = clock_timestamp();

  -- Linking identity is not a financial posting. Existing immutable payment,
  -- journal and balance rows stay in place; only their nullable account pointer
  -- is attached so app notifications and own-history privacy work normally.
  update public.payments payment
  set contributor_user_id = actor
  where payment.member_record_id = member.id
    and payment.contributor_user_id is null;
  get diagnostics updated_payments = row_count;

  update collect_hybrid.sms_notification_outbox job
  set state = 'suppressed',
      suppression_reason = 'Member authenticated the app with the exact verified MoMo number',
      claim_token = null,
      claimed_by = null,
      claim_expires_at = null
  where job.member_record_id = member.id
    and job.state in ('queued', 'awaiting_confirmation');
  get diagnostics suppressed_jobs = row_count;

  perform public.create_audit_log(
    'member.offline_account.claimed', 'member_record', member.id,
    jsonb_build_object(
      'collect_id', member.collect_id,
      'identity_revision', identity.revision,
      'verified_phone_sha256', phone_hash,
      'payments_attached', updated_payments,
      'sms_jobs_suppressed', suppressed_jobs
    ),
    actor
  );
  return jsonb_build_object(
    'ok', true, 'status', 'claimed',
    'member_record_id', member.id, 'collect_id', member.collect_id,
    'payments_attached', updated_payments,
    'sms_jobs_suppressed', suppressed_jobs
  );
end;

routine:collect_hybrid.complete_roster_i.source:
declare s collect_hybrid.roster_import_sources; prior collect_hybrid.roster_import_results; preview jsonb;
 fingerprint text; revision uuid; extraction uuid; method text;
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'service_role' then raise exception 'roster_service_required' using errcode='42501'; end if;
 perform collect_hybrid.require_roster_actor(p_actor_id,p_session_id);
 select * into s from collect_hybrid.roster_import_sources where id=p_import_id for update;
 if s.id is null or s.actor_id<>p_actor_id or s.session_id<>p_session_id then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 method:=case when s.ai_consent then 'openai_structured_extraction' else 'deterministic' end;
 if p_processing_metadata is null or jsonb_typeof(p_processing_metadata)<>'object'
  or p_processing_metadata->>'processing_method' is distinct from method
  or not (p_processing_metadata ?& array['processing_method','provider_response_sha256','provider_response_id'])
  or exists(select 1 from jsonb_object_keys(p_processing_metadata) k where k not in ('processing_method','provider_response_sha256','provider_response_id'))
  or (not s.ai_consent and (p_processing_metadata->>'provider_response_sha256' is not null or p_processing_metadata->>'provider_response_id' is not null))
  or (s.ai_consent and (jsonb_typeof(p_processing_metadata->'provider_response_sha256') is distinct from 'string'
    or (p_processing_metadata->>'provider_response_sha256') !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_processing_metadata->'provider_response_id') is distinct from 'string'
    or length(p_processing_metadata->>'provider_response_id') not between 1 and 256
    or (p_processing_metadata->>'provider_response_id') ~ '[[:cntrl:]]')) then
  raise exception 'roster_input_invalid' using errcode='22023'; end if;
 preview:=collect_hybrid.roster_preview(p_candidates,false);
 fingerprint:=collect_hybrid.roster_digest(jsonb_build_array(p_candidates,p_processing_metadata));
 select * into prior from collect_hybrid.roster_import_results where import_id=s.id;
 if prior.import_id is not null then
  if prior.state<>'preview_ready' or prior.input_sha256<>fingerprint then raise exception 'roster_request_conflict' using errcode='55000'; end if;
  return collect_hybrid.roster_revision_receipt(prior.revision_id);
 end if;
 if s.expires_at<=clock_timestamp() then raise exception 'roster_import_expired' using errcode='55000'; end if;
 select id into extraction from collect_hybrid.roster_import_extractions where import_id=s.id;
 insert into collect_hybrid.roster_import_revisions(import_id,extraction_id,revision_number,actor_id,session_id,processing_method,
  preview,normalized_rows,reviewed_rows_sha256,input_sha256)
 values(s.id,extraction,1,p_actor_id,p_session_id,method,preview,preview->'normalized_rows',
  collect_hybrid.roster_digest(preview->'normalized_rows'),fingerprint) returning id into revision;
 insert into collect_hybrid.roster_import_results(import_id,actor_id,session_id,state,revision_id,processing_metadata,input_sha256)
 values(s.id,p_actor_id,p_session_id,'preview_ready',revision,p_processing_metadata,fingerprint);
 return collect_hybrid.roster_revision_receipt(revision);
end

routine:collect_hybrid.create_assisted_g.source:
declare
  group_id uuid; clean_title text := btrim(p_title); input_digest text; response jsonb;
  prior collect_hybrid.group_creation_requests;
begin
  perform collect_hybrid.assert_onboarding();
  if p_request_id is null or clean_title is null or char_length(clean_title) not between 3 and 120
    or p_reason is null or char_length(btrim(p_reason)) not between 8 and 500 then
    raise exception 'Invalid group name or audit reason';
  end if;
  input_digest := encode(extensions.digest(jsonb_build_array(clean_title, btrim(p_reason))::text, 'sha256'), 'hex');
  perform pg_advisory_xact_lock(hashtextextended('hybrid-group-create:' || p_request_id::text, 0));
  select * into prior from collect_hybrid.group_creation_requests where request_id=p_request_id;
  if prior.request_id is not null then
    if prior.actor_id <> auth.uid() or prior.input_hash <> input_digest then raise exception 'Group idempotency key conflict'; end if;
    return prior.result || jsonb_build_object('replay', true);
  end if;
  -- Draft private savings group; no guessed/default payee and no fake owner account.
  insert into public.collections(slug, creator_user_id, title, category, visibility, public_status,
    collection_type, contribution_visibility, allow_anonymous, diaspora_enabled, creation_origin)
  values ('assisted-' || replace(gen_random_uuid()::text, '-', ''), auth.uid(), clean_title,
    'Family / friends', 'private', 'private', 'ikimina', 'members', false, false, 'admin_assisted')
  returning id into group_id;
  insert into public.collection_members(collection_id, user_id, role, status)
  values (group_id, auth.uid(), 'owner', 'active');
  perform public.create_audit_log('collection.assisted.created', 'collection', group_id,
    jsonb_build_object('reason', btrim(p_reason), 'route_ready', false));
  response := jsonb_build_object('ok', true, 'collection_id', group_id, 'visibility', 'private', 'route_ready', false, 'replay', false);
  insert into collect_hybrid.group_creation_requests(request_id, actor_id, input_hash, collection_id, result)
  values (p_request_id, auth.uid(), input_digest, group_id, response);
  return response;
end;

declare
  result jsonb;
  group_id uuid;
begin
  result := collect_hybrid.create_assisted_group(
    p_title,
    p_reason,
    p_request_id
  );
  group_id := (result->>'collection_id')::uuid;
  insert into public.collection_share_secrets(collection_id, rotated_by)
  values (group_id, auth.uid())
  on conflict (collection_id) do nothing;
  return result || jsonb_build_object('share_code_ready', true);
end;

routine:collect_hybrid.create_roster_imp.source:
declare r collect_hybrid.roster_resource_reservations;
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'service_role' then raise exception 'roster_service_required' using errcode='42501'; end if;
 perform collect_hybrid.require_roster_actor(p_actor_id,p_session_id);
 if not exists(select 1 from collect_hybrid.roster_import_sources where request_id=p_request_id) then
  select * into r from collect_hybrid.roster_resource_reservations where request_id=p_request_id for update;
  if r.id is null or r.actor_id<>p_actor_id or r.session_id<>p_session_id or r.source_sha256<>p_original_sha256
   or r.source_kind<>p_source_kind or r.source_bytes<>p_original_size or r.derived_sha256 is distinct from p_derived_sha256
   or r.expires_at<=clock_timestamp() or exists(select 1 from collect_hybrid.roster_resource_completions where reservation_id=r.id) then
