routine:collect_hybrid.enqueue_sms_recei.source:
declare
  payment public.payments;
  member collect_hybrid.member_records;
  identity collect_hybrid.member_momo_identities;
  policy collect_hybrid.sms_receipt_policies;
  consent collect_hybrid.sms_receipt_member_consents;
  message text;
  reference_value text;
begin
  if new.event_type <> 'receipt' or new.member_record_id is null
     or new.member_balance_after_rwf is null then
    return new;
  end if;
  if not coalesce((
    select flag.enabled from public.feature_flags flag
    where flag.key = 'hybrid_sms_notifications'
  ), false) then
    return new;
  end if;
  select item.* into policy
  from collect_hybrid.sms_receipt_policies item
  where item.collection_id = new.collection_id and item.enabled;
  if policy.collection_id is null then return new; end if;
  select item.* into payment from public.payments item where item.id = new.payment_id;
  select item.* into member
  from collect_hybrid.member_records item
  where item.id = new.member_record_id and item.lifecycle = 'active';
  if payment.id is null or payment.status <> 'posted' or member.id is null then
    return new;
  end if;
  -- App-linked members already use the existing contribution-confirmed push
  -- pipeline. SMS is reserved for account-independent members.
  if member.linked_user_id is not null then return new; end if;
  select item.* into identity
  from collect_hybrid.member_momo_identities item
  where item.member_id = member.id;
  if identity.member_id is null then return new; end if;
  select item.* into consent
  from collect_hybrid.sms_receipt_member_consents item
  where item.member_record_id = member.id and item.enabled;
  if consent.member_record_id is null then return new; end if;
  reference_value := btrim(coalesce(payment.transaction_id, ''));
  if reference_value !~ '^[A-Za-z0-9][A-Za-z0-9._/-]{0,63}$' then
    insert into collect_hybrid.sms_notification_outbox(
      payment_id, snapshot_id, collection_id, member_record_id,
      destination_e164, destination_sha256, destination_revision,
      policy_revision, consent_revision, template_key, template_version, amount_rwf,
      member_balance_rwf, group_balance_rwf, reference, state,
      suppression_reason
    ) values (
      payment.id, new.id, new.collection_id, member.id,
      identity.momo_number,
      encode(extensions.digest(identity.momo_number, 'sha256'), 'hex'),
      identity.revision, policy.revision, consent.revision, policy.template_key,
      policy.template_version, payment.amount_rwf,
      new.member_balance_after_rwf, new.group_balance_after_rwf,
      coalesce(nullif(reference_value, ''), 'invalid'), 'suppressed',
      'Provider reference is not safe for the canonical receipt template'
    ) on conflict (payment_id, template_key) do nothing;
    return new;
  end if;
  message := collect_hybrid.render_buri_munsi_receipt(
    payment.amount_rwf, new.member_balance_after_rwf,
    new.group_balance_after_rwf, reference_value
  );
  insert into collect_hybrid.sms_notification_outbox(
    payment_id, snapshot_id, collection_id, member_record_id,
    destination_e164, destination_sha256, destination_revision,
    policy_revision, consent_revision, template_key, template_version, amount_rwf,
    member_balance_rwf, group_balance_rwf, reference,
    message_body, body_sha256
  ) values (
    payment.id, new.id, new.collection_id, member.id,
    identity.momo_number,
    encode(extensions.digest(identity.momo_number, 'sha256'), 'hex'),
    identity.revision, policy.revision, consent.revision, policy.template_key,
    policy.template_version, payment.amount_rwf,
    new.member_balance_after_rwf, new.group_balance_after_rwf,
    reference_value, message,
    encode(extensions.digest(message, 'sha256'), 'hex')
  ) on conflict (payment_id, template_key) do nothing;
  return new;
end;

routine:collect_hybrid.fail_roster_impor.source:
declare s collect_hybrid.roster_import_sources; prior collect_hybrid.roster_import_results; replayed boolean:=false;
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'service_role' then raise exception 'roster_service_required' using errcode='42501'; end if;
 perform collect_hybrid.require_roster_actor(p_actor_id,p_session_id);
 if p_error_code is null or p_error_code not in ('roster_extraction_failed','roster_extraction_timeout','roster_extraction_refused',
  'roster_extraction_incomplete','roster_provider_response_invalid','roster_provider_response_too_large','roster_preview_invalid','roster_extraction_unavailable') then
  raise exception 'roster_input_invalid' using errcode='22023'; end if;
 select * into s from collect_hybrid.roster_import_sources where id=p_import_id for update;
 if s.id is null or s.actor_id<>p_actor_id or s.session_id<>p_session_id then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 select * into prior from collect_hybrid.roster_import_results where import_id=s.id;
 if prior.import_id is not null then
  if prior.state<>'failed' or prior.error_code<>p_error_code then raise exception 'roster_request_conflict' using errcode='55000'; end if;
  replayed:=true;
 else
  insert into collect_hybrid.roster_import_results(import_id,actor_id,session_id,state,error_code,input_sha256)
  values(s.id,p_actor_id,p_session_id,'failed',p_error_code,collect_hybrid.roster_digest(to_jsonb(p_error_code)));
 end if;
 return jsonb_build_object('contract_version',1,'ok',true,'import_id',s.id,'state','failed','error_code',p_error_code,'replayed',replayed);
end

routine:collect_hybrid.finish_roster_res.source:
declare r collect_hybrid.roster_resource_reservations; c collect_hybrid.roster_resource_completions;
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'service_role' then raise exception 'roster_service_required' using errcode='42501'; end if;
 perform collect_hybrid.require_roster_actor(p_actor_id,p_session_id);
 select * into r from collect_hybrid.roster_resource_reservations where id=p_reservation_id for update;
 if r.id is null or r.actor_id<>p_actor_id or r.session_id<>p_session_id then raise exception 'roster_resource_unavailable' using errcode='42501'; end if;
 if p_outcome is null or p_outcome not in ('preview_ready','failed','ambiguous') then raise exception 'roster_input_invalid' using errcode='22023'; end if;
 select * into c from collect_hybrid.roster_resource_completions where reservation_id=r.id;
 if c.reservation_id is not null then
  if c.outcome<>p_outcome then raise exception 'roster_request_conflict' using errcode='55000'; end if;
 else
  insert into collect_hybrid.roster_resource_completions values(r.id,p_outcome,clock_timestamp());
 end if;
 return jsonb_build_object('contract_version',1,'ok',true,'reservation_id',r.id,'outcome',p_outcome,'charged',true);
end

