routine:collect_hybrid.reject_bound_prov.source:
declare
  payment_row public.payments;
  prior collect_hybrid.payment_provider_rejections;
  clean_network text := lower(btrim(coalesce(p_provider_network, '')));
  clean_transaction text := upper(btrim(coalesce(p_transaction_id, '')));
  clean_receiver text := lower(btrim(coalesce(p_receiver_momo_number_hash, '')));
  clean_evidence text := nullif(lower(btrim(coalesce(p_evidence_sha256, ''))), '');
  clean_reason text := btrim(coalesce(p_reason, ''));
  clean_reference text := btrim(coalesce(p_provider_reference, ''));
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'Service role required'; end if;
  if p_payment_id is null or char_length(clean_network) not between 2 and 32
     or clean_network !~ '^[a-z0-9_]+$'
     or char_length(clean_transaction) not between 3 and 128
     or clean_receiver !~ '^[0-9a-f]{64}$'
     or p_amount_rwf is null or p_amount_rwf <= 0
     or p_occurred_at is null or not isfinite(p_occurred_at)
     or p_occurred_at > now() + interval '5 minutes'
     or (clean_evidence is not null and clean_evidence !~ '^[0-9a-f]{64}$')
     or char_length(clean_reason) not between 3 and 500
     or char_length(clean_reference) not between 1 and 128 then
    raise exception 'Invalid provider rejection';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('provider-finality-payment:' || p_payment_id::text, 0));
  select payment.* into payment_row from public.payments payment
    where payment.id = p_payment_id for update;
  if payment_row.id is null then raise exception 'Payment not found'; end if;
  if lower(btrim(payment_row.provider_network)) is distinct from clean_network
     or upper(btrim(payment_row.transaction_id)) is distinct from clean_transaction
     or payment_row.receiver_momo_number_hash is distinct from clean_receiver
     or payment_row.amount_rwf is distinct from p_amount_rwf then
    raise exception 'Provider rejection does not match the payment candidate';
  end if;
  if payment_row.status = 'reversed' then
    select rejection.* into prior from collect_hybrid.payment_provider_rejections rejection
      where rejection.payment_id = payment_row.id;
    if prior.payment_id is not null
       and prior.provider_network = clean_network
       and prior.transaction_id = clean_transaction
       and prior.receiver_momo_number_hash = clean_receiver
       and prior.amount_rwf = p_amount_rwf
       and prior.occurred_at = p_occurred_at
       and prior.evidence_sha256 is not distinct from clean_evidence
       and prior.reason = clean_reason and prior.provider_reference = clean_reference then
      return payment_row.id;
    end if;
    raise exception 'Payment was reversed without this provider rejection';
  end if;
  if payment_row.status <> 'review' then raise exception 'Only a review payment can be rejected'; end if;
  if exists(select 1 from public.payment_provider_confirmations where payment_id = payment_row.id)
     or exists(select 1 from public.ledger_entries where payment_id = payment_row.id) then
    raise exception 'Provider rejection cannot compensate posted financial evidence';
  end if;
  insert into collect_hybrid.payment_provider_rejections(
    payment_id, provider_network, transaction_id, receiver_momo_number_hash,
    amount_rwf, occurred_at, evidence_sha256, reason, provider_reference
  ) values (payment_row.id, clean_network, clean_transaction, clean_receiver,
    p_amount_rwf, p_occurred_at, clean_evidence, clean_reason, clean_reference);
  update public.payments set status = 'reversed', posted_at = null where id = payment_row.id;
  update public.parsed_payment_events set allocation_status = 'needs_review',
    review_reason = 'Provider rejected payment candidate: ' || clean_reason
    where id = payment_row.parsed_event_id;
  update public.payment_intents set status = 'cancelled' where id = payment_row.payment_intent_id;
  update collect_hybrid.momo_reconciliation_exceptions set status = 'resolved', resolved_at = now()
    where parsed_event_id = payment_row.parsed_event_id and status = 'open';
  perform public.create_audit_log('payment.provider_rejected', 'payment', payment_row.id,
    jsonb_build_object('reason', clean_reason, 'provider_reference', clean_reference,
      'provider_network', clean_network, 'transaction_id', clean_transaction,
      'occurred_at', p_occurred_at, 'evidence_sha256', clean_evidence, 'ledger_posted', false), null);
  return payment_row.id;
end;

routine:collect_hybrid.require_confirmed.source:
declare
  intent_row public.payment_intents;
  verified_payer_hash text;
  observed_payer_hash text;
begin
  if tg_op = 'UPDATE' then
    if old.payment_intent_id is not null or new.payment_intent_id is not null then
      if new.payment_intent_id is distinct from old.payment_intent_id
         or new.parsed_event_id is distinct from old.parsed_event_id
         or new.contributor_user_id is distinct from old.contributor_user_id
         or new.collection_id is distinct from old.collection_id
         or new.receiver_user_id is distinct from old.receiver_user_id
         or new.receiver_momo_number_hash is distinct from old.receiver_momo_number_hash
         or new.amount_rwf is distinct from old.amount_rwf
         or new.currency is distinct from old.currency
         or new.transaction_id is distinct from old.transaction_id
         or new.provider_network is distinct from old.provider_network
         or new.member_record_id is distinct from old.member_record_id then
        raise exception 'Intent-backed payment attribution is immutable'
          using errcode = '23514';
      end if;
    end if;
  end if;

  if new.status <> 'posted' or new.payment_intent_id is null then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if old.status = 'posted' then return new; end if;
  end if;

  select * into intent_row
  from public.payment_intents
  where id = new.payment_intent_id
  for share;
  if intent_row.id is null
     or new.contributor_user_id is distinct from intent_row.contributor_user_id
     or new.collection_id is distinct from intent_row.collection_id then
    raise exception 'Payment intent attribution requires reconciliation'
      using errcode = '23514';
  end if;

  verified_payer_hash :=
    public._authenticated_momo_phone_hash(intent_row.contributor_user_id);
  select event.sender_phone_hash into observed_payer_hash
  from public.parsed_payment_events event
  where event.id = new.parsed_event_id;
  if verified_payer_hash is null
     or intent_row.sender_phone_hash is distinct from verified_payer_hash
     or observed_payer_hash is distinct from verified_payer_hash
     or exists (
       select 1
       from collect_hybrid.payer_identity_reconciliation review
       where review.payment_id = new.id and review.review_status = 'open'
     ) then
    raise exception 'Confirmed payer identity and SMS sender evidence are required'
      using errcode = '23514';
  end if;
  return new;
end;

routine:collect_hybrid.require_fresh_ros.source:
declare sid uuid; s auth.sessions; exp_epoch numeric; begin
 sid:=collect_hybrid.require_roster_caller();
 select * into s from auth.sessions where id=sid and user_id=auth.uid() for share;
 if s.id is null or s.created_at<clock_timestamp()-interval '10 minutes' or s.created_at>clock_timestamp()
  or jsonb_typeof(auth.jwt()->'exp') is distinct from 'number' then
  raise exception 'roster_fresh_auth_required' using errcode='42501'; end if;
 begin exp_epoch:=(auth.jwt()->>'exp')::numeric; exception when others then
  raise exception 'roster_fresh_auth_required' using errcode='42501'; end;
 if exp_epoch<=extract(epoch from clock_timestamp()) or exp_epoch>253402300799 then
  raise exception 'roster_fresh_auth_required' using errcode='42501'; end if;
 return sid;
end

routine:collect_hybrid.require_interrupt.source:
declare s collect_hybrid.roster_import_sources; new_auth auth.sessions;
 root_source collect_hybrid.roster_import_sources; begin
 select * into s from collect_hybrid.roster_import_sources where id=p_import for update;
 if s.id is null or s.actor_id<>auth.uid() or s.session_id=p_destination then
  raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 perform collect_hybrid.roster_recovery_leaf(s.id,true);
 perform collect_hybrid.require_roster_actor(s.actor_id,p_destination);
 select * into root_source from collect_hybrid.roster_import_sources where id=collect_hybrid.roster_recovery_root(s.id);
 select * into new_auth from auth.sessions where id=p_destination and user_id=s.actor_id;
 if new_auth.id is null or new_auth.created_at<=s.created_at or new_auth.created_at<=root_source.created_at then
  raise exception 'roster_fresh_auth_required' using errcode='42501'; end if;
 if exists(select 1 from collect_hybrid.roster_import_commits where import_id=s.id) then
  raise exception 'roster_import_committed' using errcode='55000'; end if;
 if not exists(select 1 from collect_hybrid.roster_import_revisions where import_id=s.id and revision_number=1) then
  raise exception 'roster_preview_unacknowledged' using errcode='55000'; end if;
 if p_etag is not null and (p_etag !~ '^[a-f0-9]{64}$' or p_etag<>collect_hybrid.roster_interrupted_etag(s.id,p_destination)) then
  raise exception 'roster_draft_superseded' using errcode='55000'; end if;
 return s;
end

routine:collect_hybrid.require_roster_ac.source:
declare enabled_flag boolean; begin
 perform collect_hybrid.require_roster_actor_authority(p_actor,p_session,'platform_owner',array['collections.moderate','users.read']);
 select enabled into enabled_flag from public.feature_flags where key='hybrid_member_onboarding' for share;
 if enabled_flag is distinct from true then raise exception 'roster_feature_disabled' using errcode='55000'; end if;
end

declare u auth.users; s auth.sessions; role_uuid uuid; permission text; begin
 perform public._lock_notification_session_gate();
 perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
 if p_actor is null or p_session is null then raise exception 'roster_session_required' using errcode='42501'; end if;
 if p_role_name is null or p_role_name !~ '^[a-z_]+$' or p_permission_names is null
  or cardinality(p_permission_names) not between 1 and 30
  or exists(select 1 from unnest(p_permission_names) n where n is null or n !~ '^[a-z_]+(\.[a-z_]+)+$') then
  raise exception 'roster_actor_unavailable' using errcode='42501'; end if;
 select * into u from auth.users where id=p_actor for share;
 select * into s from auth.sessions where id=p_session and user_id=p_actor for share;
 if u.id is null or s.id is null or s.created_at is null or not isfinite(s.created_at) or s.created_at>clock_timestamp()
  or s.aal::text not in ('aal1','aal2') or s.aal is null
  or (s.not_after is not null and (not isfinite(s.not_after) or s.not_after<=clock_timestamp()))
  or u.deleted_at is not null or u.phone_confirmed_at is null or coalesce(u.is_anonymous,false)
  or (u.banned_until is not null and u.banned_until>clock_timestamp()) then
  raise exception 'roster_actor_unavailable' using errcode='42501'; end if;
 select r.id into role_uuid from collect_admin_access.whatsapp_approvals a
  join public.admin_user_roles ur on ur.user_id=a.user_id and ur.revoked_at is null
  join public.admin_roles r on r.id=ur.role_id and r.name=p_role_name
  where a.user_id=p_actor and a.revoked_at is null and a.phone_e164='+'||ltrim(u.phone,'+')
   and (a.expires_at is null or a.expires_at>clock_timestamp())
   and s.created_at>=a.approved_at and s.created_at>=ur.created_at
  order by ur.created_at for share of a,ur,r;
 if role_uuid is null then raise exception 'roster_actor_unavailable' using errcode='42501'; end if;
 -- Sorted locks avoid opposite permission-row orders between authority users.
 for permission in select distinct n from unnest(p_permission_names) n order by n loop
  perform 1 from public.admin_role_permissions where role_id=role_uuid and permission_name=permission for share;
  if not found then raise exception 'roster_actor_unavailable' using errcode='42501'; end if;
 end loop;
end

routine:collect_hybrid.require_roster_ca.source:
declare sid text:=auth.jwt()->>'session_id';
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'authenticated' or auth.uid() is null or sid is null
  or sid !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
  raise exception 'roster_session_required' using errcode='42501'; end if;
 perform collect_hybrid.require_roster_actor(auth.uid(),sid::uuid);
 return sid::uuid;
