routine:collect_hybrid.reserve_roster_re.source:
declare r collect_hybrid.roster_resource_reservations; policy collect_hybrid.roster_resource_policy;
 fingerprint text; replayed boolean:=false; finished boolean; cost bigint; boundary timestamptz:=clock_timestamp()-interval '24 hours';
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'service_role' then raise exception 'roster_service_required' using errcode='42501'; end if;
 perform collect_hybrid.require_roster_actor(p_actor_id,p_session_id);
 if p_request_id is null or p_source_sha256 is null or p_source_sha256 !~ '^[a-f0-9]{64}$' or p_source_kind is null
  or p_source_kind not in ('text','csv','txt','xlsx','pdf','image') or p_source_bytes is null or p_source_bytes not between 1 and
  (case when p_source_kind in ('text','csv','txt') then 512000 else 5242880 end)
  or (p_source_kind='xlsx' and (p_derived_sha256 is null or p_derived_sha256 !~ '^[a-f0-9]{64}$'))
  or (p_source_kind<>'xlsx' and p_derived_sha256 is not null) then raise exception 'roster_input_invalid' using errcode='22023'; end if;
 -- Serialize the entire quota decision, not a SELECT followed by a racy insert.
 -- Same Auth-first order as all roster operations. A singleton policy row makes
 -- concurrent actor/global changes atomic and auditable at policy_version.
 -- Same-value UPDATE creates a row-version fence. Under REPEATABLE READ
 -- an old waiter receives40001 instead of counting quota from a stale snapshot.
 update collect_hybrid.roster_resource_policy set version=version where id returning * into strict policy;
 fingerprint:=collect_hybrid.roster_digest(jsonb_build_array(p_actor_id,p_session_id,p_source_sha256,p_source_kind,p_source_bytes,p_derived_sha256));
 select * into r from collect_hybrid.roster_resource_reservations where request_id=p_request_id;
 if r.id is not null then
  if r.input_sha256<>fingerprint then raise exception 'roster_request_conflict' using errcode='55000'; end if;
  select exists(select 1 from collect_hybrid.roster_resource_completions where reservation_id=r.id) into finished;
  if not finished then
   -- Repair a lost cleanup ACK from an already durable preview/failure; never
   -- reacquire or redispatch an unknown decoder/provider attempt.
   insert into collect_hybrid.roster_resource_completions(reservation_id,outcome)
   select r.id,result.state from collect_hybrid.roster_import_sources source
    join collect_hybrid.roster_import_results result on result.import_id=source.id
    where source.request_id=r.request_id and source.actor_id=r.actor_id and source.session_id=r.session_id;
   select exists(select 1 from collect_hybrid.roster_resource_completions where reservation_id=r.id) into finished;
  end if;
  if not finished then
   raise exception 'roster_resource_in_progress' using errcode='55000';
  end if;
  replayed:=true;
 else
  cost:=case when p_source_kind in ('image','pdf') then policy.ai_attempt_cost_units else 0 end;
  if (select count(*) from collect_hybrid.roster_resource_reservations where actor_id=p_actor_id and reserved_at>boundary)>=policy.actor_daily_requests
   or (select coalesce(sum(source_bytes),0) from collect_hybrid.roster_resource_reservations where actor_id=p_actor_id and reserved_at>boundary)+p_source_bytes>policy.actor_daily_bytes
   or (select coalesce(sum(cost_units),0) from collect_hybrid.roster_resource_reservations where actor_id=p_actor_id and reserved_at>boundary)+cost>policy.actor_daily_cost_units
   or (select count(*) from collect_hybrid.roster_resource_reservations where reserved_at>boundary)>=policy.global_daily_requests
   or (select coalesce(sum(source_bytes),0) from collect_hybrid.roster_resource_reservations where reserved_at>boundary)+p_source_bytes>policy.global_daily_bytes
   or (select coalesce(sum(cost_units),0) from collect_hybrid.roster_resource_reservations where reserved_at>boundary)+cost>policy.global_daily_cost_units then
   raise exception 'roster_resource_limit' using errcode='55000'; end if;
  if (select count(*) from collect_hybrid.roster_resource_reservations a where a.actor_id=p_actor_id and a.expires_at>clock_timestamp()
   and not exists(select 1 from collect_hybrid.roster_resource_completions c where c.reservation_id=a.id and c.outcome<>'ambiguous'))>=policy.actor_active
   or (select count(*) from collect_hybrid.roster_resource_reservations a where a.expires_at>clock_timestamp()
   and not exists(select 1 from collect_hybrid.roster_resource_completions c where c.reservation_id=a.id and c.outcome<>'ambiguous'))>=policy.global_active then
   raise exception 'roster_resource_limit' using errcode='55000'; end if;
  insert into collect_hybrid.roster_resource_reservations(request_id,actor_id,session_id,source_sha256,source_kind,source_bytes,
   derived_sha256,input_sha256,cost_units,policy_version,expires_at)
  values(p_request_id,p_actor_id,p_session_id,p_source_sha256,p_source_kind,p_source_bytes,p_derived_sha256,fingerprint,cost,policy.version,
   clock_timestamp()+interval '180 seconds') returning * into r;
  finished:=false;
 end if;
 return jsonb_build_object('contract_version',1,'ok',true,'reservation_id',r.id,'request_id',r.request_id,'actor_id',r.actor_id,
  'session_id',r.session_id,'source_sha256',r.source_sha256,'state',case when finished then 'finished' else 'reserved' end,
  'replayed',replayed,'expires_at',r.expires_at);
end

routine:collect_hybrid.retire_legacy_ban.source:
declare
  before_readback jsonb;
  after_readback jsonb;
  receipt collect_hybrid.legacy_bank_scheduler_retirements%rowtype;
  candidate record;
begin
  perform pg_catalog.pg_advisory_xact_lock(143, 20260930);
  before_readback := collect_hybrid.bank_scheduler_retirement_readback();
  -- Row lock through owner API, never cron DML/table locking. A changed row
  -- after the transaction snapshot causes 40001 and rolls the whole call back.
  perform cron.alter_job((before_readback->>'job_id')::bigint, schedule := '30 21 * * *');
  after_readback := collect_hybrid.bank_scheduler_retirement_readback();
  if before_readback->>'metadata_sha256' is distinct from after_readback->>'metadata_sha256'
    or before_readback->>'history_sha256' is distinct from after_readback->>'history_sha256' then
    raise exception 'bank_scheduler_snapshot_changed' using errcode = '40001';
  end if;
  select * into receipt from collect_hybrid.legacy_bank_scheduler_retirements where job_id = (before_readback->>'job_id')::bigint;
  if found then
    if (after_readback->>'active')::boolean is distinct from false
      or receipt.inactive_metadata_sha256 is distinct from after_readback->>'metadata_sha256'
      or receipt.history_rows is distinct from (after_readback->>'history_rows')::bigint
      or receipt.history_sha256 is distinct from after_readback->>'history_sha256'
      or receipt.cron_timezone is distinct from after_readback->>'cron_timezone'
      or receipt.launcher_pid is distinct from (after_readback->>'launcher_pid')::integer
      or receipt.launcher_started_at is distinct from (after_readback->>'launcher_started_at')::timestamptz then
      raise exception 'bank_scheduler_retirement_drift' using errcode = '55000';
    end if;
    return jsonb_build_object('contract_version', 2, 'job_id', receipt.job_id,
      'state', case when exists (select 1 from collect_hybrid.legacy_bank_scheduler_verifications where job_id = receipt.job_id) then 'retired_verified' else 'paused_pending_verification' end,
      'replayed', true, 'active_jobs', 0);
  end if;
  perform cron.alter_job((before_readback->>'job_id')::bigint, active := false);
  after_readback := collect_hybrid.bank_scheduler_retirement_readback();
  if (after_readback->>'active')::boolean is distinct from false
    or before_readback->>'history_sha256' is distinct from after_readback->>'history_sha256' then
    raise exception 'bank_scheduler_retirement_failed' using errcode = '55000';
  end if;
  select * into strict candidate from cron.job where jobid = (after_readback->>'job_id')::bigint;
  insert into collect_hybrid.legacy_bank_scheduler_retirements (
    job_id, job_name, job_owner, database_name, schedule, command_sha256,
    inactive_metadata_sha256, was_active, retirement_version, retirement_reason,
    state, paused_at, paused_by, paused_xid, cron_timezone, launcher_pid,
    launcher_started_at, history_rows, history_sha256
  ) values (candidate.jobid, candidate.jobname, candidate.username, candidate.database,
    candidate.schedule, encode(extensions.digest(candidate.command, 'sha256'), 'hex'),
    after_readback->>'metadata_sha256', (before_readback->>'active')::boolean,
    '20260930110000', 'rwanda_momo_only_bank_scheduler_retired',
    'paused_pending_verification', clock_timestamp(), current_user, pg_catalog.txid_current(),
    after_readback->>'cron_timezone', (after_readback->>'launcher_pid')::integer,
    (after_readback->>'launcher_started_at')::timestamptz,
    (after_readback->>'history_rows')::bigint, after_readback->>'history_sha256');
  return jsonb_build_object('contract_version', 2, 'job_id', candidate.jobid,
    'state', 'paused_pending_verification', 'replayed', false, 'active_jobs', 0);
end;

routine:collect_hybrid.roster_interrupte.source:
declare d collect_hybrid.roster_import_editor_drafts; r collect_hybrid.roster_import_revisions; v jsonb; begin
 select * into r from collect_hybrid.roster_import_revisions where import_id=p_import order by revision_number desc limit 1;
 select * into d from collect_hybrid.roster_import_editor_drafts where import_id=p_import and expires_at>statement_timestamp();
 if d.import_id is not null then
  v:=collect_hybrid.roster_recovery_payload(d.payload,d.payload_sha256,'draft');
  if not exists(select 1 from collect_hybrid.roster_import_revisions where import_id=p_import
   and id=(v->>'parent_revision_id')::uuid) then
   raise exception 'roster_recovery_lineage_invalid' using errcode='55000'; end if;
  if v->>'parent_revision_id'=r.id::text then
   if p_parent=r.id then return d.payload; end if; -- Inspection preserves exact acknowledged bytes/SHA.
   return collect_hybrid.roster_compact_recovery_draft(v,p_parent);
  end if;
 else v:=jsonb_build_object('title','','reason',''); end if;
 -- An acknowledged review supersedes stale editor rows. Preserve its saved
 -- title/reason, but never reapply those older rows or their approval state.
 v:=v||jsonb_build_object('rows',(select jsonb_agg(jsonb_build_object('member_name',x->>'member_name',
  'momo_name',x->>'momo_name','momo_number',x->>'momo_number') order by ord)
  from jsonb_array_elements(r.preview->'rows') with ordinality a(x,ord)));
 return collect_hybrid.roster_compact_recovery_draft(v,p_parent);
end

routine:collect_hybrid.roster_preview(js.source:
declare raw jsonb; n integer:=0; sr integer; confidence numeric; member_name text; momo_name text;
 phone text; compact text; issues jsonb; seen jsonb:='{}'; rows jsonb:='[]'; normalized jsonb:='[]'; ready integer:=0;
begin
 if p_human is null or p_candidates is null or jsonb_typeof(p_candidates)<>'array'
   or jsonb_array_length(p_candidates) not between 1 and 500 or octet_length(p_candidates::text)>512000 then
  raise exception 'roster_input_invalid' using errcode='22023'; end if;
 for raw in select value from jsonb_array_elements(p_candidates) loop
  n:=n+1;
  if jsonb_typeof(raw)<>'object' or jsonb_typeof(raw->'member_name') is distinct from 'string'
    or jsonb_typeof(raw->'momo_name') is distinct from 'string' or jsonb_typeof(raw->'momo_number') is distinct from 'string'
    or length(raw->>'member_name')>480 or length(raw->>'momo_name')>480 or length(raw->>'momo_number')>32
    or exists(select 1 from jsonb_object_keys(raw) k where k not in ('member_name','momo_name','momo_number','source_row','confidence'))
    or (p_human and (raw ? 'source_row' or raw ? 'confidence')) then
   raise exception 'roster_input_invalid' using errcode='22023'; end if;
  if p_human then sr:=n; confidence:=1;
  else
   if jsonb_typeof(raw->'source_row') is distinct from 'number' or (raw->>'source_row') !~ '^[0-9]+$'
     or (raw->>'source_row')::numeric not between 1 and 2147483647
     or jsonb_typeof(raw->'confidence') is distinct from 'number'
     or (raw->>'confidence')::numeric not between 0 and 1 then
    raise exception 'roster_input_invalid' using errcode='22023'; end if;
   sr:=(raw->>'source_row')::integer; confidence:=(raw->>'confidence')::numeric;
  end if;
  member_name:=collect_hybrid.roster_clean_text(raw->>'member_name');
  momo_name:=collect_hybrid.roster_clean_text(raw->>'momo_name');
  compact:=regexp_replace(collect_hybrid.roster_clean_text(raw->>'momo_number'),'[ ().-]','','g');
  if compact ~ '^250' then compact:='+'||compact; end if;
  phone:=null;
  if compact ~ '^07[2389][0-9]{7}$' or compact ~ '^\+2507[2389][0-9]{7}$' then
   phone:=collect_hybrid.canonical_momo_number(compact); end if;
  issues:='[]';
  if length(member_name) not between 2 and 120 then issues:=issues||jsonb_build_array('Member name must contain 2 to 120 characters'); end if;
  if length(momo_name) not between 2 and 120 then issues:=issues||jsonb_build_array('Registered MoMo name must contain 2 to 120 characters'); end if;
  if (member_name||momo_name) ~ '[[:cntrl:]]' then issues:=issues||jsonb_build_array('Names cannot contain control characters'); end if;
  if member_name ~ '^[=+@-]' or momo_name ~ '^[=+@-]' then issues:=issues||jsonb_build_array('Names cannot begin with spreadsheet formula characters'); end if;
  if phone is null then issues:=issues||jsonb_build_array('Enter a valid full Rwanda MoMo number'); end if;
  if confidence<0.8 then issues:=issues||jsonb_build_array('Extraction confidence is below 80%'); end if;
  if phone is not null then
   if seen ? phone then issues:=issues||jsonb_build_array('MoMo number duplicates source row '||(seen->>phone));
   else seen:=seen||jsonb_build_object(phone,sr); end if;
  end if;
  rows:=rows||jsonb_build_array(jsonb_build_object('source_row',sr,'member_name',member_name,'momo_name',momo_name,
   'momo_number',coalesce(phone,collect_hybrid.roster_clean_text(raw->>'momo_number')),'confidence',confidence,'issues',issues,'ready',jsonb_array_length(issues)=0));
  if jsonb_array_length(issues)=0 then
   ready:=ready+1; normalized:=normalized||jsonb_build_array(jsonb_build_object('member_name',member_name,'momo_name',momo_name,'momo_number',phone)); end if;
 end loop;
 if p_human and ready<>n then raise exception 'roster_rows_invalid' using errcode='22023'; end if;
 return jsonb_build_object('rows',rows,'row_count',n,'ready_count',ready,'error_count',n-ready,'normalized_rows',normalized);
end

routine:collect_hybrid.roster_recovery_l.source:
declare s collect_hybrid.roster_import_sources; root_source collect_hybrid.roster_import_sources; begin
 perform public._lock_notification_session_gate();
 perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
 select * into s from collect_hybrid.roster_import_sources where id=p_import;
 if s.id is null then return; end if; -- Frozen entrypoint preserves its missing-source contract.
 if auth.role()='authenticated' and s.actor_id is distinct from auth.uid() then
  raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 if exists(select 1 from collect_hybrid.roster_recovery_transfers where from_import_id=s.id) then
  raise exception 'roster_recovery_transferred' using errcode='55000'; end if;
 select * into root_source from collect_hybrid.roster_import_sources where id=collect_hybrid.roster_recovery_root(s.id);
 if s.id<>root_source.id then
  -- Logout may legitimately delete the issued source session. Immutable
  -- provenance records that issuance; current verified authority authorizes
  -- this branch. The original SID never becomes a credential/dependency.
  if auth.role()='authenticated' then
   perform collect_hybrid.require_roster_actor(root_source.actor_id,(auth.jwt()->>'session_id')::uuid);
  end if;
  if s.actor_id<>root_source.actor_id or s.expires_at<>root_source.expires_at then
   raise exception 'roster_recovery_lineage_invalid' using errcode='55000'; end if;
 end if;
 if p_mutation and s.expires_at<=clock_timestamp() then raise exception 'roster_import_expired' using errcode='55000'; end if;
end

routine:collect_hybrid.roster_recovery_p.source:
declare v jsonb; r jsonb; raw_row json; keys text[]; field text; begin
 if p_payload is null or octet_length(p_payload) not between 2 and 512000
  or p_sha is null or p_sha !~ '^[a-f0-9]{64}$'
  or encode(extensions.digest(convert_to(p_payload,'UTF8'),'sha256'),'hex')<>p_sha then
  raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 begin v:=p_payload::jsonb; exception when others then
  raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end;
 if jsonb_typeof(v)<>'object' then raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 if (select count(*) from json_object_keys(p_payload::json))<>(select count(*) from jsonb_object_keys(v)) then raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 select array_agg(k order by k) into keys from jsonb_object_keys(v) k;
 if p_kind='review' then
  if keys is distinct from array['p_import_id','p_parent_revision_id','p_reason','p_request_id','p_rows'] then
   raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 elsif p_kind='commit' then
  if keys is distinct from array['p_collection_id','p_human_affirmed','p_import_id','p_mode','p_reason','p_request_id','p_reviewed_rows_sha256','p_revision_id','p_title'] then
   raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 elsif p_kind='draft' then
  if keys is distinct from array['parent_revision_id','reason','rows','title'] then raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 else raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 if p_kind in ('review','commit') then
  foreach field in array (case when p_kind='review' then array['p_import_id','p_request_id','p_parent_revision_id'] else array['p_import_id','p_request_id','p_revision_id'] end) loop
   if jsonb_typeof(v->field) is distinct from 'string' or coalesce(v->>field,'') !~ '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' then
    raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
  end loop;
  if jsonb_typeof(v->'p_reason') is distinct from 'string' or length(btrim(v->>'p_reason')) not between 8 and 500 or (v->>'p_reason') ~ '[[:cntrl:]]' then
   raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 end if;
 if p_kind='commit' then
  if v->'p_human_affirmed' is distinct from 'true'::jsonb or jsonb_typeof(v->'p_mode') is distinct from 'string'
   or v->>'p_mode' not in ('create','existing') or jsonb_typeof(v->'p_reviewed_rows_sha256') is distinct from 'string'
   or coalesce(v->>'p_reviewed_rows_sha256','') !~ '^[a-f0-9]{64}$'
   or (v->>'p_mode'='create' and (v->'p_collection_id' is distinct from 'null'::jsonb
    or jsonb_typeof(v->'p_title') is distinct from 'string' or length(btrim(v->>'p_title')) not between 3 and 120 or (v->>'p_title') ~ '[[:cntrl:]]'))
   or (v->>'p_mode'='existing' and (v->'p_title' is distinct from 'null'::jsonb
    or jsonb_typeof(v->'p_collection_id') is distinct from 'string' or coalesce(v->>'p_collection_id','') !~ '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$')) then
   raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 end if;
 if p_kind in ('draft','review') then
  if jsonb_typeof(case when p_kind='draft' then v->'rows' else v->'p_rows' end) is distinct from 'array'
   or jsonb_array_length(case when p_kind='draft' then v->'rows' else v->'p_rows' end) not between 1 and 500 then
   raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
  for raw_row in select value from json_array_elements(case when p_kind='draft' then p_payload::json->'rows' else p_payload::json->'p_rows' end) loop
   r:=raw_row::jsonb;
   if json_typeof(raw_row) is distinct from 'object' then raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
   if (select count(*) from json_object_keys(raw_row))<>(select count(*) from jsonb_object_keys(r)) then raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
   if jsonb_typeof(r) is distinct from 'object' then raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
   select array_agg(k order by k) into keys from jsonb_object_keys(r) k;
   if keys is distinct from array['member_name','momo_name','momo_number']
    or jsonb_typeof(r->'member_name') is distinct from 'string' or length(r->>'member_name')>480
    or jsonb_typeof(r->'momo_name') is distinct from 'string' or length(r->>'momo_name')>480
    or jsonb_typeof(r->'momo_number') is distinct from 'string' or length(r->>'momo_number')>32 then
    raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
  end loop;
 end if;
 if p_kind='draft' and (jsonb_typeof(v->'parent_revision_id') is distinct from 'string' or jsonb_typeof(v->'title') is distinct from 'string' or length(v->>'title')>120
  or jsonb_typeof(v->'reason') is distinct from 'string' or length(v->>'reason')>500
  or coalesce(v->>'parent_revision_id','') !~ '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$') then
  raise exception 'roster_recovery_payload_invalid' using errcode='22023'; end if;
 return v;
end

routine:collect_hybrid.roster_revision_r.source:
declare answer jsonb; t collect_hybrid.roster_recovery_transfers; r collect_hybrid.roster_import_revisions;
 proof text; begin
 select * into r from collect_hybrid.roster_import_revisions where id=p_revision;
 if r.id is null then return null; end if;
 answer:=collect_hybrid.roster_revision_receipt_v149_frozen(r.id);
 if exists(select 1 from collect_hybrid.roster_recovery_transfers where from_import_id=r.import_id) then
  answer:=answer||jsonb_build_object('can_submit',false);
 end if;
 select * into t from collect_hybrid.roster_recovery_transfers where to_import_id=r.import_id;
 if t.request_id is null then return answer; end if;
 proof:=collect_hybrid.roster_original_proof(t.root_import_id);
 if proof is null or collect_hybrid.roster_recovery_sha(proof)<>t.original_proof_sha256 then
  raise exception 'roster_recovery_lineage_invalid' using errcode='55000'; end if;
 return answer||jsonb_build_object('source_receipt',proof::jsonb->'source_receipt',
  'recovery_lineage',jsonb_build_object('contract_version',1,'transfer_request_id',t.request_id,
   'root_import_id',t.root_import_id,'from_import_id',t.from_import_id,'to_import_id',t.to_import_id,
   'actor_id',t.actor_id,'destination_session_id',t.to_session_id,'destination_reference_id',t.destination_reference_id,
   'initial_revision_id',t.initial_revision_id,'original_proof',proof,'original_proof_sha256',t.original_proof_sha256));
end

