routine:collect_hybrid.validate_receivin.source:
declare
  route public.collection_receivers;
  expected_key text;
begin
  if tg_op = 'DELETE' then
    raise exception 'Receiving assignments are retained; end the assignment instead';
  end if;

  if tg_op = 'UPDATE' then
    if new.member_record_id is distinct from old.member_record_id
       or new.collection_id is distinct from old.collection_id
       or new.collection_receiver_id is distinct from old.collection_receiver_id
       or new.route_key is distinct from old.route_key
       or new.starts_at is distinct from old.starts_at
       or new.reason is distinct from old.reason
       or new.created_by is distinct from old.created_by
       or new.created_at is distinct from old.created_at
       or old.status <> 'active'
       or new.status <> 'ended'
       or new.ended_at is null then
      raise exception 'Receiving assignment history is immutable';
    end if;
    return new;
  end if;

  select receiver.* into route
  from public.collection_receivers receiver
  where receiver.id = new.collection_receiver_id
    and receiver.collection_id = new.collection_id
    and receiver.is_active;
  if route.id is null then
    raise exception 'Active receiving route for this group required';
  end if;
  if not exists (
    select 1
    from collect_hybrid.member_records member
    join public.collection_members membership
      on membership.member_record_id = member.id
     and membership.collection_id = new.collection_id
     and membership.status = 'active'
    where member.id = new.member_record_id
      and member.lifecycle = 'active'
  ) then
    raise exception 'Active group membership required';
  end if;
  expected_key := encode(
    extensions.digest(
      route.receiver_user_id::text || '|' || route.momo_number_hash || '|' || route.network,
      'sha256'
    ),
    'hex'
  );
  new.route_key := expected_key;
  return new;
end;

routine:collect_hybrid.verify_legacy_ban.source:
declare
  receipt collect_hybrid.legacy_bank_scheduler_retirements%rowtype;
  observation collect_hybrid.legacy_bank_scheduler_observations%rowtype;
  final_receipt collect_hybrid.legacy_bank_scheduler_verifications%rowtype;
  readback jsonb;
  readback_hash text;
  elapsed numeric;
begin
  perform pg_catalog.pg_advisory_xact_lock(143, 20260930);
  readback := collect_hybrid.bank_scheduler_retirement_readback();
  perform cron.alter_job((readback->>'job_id')::bigint, schedule := '30 21 * * *');
  readback := collect_hybrid.bank_scheduler_retirement_readback();
  select * into receipt from collect_hybrid.legacy_bank_scheduler_retirements where job_id = (readback->>'job_id')::bigint;
  if not found then raise exception 'bank_scheduler_pause_receipt_required' using errcode = '55000'; end if;
  if receipt.paused_xid = pg_catalog.txid_current() then
    raise exception 'bank_scheduler_postcommit_transaction_required' using errcode = '25001';
  end if;
  if (readback->>'active')::boolean is distinct from false
    or receipt.inactive_metadata_sha256 is distinct from readback->>'metadata_sha256'
    or receipt.history_rows is distinct from (readback->>'history_rows')::bigint
    or receipt.history_sha256 is distinct from readback->>'history_sha256'
    or receipt.cron_timezone is distinct from readback->>'cron_timezone'
    or receipt.launcher_pid is distinct from (readback->>'launcher_pid')::integer
    or receipt.launcher_started_at is distinct from (readback->>'launcher_started_at')::timestamptz then
    raise exception 'bank_scheduler_retirement_drift' using errcode = '55000';
  end if;
  select * into final_receipt from collect_hybrid.legacy_bank_scheduler_verifications where job_id = receipt.job_id;
  if found then
    return jsonb_build_object('contract_version', 2, 'job_id', receipt.job_id,
      'state', 'retired_verified', 'replayed', true, 'active_jobs', 0,
      'verification', to_jsonb(final_receipt));
  end if;
  readback_hash := encode(extensions.digest(readback::text, 'sha256'), 'hex');
  select * into observation from collect_hybrid.legacy_bank_scheduler_observations where job_id = receipt.job_id;
  if not found then
    insert into collect_hybrid.legacy_bank_scheduler_observations
      values (receipt.job_id, (readback->>'observed_at')::timestamptz, current_user, pg_catalog.txid_current(), readback_hash);
    return jsonb_build_object('contract_version', 2, 'job_id', receipt.job_id,
      'state', 'awaiting_observation_interval', 'minimum_seconds', 30,
      'readback', readback, 'readback_sha256', readback_hash);
  end if;
  if observation.observation_xid = pg_catalog.txid_current() then
    raise exception 'bank_scheduler_postcommit_transaction_required' using errcode = '25001';
  end if;
  elapsed := extract(epoch from (readback->>'observed_at')::timestamptz - observation.observed_at);
  if elapsed < 30 then raise exception 'bank_scheduler_observation_interval_required' using errcode = '55000'; end if;
  insert into collect_hybrid.legacy_bank_scheduler_verifications
    values (receipt.job_id, 'retired_verified', (readback->>'observed_at')::timestamptz,
      current_user, pg_catalog.txid_current(), readback_hash, observation.readback_sha256, elapsed);
  select * into strict final_receipt from collect_hybrid.legacy_bank_scheduler_verifications where job_id = receipt.job_id;
  return jsonb_build_object('contract_version', 2, 'job_id', receipt.job_id,
    'state', 'retired_verified', 'replayed', false, 'active_jobs', 0,
    'readback', readback, 'verification', to_jsonb(final_receipt));
end;

routine:collect_hybrid.verify_roster_sou.source:
declare r collect_hybrid.roster_resource_reservations; v collect_hybrid.roster_source_verifications;
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'service_role' then raise exception 'roster_service_required' using errcode='42501'; end if;
 perform collect_hybrid.require_roster_actor(p_actor_id,p_session_id);
 select * into r from collect_hybrid.roster_resource_reservations where id=p_reservation_id for update;
 if r.id is null or r.actor_id<>p_actor_id or r.session_id<>p_session_id or r.source_kind not in ('xlsx','image','pdf') then
  raise exception 'roster_resource_unavailable' using errcode='42501'; end if;
 if p_decoder_receipt_sha256 is null or p_decoder_receipt_sha256 !~ '^[a-f0-9]{64}$'
  or p_decoder_build_sha256 is null or p_decoder_build_sha256 !~ '^[a-f0-9]{64}$'
  or p_policy_version is distinct from 'collect-roster-decoder-v1' or p_toolchain is distinct from
   '{"python":"3.12","pillow":"12.0.0","pypdfium2":"5.2.0","pypdf":"6.7.0","openpyxl":"3.1.5","defusedxml":"0.7.1"}'::jsonb
  or p_summary is null or jsonb_typeof(p_summary)<>'object' or not (p_summary ?& array['frames','pages','pixels','expanded_bytes'])
  or (select count(*) from jsonb_object_keys(p_summary))<>4
  or exists(select 1 from jsonb_each(p_summary) where jsonb_typeof(value)<>'number' or value::text !~ '^[0-9]+$'
    or value::text::numeric>160000000)
  or (p_summary->>'frames')::numeric>20 or (p_summary->>'pages')::numeric>20 or (p_summary->>'pixels')::numeric>40000000
  or (r.source_kind='image' and ((p_summary->>'frames')::numeric<1 or (p_summary->>'pages')::numeric<>0 or (p_summary->>'pixels')::numeric<1))
  or (r.source_kind='pdf' and ((p_summary->>'pages')::numeric<1 or (p_summary->>'frames')::numeric<>0 or (p_summary->>'pixels')::numeric<1))
  or (r.source_kind='xlsx' and ((p_summary->>'frames')::numeric<>0 or (p_summary->>'pages')::numeric<>0 or (p_summary->>'pixels')::numeric<>0
    or (p_summary->>'expanded_bytes')::numeric>8388608)) then raise exception 'roster_input_invalid' using errcode='22023'; end if;
 select * into v from collect_hybrid.roster_source_verifications where reservation_id=r.id;
 if v.reservation_id is not null then
  if v.decoder_receipt_sha256<>p_decoder_receipt_sha256 or v.decoder_build_sha256<>p_decoder_build_sha256 or v.toolchain<>p_toolchain or v.summary<>p_summary then
   raise exception 'roster_request_conflict' using errcode='55000'; end if;
 else
  if r.expires_at<=clock_timestamp() or exists(select 1 from collect_hybrid.roster_resource_completions where reservation_id=r.id) then
   raise exception 'roster_resource_expired' using errcode='55000'; end if;
  insert into collect_hybrid.roster_source_verifications values(r.id,r.source_sha256,r.derived_sha256,p_decoder_receipt_sha256,p_decoder_build_sha256,
   p_policy_version,p_toolchain,p_summary,clock_timestamp());
 end if;
 return jsonb_build_object('contract_version',1,'ok',true,'reservation_id',r.id,'source_sha256',r.source_sha256,
  'derived_sha256',r.derived_sha256,'decoder_receipt_sha256',p_decoder_receipt_sha256,'verified',true);
end

routine:collect_member_actions.add_owned.source:
declare
  actor uuid := auth.uid();
  group_row public.collections%rowtype;
  target_user uuid;
  clean_id text := btrim(coalesce(p_public_id, ''));
begin
  if actor is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  -- Share the owner-control lock: queued requests re-check current authority
  -- after a concurrent ownership transfer or archive, rather than trusting it.
  select * into group_row from public.collections where id = p_collection for update;
  if group_row.id is null or group_row.creator_user_id is distinct from actor
     or group_row.is_platform_sponsored
     or group_row.public_status not in ('private', 'archived') then
    raise exception 'Only the current owner can add a private group admin' using errcode = '42501';
  end if;
  if group_row.archived_at is not null or group_row.public_status = 'archived' then
    raise exception 'Archived groups cannot add admins' using errcode = '22023';
  end if;
  if clean_id !~ '^[0-9]{6}$' then
    raise exception 'Enter a 6 digit Collect ID.' using errcode = '22023';
  end if;
  -- Resolve the ID only within this group's active membership, never expose
  -- global account existence, phone numbers or names through this endpoint.
  select p.id into target_user from public.profiles p
  where p.public_id = clean_id and p.id <> actor
    and exists(select 1 from public.collection_members m
      where m.collection_id = p_collection and m.user_id = p.id and m.status = 'active');
  if target_user is null then
    raise exception 'Choose another active group member.' using errcode = '22023';
  end if;
  -- Lock and re-check membership too; a removed/left member must not be revived.
  perform 1 from public.collection_members
    where collection_id = p_collection and user_id = target_user for update;
  if not exists(select 1 from public.collection_members where collection_id = p_collection
    and user_id = target_user and status = 'active') then
    raise exception 'Choose another active group member.' using errcode = '22023';
  end if;
  if not exists(select 1 from public.collection_members where collection_id = p_collection
    and user_id = target_user and role = 'admin' and status = 'active') then
    insert into public.collection_members(collection_id, user_id, role, status)
    values(p_collection, target_user, 'admin', 'active')
    on conflict(collection_id, user_id, role) do update set status = 'active';
    insert into public.audit_logs(actor_user_id, action, entity_type, entity_id, metadata)
    values(actor, 'collection.admin_added', 'collection', p_collection,
      jsonb_build_object('member_public_id', clean_id));
  end if;
  -- Lost-response retries return the same minimal, verifiable result and do
  -- not create a second role or audit event. No ownership/payment/Admin writes.
  return jsonb_build_object('collection_id', p_collection, 'public_id', clean_id,
    'role', 'admin', 'status', 'active');
end;

routine:collect_member_actions.archive_o.source:
declare
  actor uuid := auth.uid();
  group_row public.collections%rowtype;
begin
  if actor is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  select * into group_row from public.collections where id = p_collection for update;
  if group_row.id is null or group_row.creator_user_id is distinct from actor
     or group_row.is_platform_sponsored
     or group_row.public_status not in ('private', 'archived') then
    raise exception 'Only the current owner can archive a private group' using errcode = '42501';
  end if;
  -- A lost response can be retried by the same owner without a second event.
  if group_row.archived_at is not null then return; end if;
  update public.collections
  set visibility = 'archived', public_status = 'archived', archived_at = now(), updated_at = now()
  where id = p_collection;
  insert into public.audit_logs(actor_user_id,action,entity_type,entity_id,metadata)
  values(actor,'collection.archived','collection',p_collection,
    jsonb_build_object('previous_status',group_row.public_status::text));
end;

routine:collect_member_actions.history_p.source:
declare
  actor uuid := auth.uid();
  query_text text := lower(btrim(coalesce(p_query, '')));
  anchor_id uuid;
  anchor_at timestamptz;
  anchor_amount bigint;
  total_count bigint;
  total_amount bigint;
  own_amount bigint;
  own_collection_ids jsonb;
  revision text;
  page_items jsonb;
  has_more boolean;
  last_id text;
  keyset_predicate text;
  source_order text;
  window_order text;
begin
  if actor is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  if p_limit is null or p_limit not between 1 and 100 or length(query_text) > 80
     or p_sort is null or p_sort not in ('newest', 'oldest', 'highest', 'lowest') then
    raise exception 'Invalid history query' using errcode = '22023';
  end if;
  if p_cursor is not null then
    if jsonb_typeof(p_cursor) <> 'object'
       or coalesce(p_cursor->>'revision', '') !~ '^[a-f0-9]{32}$'
       or coalesce(p_cursor->>'after', '') !~
         '^momo:[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' then
      raise exception 'Invalid history cursor' using errcode = '22023';
    end if;
    anchor_id := substring(p_cursor->>'after' from 6)::uuid;
  end if;

  with readable as materialized (
    select collection.id from public.collections collection
    where public.user_can_read_collection(collection.id, actor)
  ), scoped as (
    select payment.id, payment.collection_id, payment.amount_rwf,
      payment.posted_at,
      coalesce(payment.contributor_user_id = actor, false) as own,
      case when payment.contributor_user_id = actor
        then payment.transaction_id end as transaction_id,
      case when payment.contributor_user_id = actor then 'You'
        when payment.anonymity_choice = 'public_id'
          and payment.contributor_public_id is not null
          then 'Collect ID ' || payment.contributor_public_id
        else 'Anonymous supporter' end as supporter_label,
      collection.title,
      payment.collection_id in (select id from readable) as can_read_collection
    from public.payments payment
    join public.collections collection on collection.id = payment.collection_id
    where payment.status = 'posted' and payment.currency = 'RWF'
      and (p_collection_id is null or payment.collection_id = p_collection_id)
      and (payment.contributor_user_id = actor
        or payment.collection_id in (select id from readable))
  ), matched as (
    select * from scoped
    where query_text = ''
      or strpos(lower(supporter_label), query_text) > 0
      or strpos(lower(coalesce(transaction_id, '')), query_text) > 0
      or (can_read_collection and strpos(lower(title), query_text) > 0)
  )
  select count(*)::bigint,
    coalesce(sum(amount_rwf), 0)::bigint,
    coalesce(sum(amount_rwf) filter (where own), 0)::bigint,
    coalesce(to_jsonb(array_agg(distinct collection_id::text
      order by collection_id::text) filter (where own)), '[]'::jsonb),
    -- A 256-bit XOR of per-row SHA-256 digests has constant aggregate space.
    -- Row identity is included, so a changed/missing row changes the revision
    -- with overwhelming probability; count also distinguishes cardinality.
    md5(row(actor, p_collection_id, query_text, p_sort, count(*),
      coalesce(bit_xor(('x' || encode(extensions.digest(
        row(id, collection_id, amount_rwf, posted_at, own,
          transaction_id, supporter_label)::text, 'sha256'), 'hex'))::bit(256)),
        repeat('0', 256)::bit(256)))::text)
  into total_count, total_amount, own_amount, own_collection_ids, revision
  from matched;

  if p_cursor is not null and revision <> p_cursor->>'revision' then
    raise exception 'History changed. Refresh before loading more.'
      using errcode = 'P0001';
  end if;
  if anchor_id is not null then
    with readable as materialized (
      select collection.id from public.collections collection
      where public.user_can_read_collection(collection.id, actor)
    )
    select payment.posted_at, payment.amount_rwf
    into anchor_at, anchor_amount
    from public.payments payment
    join public.collections collection on collection.id = payment.collection_id
    where payment.id = anchor_id
      and payment.status = 'posted' and payment.currency = 'RWF'
      and (p_collection_id is null or payment.collection_id = p_collection_id)
      and (payment.contributor_user_id = actor
        or payment.collection_id in (select id from readable))
      and (query_text = ''
        or strpos(lower(case when payment.contributor_user_id = actor then 'You'
          when payment.anonymity_choice = 'public_id'
            and payment.contributor_public_id is not null
            then 'Collect ID ' || payment.contributor_public_id
          else 'Anonymous supporter' end), query_text) > 0
        or (payment.contributor_user_id = actor
          and strpos(lower(coalesce(payment.transaction_id, '')), query_text) > 0)
        or (payment.collection_id in (select id from readable)
          and strpos(lower(collection.title), query_text) > 0));
    if not found then
      raise exception 'History changed. Refresh before loading more.'
        using errcode = 'P0001';
    end if;
  end if;

  -- These fragments are selected solely from the four validated enum values.
  -- All user data remains in EXECUTE USING parameters, never in SQL text.
  if p_sort = 'newest' then
    keyset_predicate := '($4::uuid is null or payment.posted_at < $5 or '
      || '(payment.posted_at = $5 and payment.id > $4))';
    source_order := 'payment.posted_at desc, payment.id';
    window_order := 'posted_at desc, id';
  elsif p_sort = 'oldest' then
    keyset_predicate := '($4::uuid is null or payment.posted_at > $5 or '
      || '(payment.posted_at = $5 and payment.id > $4))';
    source_order := 'payment.posted_at, payment.id';
    window_order := 'posted_at, id';
  elsif p_sort = 'highest' then
    keyset_predicate := '($4::uuid is null or payment.amount_rwf < $6 or '
      || '(payment.amount_rwf = $6 and (payment.posted_at < $5 or '
      || '(payment.posted_at = $5 and payment.id > $4))))';
    source_order := 'payment.amount_rwf desc, payment.posted_at desc, payment.id';
    window_order := 'amount_rwf desc, posted_at desc, id';
  else
    keyset_predicate := '($4::uuid is null or payment.amount_rwf > $6 or '
      || '(payment.amount_rwf = $6 and (payment.posted_at < $5 or '
      || '(payment.posted_at = $5 and payment.id > $4))))';
    source_order := 'payment.amount_rwf, payment.posted_at desc, payment.id';
    window_order := 'amount_rwf, posted_at desc, id';
  end if;

  execute format($page$
    with readable as materialized (
      select collection.id from public.collections collection
      where public.user_can_read_collection(collection.id, $1)
    ), candidate as (
      select payment.id, payment.collection_id, payment.amount_rwf,
        payment.posted_at, payment.contributor_user_id, payment.transaction_id,
        payment.anonymity_choice, payment.contributor_public_id
      from public.payments payment
      join public.collections collection on collection.id = payment.collection_id
      where payment.status = 'posted' and payment.currency = 'RWF'
        and ($2::uuid is null or payment.collection_id = $2)
        and (payment.contributor_user_id = $1
          or payment.collection_id in (select id from readable))
        and ($3 = ''
          or strpos(lower(case when payment.contributor_user_id = $1 then 'You'
            when payment.anonymity_choice = 'public_id'
              and payment.contributor_public_id is not null
              then 'Collect ID ' || payment.contributor_public_id
            else 'Anonymous supporter' end), $3) > 0
          or (payment.contributor_user_id = $1
            and strpos(lower(coalesce(payment.transaction_id, '')), $3) > 0)
          or (payment.collection_id in (select id from readable)
            and strpos(lower(collection.title), $3) > 0))
        and %s
      order by %s
      limit $7 + 1
    ), numbered as (
      select candidate.*, row_number() over (order by %s) as position
      from candidate
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'payment_id', 'momo:' || id,
      'collection_id', collection_id,
      'amount_minor', amount_rwf,
      'currency', 'RWF',
      'rail', 'rwanda_momo',
      'posted_at', posted_at,
      'transaction_id', case when contributor_user_id = $1 then transaction_id end,
      'is_current_user_contribution', coalesce(contributor_user_id = $1, false),
      'supporter_label', case when contributor_user_id = $1 then 'You'
        when anonymity_choice = 'public_id' and contributor_public_id is not null
          then 'Collect ID ' || contributor_public_id
        else 'Anonymous supporter' end
    ) order by position) filter (where position <= $7), '[]'::jsonb),
    count(*) > $7,
    max(case when position = $7 then 'momo:' || id end)
    from numbered
  $page$, keyset_predicate, source_order, window_order)
  into page_items, has_more, last_id
  using actor, p_collection_id, query_text, anchor_id, anchor_at,
    anchor_amount, p_limit;

  return jsonb_build_object(
    'items', page_items,
    'total_count', total_count,
    'totals', case when total_count = 0 then '{}'::jsonb
      else jsonb_build_object('RWF', total_amount) end,
    'own_totals', case when total_count = 0 then '{}'::jsonb
      else jsonb_build_object('RWF', own_amount) end,
    'own_collection_ids', own_collection_ids,
    'revision', revision,
    'next_cursor', case when has_more then
      jsonb_build_object('revision', revision, 'after', last_id) end
  );
end;

routine:collect_member_actions.require_g.source:
declare sid uuid; u auth.users; s auth.sessions; c public.collections; m record; jwt_exp text:=auth.jwt()->>'exp';
  member collect_hybrid.member_records; claimed_user uuid; authorized boolean:=false;
begin
  if p_collection_id is null or p_rotate is null then
    raise exception 'group_share_request_invalid' using errcode='22023';end if;
  begin sid:=public._lock_notification_registration_session();
  exception when sqlstate '42501' then
    raise exception 'group_share_session_required' using errcode='42501';end;
  if jwt_exp is null or jwt_exp !~ '^[0-9]{1,12}$'
    or jwt_exp::bigint<=extract(epoch from clock_timestamp()) then
    raise exception 'group_share_session_required' using errcode='42501';end if;
  select * into s from auth.sessions where id=sid and user_id=auth.uid();
  if s.id is null or s.created_at is null or not isfinite(s.created_at) or s.created_at>clock_timestamp()
    or (s.not_after is not null and (not isfinite(s.not_after) or s.not_after<=clock_timestamp())) then
    raise exception 'group_share_session_required' using errcode='42501';end if;
  select * into u from auth.users where id=auth.uid() for share;
  if u.id is null or u.deleted_at is not null or coalesce(u.is_anonymous,false)
    or (u.phone_confirmed_at is null and u.email_confirmed_at is null)
    or (u.banned_until is not null and u.banned_until>clock_timestamp()) then
    raise exception 'group_share_session_required' using errcode='42501';end if;
  if p_rotate then
    select * into c from public.collections where id=p_collection_id for update;
  else
    select * into c from public.collections where id=p_collection_id for share;
  end if;
  if c.id is null or c.archived_at is not null then
    raise exception 'group_share_group_unavailable' using errcode='42501';end if;
  if c.creator_user_id=auth.uid() then authorized:=true;
  -- Rotation retains the existing platform-owner exception with current proof
  -- locks. Reading a private link still requires actual group authority.
  elsif p_rotate and public.is_platform_admin(auth.uid()) then
    begin perform collect_hybrid.require_roster_actor_authority(auth.uid(),sid,
      'platform_owner',array['collections.moderate']);
    exception when sqlstate '42501' then
      raise exception 'group_share_permission_required' using errcode='42501';end;
    authorized:=true;
  else
  for m in select cm.id,cm.user_id,cm.member_record_id from public.collection_members cm
    where cm.collection_id=p_collection_id and cm.status='active'
      and (not p_rotate or cm.role in ('owner','admin','receiver'))
      and (cm.user_id=auth.uid() or collect_hybrid.member_record_belongs_to_user(cm.member_record_id,auth.uid()))
    order by cm.id for share of cm loop
    if m.user_id=auth.uid() then authorized:=true;exit;end if;
    -- Lock both possible account bindings. A lost claim/record in an established
    -- snapshot must serialize or refuse rather than authorize from old EXISTS.
    select * into member from collect_hybrid.member_records where id=m.member_record_id for share;
    claimed_user:=null;
    select claim.user_id into claimed_user from collect_hybrid.member_account_claims claim
      where claim.member_record_id=m.member_record_id for share;
    if member.id is not null and member.lifecycle='active'
      and (member.linked_user_id=auth.uid() or claimed_user=auth.uid()) then authorized:=true;exit;end if;
  end loop;
  end if;
  if not authorized then raise exception 'group_share_permission_required' using errcode='42501';end if;
  if jwt_exp::bigint<=extract(epoch from clock_timestamp()) then
    raise exception 'group_share_session_required' using errcode='42501';end if;
  return sid;
end

routine:collect_member_actions.transfer_.source:
declare
  actor uuid := auth.uid();
  group_row public.collections%rowtype;
  target_user uuid;
  clean_id text := btrim(coalesce(p_public_id,''));
begin
  if actor is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  -- Serialize transfers/archives and re-check authority after taking the lock.
  select * into group_row from public.collections where id = p_collection for update;
  if group_row.id is null or group_row.creator_user_id is distinct from actor
     or group_row.is_platform_sponsored
     or group_row.public_status not in ('private', 'archived') then
    raise exception 'Only the current owner can transfer a private group' using errcode = '42501';
  end if;
  if group_row.archived_at is not null or group_row.public_status = 'archived' then
    raise exception 'Archived groups cannot be transferred' using errcode = '22023';
  end if;
  if clean_id !~ '^[0-9]{6}$' then
    raise exception 'Enter a 6 digit Collect ID.' using errcode = '22023';
  end if;
  -- Preserve the existing contract: a registered Collect ID may receive
  -- ownership. This endpoint never looks up or returns a personal name.
  select id into target_user from public.profiles where public_id = clean_id for key share;
  if target_user is null or target_user = actor then
    raise exception 'Choose another registered Collect ID' using errcode = '22023';
  end if;

  update public.collections set creator_user_id = target_user, updated_at = now()
  where id = p_collection;
  -- Preserve historical memberships, but never leave a stale active owner.
  update public.collection_members set status = 'removed'
  where collection_id = p_collection and role = 'owner' and user_id is distinct from target_user;
  insert into public.collection_members(collection_id,user_id,role,status)
  values(p_collection,target_user,'owner','active')
  on conflict(collection_id,user_id,role) do update set status = 'active';
  insert into public.collection_members(collection_id,user_id,role,status)
  values(p_collection,actor,'admin','active')
  on conflict(collection_id,user_id,role) do update set status = 'active';
  insert into public.audit_logs(actor_user_id,action,entity_type,entity_id,metadata)
  values(actor,'collection.ownership_transferred','collection',p_collection,
    jsonb_build_object('previous_owner_id',actor,'new_owner_id',target_user));
  -- Receiver, SMS consent, ledger and platform Admin roles are intentionally
  -- unchanged. Transferring a group is not approval to redirect its funds.
end;

routine:collect_profile_access.assert_re.source:
declare
  profile_row public.profiles%rowtype;
  local_momo text;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if required_rail is not null and required_rail <> 'rwanda' then
    raise exception 'Only Rwanda MoMo contributions are supported';
  end if;
  select * into profile_row from public.profiles where id = auth.uid() for share;
  if profile_row.id is null or profile_row.country_code <> 'RW'
     or profile_row.currency_code <> 'RWF'
     or profile_row.public_id !~ '^[0-9]{6}$'
     or nullif(btrim(profile_row.whatsapp_phone), '') is null then
    raise exception 'Complete your Rwanda MoMo profile first';
  end if;
  local_momo := public._rwanda_momo_local(profile_row.momo_number);
  if local_momo is null
     or profile_row.momo_provider not in ('mtn_momo', 'airtel_money')
     or (profile_row.momo_provider = 'mtn_momo' and local_momo !~ '^07[89][0-9]{7}$')
     or (profile_row.momo_provider = 'airtel_money' and local_momo !~ '^07[23][0-9]{7}$')
     or profile_row.momo_number_hash is distinct from
        encode(extensions.digest('+250' || substr(local_momo, 2), 'sha256'), 'hex') then
    raise exception 'Complete your profile with a valid MoMo number first';
  end if;
end;

