routine:collect_security.govern_runtime_.source:
declare control_family text:=tg_table_name; spec jsonb:=collect_security.runtime_control_spec(control_family); prior jsonb; next_row jsonb; identity_row jsonb;
 head collect_security.runtime_control_heads; context jsonb; owner_maintenance boolean;
 actor uuid; sid uuid; audit_redacted boolean; reason_hash text; reason_length integer; changed text[]; content_hash text; target_revision bigint;
begin
 if spec is null or spec->>'relation'<>(tg_table_schema||'.'||tg_table_name) then raise exception 'runtime_control_family_invalid' using errcode='55000';end if;
 prior:=case when tg_op='INSERT' then null else to_jsonb(old) end;
 next_row:=case when tg_op='DELETE' then null else to_jsonb(new) end;
 owner_maintenance:=session_user='postgres' and current_setting('role') in ('none','postgres');
 if control_family='notification_preferences' and not owner_maintenance and coalesce(next_row,prior)->>'user_id' is distinct from auth.uid()::text then raise exception 'runtime_control_owner_required' using errcode='42501';end if;
 -- Crucial: preserve the145/146 physical same-value UPDATE serialization
 -- fence. Returning NEW still writes the row; governance state remains untouched.
 if tg_op='UPDATE' and collect_security.runtime_control_hash(prior)=collect_security.runtime_control_hash(next_row) then return new;end if;
 identity_row:=collect_security.runtime_control_identity(control_family,coalesce(next_row,prior));
 if tg_op='UPDATE' and identity_row is distinct from collect_security.runtime_control_identity(control_family,prior) then raise exception 'runtime_control_identity_immutable' using errcode='55000';end if;
 if tg_op='DELETE' and (control_family in ('policy_documents','notification_template_versions') and (prior->>'status'<>'draft' or prior->>'published_at' is not null)
    or control_family='notification_templates' and exists(select 1 from public.notification_template_versions where template_key=prior->>'key' and (status<>'draft' or published_at is not null))
    or control_family='policy_document_sections' and exists(select 1 from public.policy_documents where id=(prior->>'policy_document_id')::uuid and (status<>'draft' or published_at is not null))) then raise exception 'runtime_control_published_immutable' using errcode='55000';end if;
 perform collect_security.runtime_control_lock_parent(control_family,coalesce(next_row,prior),prior,tg_op='DELETE');
 if owner_maintenance then
  actor:=null;sid:=null;reason_hash:=encode(extensions.digest(convert_to('database_owner_maintenance','UTF8'),'sha256'),'hex');reason_length:=26;
 else
  begin context:=current_setting('collect.runtime_control_context',true)::jsonb;exception when others then context:=null;end;
  if context is null or jsonb_typeof(context) is distinct from 'object' or octet_length(context::text)>4096 then raise exception 'runtime_control_revision_required' using errcode='42501';end if;
  if (select array_agg(key order by key) from jsonb_object_keys(context) key) is distinct from
   array['actor_id','expected_revision','family','identity','reason_characters','reason_sha256','session_id']::text[]
   or jsonb_typeof(context->'family') is distinct from 'string' or context->>'family' is distinct from control_family
   or jsonb_typeof(context->'identity') is distinct from 'object' or context->'identity' is distinct from identity_row
   or jsonb_typeof(context->'actor_id') is distinct from 'string' or context->>'actor_id' is distinct from auth.uid()::text
   or jsonb_typeof(context->'session_id') is distinct from 'string' or context->>'session_id' is distinct from auth.jwt()->>'session_id'
   or jsonb_typeof(context->'expected_revision') is distinct from 'number' or char_length(context->>'expected_revision') not between 1 and 10
   or context->>'expected_revision' !~ '^(0|[1-9][0-9]*)$'
   or jsonb_typeof(context->'reason_characters') is distinct from 'number' or char_length(context->>'reason_characters') not between 1 and 3
   or context->>'reason_characters' !~ '^[1-9][0-9]*$'
   or jsonb_typeof(context->'reason_sha256') is distinct from 'string' or context->>'reason_sha256' !~ '^[a-f0-9]{64}$' then
   raise exception 'runtime_control_revision_required' using errcode='42501';end if;
  if (context->>'expected_revision')::bigint not between 0 and 1000000000 or (context->>'reason_characters')::integer not between 8 and 500 then
   raise exception 'runtime_control_revision_required' using errcode='42501';end if;
  actor:=auth.uid();sid:=collect_security.runtime_control_actor(control_family);
  reason_hash:=context->>'reason_sha256';reason_length:=(context->>'reason_characters')::integer;
 end if;
 select * into head from collect_security.runtime_control_heads where runtime_control_heads.family=control_family and identity=identity_row for update;
 if not owner_maintenance and coalesce(head.revision,0) is distinct from (context->>'expected_revision')::bigint then raise exception 'runtime_control_conflict' using errcode='40001';end if;
 if head.family is not null and prior is not null and head.content_sha256 is distinct from collect_security.runtime_control_hash(prior) then raise exception 'runtime_control_head_invalid' using errcode='55000';end if;
 if tg_op<>'DELETE' then
  if control_family in ('policy_documents','notification_template_versions') and next_row->>'status'='published' and (prior is null or prior->>'status'='draft') then next_row:=next_row||jsonb_build_object('published_at',clock_timestamp());end if;
  if control_family in ('sms_receipt_policies','sms_receipt_member_consents') then
   next_row:=next_row||jsonb_build_object('reason','runtime_control:'||reason_hash,'revision',coalesce((prior->>'revision')::integer,0)+1);
   if control_family='sms_receipt_policies' then next_row:=next_row||jsonb_build_object('updated_by',actor);else next_row:=next_row||jsonb_build_object('recorded_by',actor,'recorded_at',clock_timestamp());end if;
   -- Database-owner fixtures must explicitly carry the accountable profile.
   if actor is null then next_row:=next_row||jsonb_build_object(case when control_family='sms_receipt_policies' then 'updated_by' else 'recorded_by' end,coalesce(to_jsonb(new)->case when control_family='sms_receipt_policies' then 'updated_by' else 'recorded_by' end,prior->case when control_family='sms_receipt_policies' then 'updated_by' else 'recorded_by' end));end if;
  end if;
  perform collect_security.runtime_control_validate(control_family,next_row,prior);
  if next_row ? 'updated_at' then next_row:=next_row||jsonb_build_object('updated_at',clock_timestamp());end if;
  if next_row ? 'updated_by' and not (control_family='sms_receipt_policies' and actor is null) then next_row:=next_row||jsonb_build_object('updated_by',actor);end if;
  if next_row ? 'updated_reason' then next_row:=next_row||jsonb_build_object('updated_reason','runtime_control:'||reason_hash);end if;
  if control_family='roster_resource_policy' and prior is not null then next_row:=next_row||jsonb_build_object('version',(prior->>'version')::integer+1);end if;
  new:=jsonb_populate_record(new,next_row);
 end if;
 select coalesce(array_agg(key order by key),'{}') into changed from jsonb_each(coalesce(next_row,prior)) field
 where field.key not in ('created_at','updated_at','updated_by','updated_reason','recorded_by','recorded_at','reason') and (tg_op<>'UPDATE' or prior->field.key is distinct from field.value);
 target_revision:=coalesce(head.revision,0)+1;
 content_hash:=case when tg_op='DELETE' then collect_security.runtime_control_hash(jsonb_build_object('deleted',true)) else collect_security.runtime_control_hash(next_row) end;
 insert into collect_security.runtime_control_heads(family,identity,revision,content_sha256,updated_at) values(control_family,identity_row,target_revision,content_hash,clock_timestamp())
 on conflict on constraint runtime_control_heads_pkey do update set revision=excluded.revision,content_sha256=excluded.content_sha256,updated_at=excluded.updated_at;
 audit_redacted:=control_family='notification_preferences' or control_family='system_settings' and coalesce((coalesce(next_row,prior)->>'is_sensitive')::boolean,false);
 insert into collect_security.runtime_control_events(family,identity_sha256,previous_revision,revision,operation,old_sha256,new_sha256,changed_fields,actor_id,session_id,authority,reason_sha256,redacted,reason_characters)
 values(control_family,collect_security.runtime_control_hash(identity_row),target_revision-1,target_revision,lower(tg_op),case when prior is null or audit_redacted then null else collect_security.runtime_control_hash(prior) end,
 case when next_row is null or audit_redacted then null else content_hash end,changed,actor,sid,case when owner_maintenance then 'database_owner' else 'live_operator' end,reason_hash,audit_redacted,reason_length);
 if tg_op='DELETE' then return old;end if;return new;
end

routine:collect_security.guard_reconcili.source:
begin
 if tg_op='DELETE' then raise exception 'reconciliation_evidence_immutable' using errcode='55000'; end if;
 if row(new.id,new.payment_id,new.payment_fingerprint,new.evidence_sha256,new.source_reference,
   new.occurred_at,new.proposal_reason,new.proposed_by,new.proposed_at,new.proposed_session_id)
  is distinct from row(old.id,old.payment_id,old.payment_fingerprint,old.evidence_sha256,old.source_reference,
   old.occurred_at,old.proposal_reason,old.proposed_by,old.proposed_at,old.proposed_session_id)
  or (old.approved_by is not null and row(new.approved_by,new.approved_at,new.approval_reason,new.approved_session_id)
    is distinct from row(old.approved_by,old.approved_at,old.approval_reason,old.approved_session_id))
  or (old.consumed_at is not null and new.consumed_at is distinct from old.consumed_at)
  or (new.approved_by is not null and (new.approved_by=new.proposed_by or new.approved_at is null
    or new.approved_session_id is null or length(btrim(coalesce(new.approval_reason,''))) not between 10 and 500))
  or (new.consumed_at is not null and new.approved_by is null) then
   raise exception 'reconciliation_evidence_immutable' using errcode='55000';
 end if;
 return new;
end

routine:collect_security.operational_hea.source:
declare rule record; value jsonb; number_value numeric; state text;
 alerts jsonb:='[]';
begin
 if p_metrics is null or jsonb_typeof(p_metrics)<>'object' then
  raise exception 'operational_health_invalid' using errcode='22023';end if;
 for rule in select * from (values
  ('receipt_parse_backlog','sms_pending',100::numeric,null::text),
  ('receipt_parse_age','sms_pending_age_seconds',300::numeric,'sms_pending'),
  ('receipt_parse_failure','sms_failed_24h',1::numeric,null::text),
  ('receipt_parser_lease_expired','sms_expired_parse_leases',1::numeric,null::text),
  ('payment_unmatched','unallocated_events',1::numeric,null::text),
  ('payment_review_age','payment_review_age_seconds',3600::numeric,'payments_review'),
  ('reconciliation_exception','reconciliation_open',1::numeric,null::text),
  ('push_queue_age','push_due_age_seconds',120::numeric,'push_due'),
  ('push_expired_lease','push_expired_leases',1::numeric,null::text),
  ('push_missing_lease','push_missing_leases',1::numeric,null::text),
  ('push_attempt_failure','push_failed_24h',5::numeric,null::text),
  ('receipt_telemetry_stale','receipt_telemetry_age_seconds',300::numeric,'durable_receipts_24h'),
  ('push_scheduler_stale','push_scheduler_age_seconds',180::numeric,'push_due')
 ) rules(code,metric,threshold,queue) loop
  value:=p_metrics->rule.metric;
  if rule.queue is not null and p_metrics->rule.queue='0'::jsonb then state:='not_applicable';
  elsif value is null or value='null'::jsonb then state:='unknown';
  elsif jsonb_typeof(value)<>'number' or (value#>>'{}') !~ '^[0-9]+$'
     or (value#>>'{}')::numeric>9007199254740991 then
   raise exception 'operational_health_invalid' using errcode='22023';
  else number_value:=(value#>>'{}')::numeric;
   state:=case when number_value>=rule.threshold then 'attention' else 'ok' end;
  end if;
  alerts:=alerts||jsonb_build_array(jsonb_build_object('code',rule.code,'metric',rule.metric,
   'threshold',rule.threshold,'state',state));
 end loop;
 return alerts;
end

routine:collect_security.otp_expire_v3(t.source:
declare r collect_security.signed_otp_requests; kind text; h text; t timestamptz:=clock_timestamp();
begin
 select * into r from collect_security.signed_otp_requests where hook_id=p_hook_id for update;
 if r.status='reserved' and r.requested_at<t-interval '5 minutes' then
   kind:='expired_unsent';
 elsif r.status='sending' and r.started_at<t-interval '1 minute' then
   kind:='transport_ambiguous';
 else return; end if;
 h:=encode(extensions.digest(convert_to(kind||':'||r.attempt_id::text||':'||r.revision::text,'UTF8'),'sha256'),'hex');
 update collect_security.signed_otp_requests set status=case when kind='expired_unsent' then 'expired' else 'ambiguous' end,
   revision=revision+1,last_evidence_sha256=h where hook_id=r.hook_id returning * into r;
 insert into collect_security.signed_otp_evidence(hook_id,attempt_id,revision,evidence_sha256,evidence_kind,observed_at,source)
 values(r.hook_id,r.attempt_id,r.revision,h,kind,t,'local_clock');
end

routine:collect_security.otp_receipt_v3(.source:
begin
 if r.contract_version not in (2,3) or r.revision is null or r.attempt_id is null or
   (r.status='sending' and r.started_at is null) or
   (r.status='accepted' and r.contract_version=3 and (r.accepted_at is null or r.provider_message_hash is null)) or
   (r.status='delivered' and (r.accepted_at is null or r.delivered_at is null or r.provider_message_hash is null)) then
   raise exception 'OTP stored state unavailable' using errcode='55000';
 end if;
 return jsonb_build_object('contract_version',3,'hook_id',r.hook_id,'payload_hash',r.payload_hash,
   'attempt_id',r.attempt_id,'state',r.status,'revision',r.revision,
   'can_send',r.contract_version=3 and r.status='reserved');
end

routine:collect_security.purge_operation.source:
declare removed integer;
begin
 if p_limit is null or p_limit not between 1 and 10000 then
  raise exception 'operational_metric_limit_invalid' using errcode='22023';end if;
 with old as (select bucket_at,event_code from collect_security.operational_metric_buckets
   where bucket_at<clock_timestamp()-interval '90 days' order by bucket_at,event_code
   for update skip locked limit p_limit), gone as (
   delete from collect_security.operational_metric_buckets b using old
   where b.bucket_at=old.bucket_at and b.event_code=old.event_code returning 1)
 select count(*) into removed from gone;
 return removed;
end

routine:collect_security.reconciliation_.source:
declare u auth.users; s auth.sessions;
begin
 if p_actor is null or p_session is null then return false; end if;
 select * into u from auth.users where id=p_actor for share;
 select * into s from auth.sessions where id=p_session and user_id=p_actor for share;
 if u.id is null or s.id is null or s.aal::text is distinct from 'aal2'
   or (s.not_after is not null and s.not_after<=clock_timestamp())
   or u.deleted_at is not null or u.phone_confirmed_at is null or coalesce(u.is_anonymous,false)
   or (u.banned_until is not null and u.banned_until>clock_timestamp()) then return false; end if;
 return exists(select 1 from collect_admin_access.whatsapp_approvals a
   join public.admin_user_roles ur on ur.user_id=a.user_id and ur.revoked_at is null
   join public.admin_roles r on r.id=ur.role_id and r.name='platform_owner'
   join public.admin_role_permissions rp on rp.role_id=r.id and rp.permission_name='payments.allocate'
   where a.user_id=p_actor and a.revoked_at is null
     and a.phone_e164='+'||ltrim(u.phone,'+')
     and (a.expires_at is null or a.expires_at>clock_timestamp())
     and s.created_at>=a.approved_at and s.created_at>=ur.created_at);
end

routine:collect_security.require_otp_ser.source:
