routine:collect_security.require_reconci.source:
declare session_text text:=auth.jwt()->>'session_id'; session_id uuid;
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'authenticated' or auth.uid() is null
   or auth.jwt()->>'aal' is distinct from 'aal2' or session_text is null
   or session_text !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
  raise exception 'reconciliation_step_up_required' using errcode='42501';
 end if;
 session_id:=session_text::uuid;
 perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
 if not collect_security.reconciliation_actor_current(auth.uid(),session_id) then
  raise exception 'reconciliation_actor_unavailable' using errcode='42501';
 end if;
 return session_id;
end

routine:collect_security.require_shadow_.source:
declare sid uuid;
begin
  begin sid:=public._lock_notification_registration_session();
  exception when sqlstate '42501' then
    raise exception 'shadow_session_required' using errcode='42501';end;
  -- Match150: Auth/session -> roster serialization -> authority rows -> lease.
  perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
  begin
    perform collect_hybrid.require_roster_actor_authority(auth.uid(),sid,
      'platform_owner',array['system_health.read','notifications.read']);
  exception when sqlstate '42501' then
    raise exception 'shadow_permission_required' using errcode='42501';end;
  return sid;
end

routine:collect_security.runtime_control.source:
declare spec jsonb:=collect_security.runtime_control_spec(p_family);
 session_id uuid; permissions text[];
begin
 if spec is null then raise exception 'runtime_control_family_invalid' using errcode='22023';end if;
 begin session_id:=public._lock_notification_registration_session();
 exception when sqlstate '42501' then
  raise exception 'runtime_control_session_required' using errcode='42501';end;
 if coalesce((spec->>'user_owned')::boolean,false) then return session_id;end if;
 permissions:=array[case when p_read then spec->>'read_permission' else spec->>'permission' end];
 if not p_read and spec ? 'additional_permission' then
  permissions:=array_append(permissions,spec->>'additional_permission');end if;
 begin
  perform collect_hybrid.require_roster_actor_authority(auth.uid(),session_id,'platform_owner',permissions);
 exception when sqlstate '42501' then
  raise exception 'runtime_control_permission_required' using errcode='42501';end;
 return session_id;
end

declare item record; text_value text;
begin
 if p_value is null or p_depth>5 or octet_length(p_value::text)>65536 then raise exception 'runtime_control_invalid' using errcode='22023';end if;
 if jsonb_typeof(p_value)='object' then
  if (select count(*) from jsonb_object_keys(p_value))>50 then raise exception 'runtime_control_invalid' using errcode='22023';end if;
  for item in select * from jsonb_each(p_value) loop
   if char_length(item.key) not between 1 and 80 or item.key !~ '^[A-Za-z_][A-Za-z0-9_.:-]*$'
      or item.key ~* '(secret|password|credential|api[_-]?key|authorization|access[_-]?token|refresh[_-]?token|private[_-]?key)' then
    raise exception 'runtime_control_sensitive_field' using errcode='22023';end if;
   perform collect_security.runtime_control_bound_json(item.value,p_depth+1);
  end loop;
 elsif jsonb_typeof(p_value)='array' then
  if jsonb_array_length(p_value)>50 then raise exception 'runtime_control_invalid' using errcode='22023';end if;
  for item in select value from jsonb_array_elements(p_value) loop perform collect_security.runtime_control_bound_json(item.value,p_depth+1);end loop;
 elsif jsonb_typeof(p_value)='string' then
  text_value:=p_value#>>'{}';
  if char_length(text_value)>32768 or regexp_replace(text_value,E'[\n\r\t]','','g') ~ '[[:cntrl:]]' then raise exception 'runtime_control_invalid' using errcode='22023';end if;
 elsif jsonb_typeof(p_value)='number' then
  if (p_value#>>'{}')::numeric not between -100000000000 and 100000000000 then raise exception 'runtime_control_invalid' using errcode='22023';end if;
 end if;
end

declare spec jsonb:=collect_security.runtime_control_spec(p_family); field record; typ text; clean text;
begin
 if spec is null or p_identity is null or jsonb_typeof(p_identity)<>'object' or octet_length(p_identity::text)>2048 then raise exception 'runtime_control_identity_invalid' using errcode='22023';end if;
 if (select array_agg(key order by key) from jsonb_object_keys(p_identity) key) is distinct from (select array_agg(key order by key) from jsonb_array_elements_text(spec->'identity') key) then raise exception 'runtime_control_identity_invalid' using errcode='22023';end if;
 if coalesce((spec->>'user_owned')::boolean,false) and p_identity->>'user_id' is distinct from auth.uid()::text then raise exception 'runtime_control_owner_required' using errcode='42501';end if;
 for field in select * from jsonb_each(p_identity) loop
  typ:=spec->'types'->>field.key;clean:=field.value#>>'{}';
  if field.value='null'::jsonb
   or typ='uuid' and (jsonb_typeof(field.value)<>'string' or clean !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$')
   or typ='boolean' and field.value is distinct from 'true'::jsonb
   or typ='text' and (jsonb_typeof(field.value)<>'string' or char_length(clean) not between 1 and 128 or clean !~ '^[A-Za-z0-9_.:-]+$') then raise exception 'runtime_control_identity_invalid' using errcode='22023';end if;
 end loop;
end

declare spec jsonb:=collect_security.runtime_control_spec(p_family); field record; typ text; value_type text; clean text; limit_chars integer; numeric_value numeric;
begin
 if spec is null or p_values is null or jsonb_typeof(p_values)<>'object' or octet_length(p_values::text)>65536 then raise exception 'runtime_control_invalid' using errcode='22023';end if;
 for field in select * from jsonb_each(p_values) loop
  typ:=spec->'types'->>field.key;value_type:=jsonb_typeof(field.value);clean:=field.value#>>'{}';
  if typ is null then raise exception 'runtime_control_invalid' using errcode='22023';end if;
  if value_type='null' then
   if not (spec->'nullable') ? field.key then raise exception 'runtime_control_invalid' using errcode='22023';end if;
   continue;
  end if;
  if typ='boolean' and value_type<>'boolean' or typ in ('integer','bigint') and (value_type<>'number' or clean !~ '^-?[0-9]+$')
    or typ in ('text','uuid','timestamp with time zone') and value_type<>'string' then raise exception 'runtime_control_invalid' using errcode='22023';end if;
  if typ in ('integer','bigint') then
   numeric_value:=clean::numeric;
   if typ='integer' and numeric_value not between -2147483648 and 2147483647 or typ='bigint' and numeric_value not between -100000000000 and 100000000000 then raise exception 'runtime_control_invalid' using errcode='22023';end if;
  end if;
  if typ='jsonb' then perform collect_security.runtime_control_bound_json(field.value);end if;
  if typ='uuid' and clean !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then raise exception 'runtime_control_invalid' using errcode='22023';end if;
  if typ='timestamp with time zone' then
   if char_length(clean) not between 20 and 35 or clean !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' then raise exception 'runtime_control_invalid' using errcode='22023';end if;
   begin
    if not isfinite(clean::timestamptz) or clean::timestamptz>clock_timestamp()+interval '2 years' or clean::timestamptz<'2000-01-01'::timestamptz then raise exception 'runtime_control_invalid' using errcode='22023';end if;
   exception when invalid_datetime_format or datetime_field_overflow then raise exception 'runtime_control_invalid' using errcode='22023';end;
  end if;
  if typ='text' then
   limit_chars:=case when field.key in ('body','body_template','instructions','regulatory_footer_note') then 24000 when field.key in ('description','subtitle','summary','short_purpose','target','owner','escalation') then 2000 when field.key like '%url' then 2048 else 500 end;
   if char_length(clean)>limit_chars or regexp_replace(clean,E'[\n\r\t]','','g') ~ '[[:cntrl:]]' then raise exception 'runtime_control_invalid' using errcode='22023';end if;
   if field.key in ('key','queue_key','rpc_name','section_key','icon_key','version','locale','network','currency','country_code','required_permission','template_key','event_type_key','preference_key','collection_type_key','default_category_subtype','default_purpose_template_key')
    and (char_length(clean) not between 1 and 128 or clean !~ '^[A-Za-z0-9_.:-]+$') then raise exception 'runtime_control_invalid' using errcode='22023';end if;
   if field.key in ('label','display_name','legal_name','title','title_template','body_template','body','target','owner','escalation') and char_length(btrim(clean))=0 then raise exception 'runtime_control_invalid' using errcode='22023';end if;
   if field.key like '%url' and not collect_security.runtime_control_https(clean) then raise exception 'runtime_control_invalid_url' using errcode='22023';end if;
   if field.key in ('title_template','body_template') and regexp_replace(clean,'\{\{[a-z][a-z0-9_]{0,63}\}\}','','g') ~ '(\{\{|\}\})' then raise exception 'runtime_control_invalid_template' using errcode='22023';end if;
  end if;
  if field.key in ('display_order','sort_order') and numeric_value not between 0 and 10000 then raise exception 'runtime_control_invalid' using errcode='22023';end if;
 end loop;
end

select p_value is not null and char_length(p_value) between 10 and 2048
 and p_value ~ '^https://[A-Za-z0-9][A-Za-z0-9.-]*\.[A-Za-z]{2,63}(:443)?([/?][^[:space:]@]*)?$'
 and p_value !~ '[[:cntrl:]]' and p_value !~ '^https://[0-9.]+';

declare parent_id uuid; template_key_text text; parent public.policy_documents;
begin
 if p_family='policy_documents' then
  perform 1 from public.policy_documents where id=(p_new->>'id')::uuid for update;
 elsif p_family='policy_document_sections' then
  if p_old is not null and p_old->>'policy_document_id' is distinct from p_new->>'policy_document_id' then raise exception 'runtime_control_wiring_immutable' using errcode='55000';end if;
  parent_id:=(p_new->>'policy_document_id')::uuid;
  -- Physical parent fencing also prevents stale repeatable-read publication
  -- after a committed section edit. Governance no-op keeps its version intact.
  update public.policy_documents set status=status where id=parent_id returning * into parent;
  if parent.id is null and p_delete and pg_trigger_depth()>1 then return;end if;
  if parent.id is null or parent.status<>'draft' or parent.published_at is not null then raise exception 'runtime_control_published_immutable' using errcode='55000';end if;
 elsif p_family='notification_template_versions' then
  template_key_text:=p_new->>'template_key';
  update public.notification_templates set enabled=enabled where key=template_key_text;
  if not found and p_delete and pg_trigger_depth()>1 then return;end if;
  if not found then raise exception 'runtime_control_template_required' using errcode='22023';end if;
 end if;
end

declare spec jsonb:=collect_security.runtime_control_spec(p_family); field record; typ text; value_type text; clean text; limit_chars integer;
 parent public.policy_documents; amount_text text;
begin
 if spec is null or p_new is null or jsonb_typeof(p_new)<>'object' then raise exception 'runtime_control_invalid' using errcode='22023';end if;
 perform collect_security.runtime_control_check_values(p_family,case when p_old is null then p_new else
  coalesce((select jsonb_object_agg(key,value) from jsonb_each(p_new) where p_old->key is distinct from value),'{}'::jsonb) end);
 if p_old is not null and exists(select 1 from jsonb_array_elements_text(spec->'immutable_after_create') k where p_new->k is distinct from p_old->k) then
  raise exception 'runtime_control_wiring_immutable' using errcode='55000';end if;
 if p_family='support_channels' then
  if p_new->>'channel_type' in ('phone','whatsapp') and (char_length(p_new->>'value') not between 8 and 16 or p_new->>'value' !~ '^\+?[1-9][0-9]+$')
   or p_new->>'channel_type'='email' and (char_length(p_new->>'value')>254 or p_new->>'value' !~ '^[A-Za-z0-9.!#$%&''*+/=?^_`{|}~-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,63}$')
   or p_new->>'channel_type'='url' and not collect_security.runtime_control_https(p_new->>'value') then raise exception 'runtime_control_invalid_support' using errcode='22023';end if;
 end if;
 if p_family='payment_entrypoints' and (p_new->>'is_active')::boolean then
  if p_new->>'country_code' is distinct from 'RW' or p_new->>'currency' is distinct from 'RWF' or p_new->>'network' is distinct from 'mtn_momo'
    or p_new->>'code' is null or p_new->>'code' !~ '^\*182\*8\*1\*41258\*[1-9][0-9]{0,8}#$' then raise exception 'runtime_control_rwanda_route_required' using errcode='22023';end if;
  amount_text:=split_part(p_new->>'code','*',6);amount_text:=replace(amount_text,'#','');
  if p_new->'metadata'->>'amount_rwf' is distinct from amount_text then raise exception 'runtime_control_payment_amount_mismatch' using errcode='22023';end if;
 end if;
 if p_family='collection_type_country_rules' and (p_new->>'enabled')::boolean and p_new->>'country_code' is distinct from 'RW' then raise exception 'runtime_control_rwanda_route_required' using errcode='22023';end if;
 if p_family='feature_flags' and (p_new->>'enabled')::boolean and p_new->>'key' ~* '(bank_transfer|stripe|diaspora|international|foreign)' then raise exception 'runtime_control_rwanda_route_required' using errcode='22023';end if;
 if p_family='system_settings' then
  if p_new->>'key' ~* '(secret|password|credential|api[_-]?key|token|private[_-]?key)' then raise exception 'runtime_control_sensitive_field' using errcode='22023';end if;
  if p_new->>'key'='payments.mode' and p_new->'value' is distinct from '{"rwanda":{"provider":"momo_ussd_sms","currency":"RWF"}}'::jsonb then raise exception 'runtime_control_rwanda_route_required' using errcode='22023';end if;
  if p_new->>'key'='sms.parser.schema_version' and p_new->'value' is distinct from '"collect.sms_parser.v1"'::jsonb then raise exception 'runtime_control_unsupported_parser' using errcode='22023';end if;
 end if;
 if p_old is not null and p_family in ('policy_documents','notification_template_versions') and (p_old->>'status'<>'draft' or p_old->>'published_at' is not null) then
  if (p_new-array['status','updated_at','updated_by','updated_reason']) is distinct from (p_old-array['status','updated_at','updated_by','updated_reason'])
    or p_new->>'status' not in ('published','archived') or (p_old->>'status'='archived' and p_new->>'status'<>'archived') then raise exception 'runtime_control_published_immutable' using errcode='55000';end if;
 end if;
 if p_family='policy_document_sections' then
  select * into parent from public.policy_documents where id=(p_new->>'policy_document_id')::uuid;
  if parent.id is null or parent.status<>'draft' or parent.published_at is not null then raise exception 'runtime_control_published_immutable' using errcode='55000';end if;
 end if;
 if p_family='notification_templates' and p_old is not null and exists(select 1 from public.notification_template_versions where template_key=p_old->>'key' and (status<>'draft' or published_at is not null))
  and (p_new-array['enabled','updated_at','updated_by','updated_reason']) is distinct from (p_old-array['enabled','updated_at','updated_by','updated_reason']) then
  raise exception 'runtime_control_published_immutable' using errcode='55000';end if;
 if p_family='policy_documents' and p_new->>'status'='published' and (p_old is null or p_old->>'status'='draft') then
  if not exists(select 1 from public.policy_document_sections where policy_document_id=(p_new->>'id')::uuid) then raise exception 'runtime_control_policy_sections_required' using errcode='22023';end if;
 end if;
 if p_family='sms_receipt_policies' and not exists(select 1 from public.collections c where c.id=(p_new->>'collection_id')::uuid and c.collection_type='ikimina' and c.archived_at is null) then raise exception 'runtime_control_collection_required' using errcode='22023';end if;
 if p_family='sms_receipt_member_consents' and not exists(select 1 from collect_hybrid.member_records m join collect_hybrid.member_momo_identities i on i.member_id=m.id where m.id=(p_new->>'member_record_id')::uuid and m.lifecycle='active' and m.linked_user_id is null) then raise exception 'runtime_control_member_required' using errcode='22023';end if;
 if p_family='roster_resource_policy' and ((p_new->>'actor_active')::integer>(p_new->>'global_active')::integer
   or (p_new->>'actor_daily_requests')::integer>(p_new->>'global_daily_requests')::integer
   or (p_new->>'actor_daily_bytes')::bigint>(p_new->>'global_daily_bytes')::bigint
   or (p_new->>'actor_daily_cost_units')::bigint>(p_new->>'global_daily_cost_units')::bigint
   or (p_new->>'ai_attempt_cost_units')::bigint>(p_new->>'actor_daily_cost_units')::bigint) then raise exception 'runtime_control_quota_order_invalid' using errcode='22023';end if;
 if p_family='otp_policy' and (p_new->>'global_hourly_limit')::integer>(p_new->>'global_daily_limit')::integer then raise exception 'runtime_control_quota_order_invalid' using errcode='22023';end if;
end

routine:collect_security.shadow_run_json.source:
declare r collect_security.shadow_supervisor_runs;
  s collect_security.shadow_supervisor_samples;
begin
  select * into r from collect_security.shadow_supervisor_runs where id=p_run_id;
  if r.id is null then return null;end if;
  select * into s from collect_security.shadow_supervisor_samples where run_id=r.id;
  if s.id is not null and s.content_sha256 is distinct from
    encode(extensions.digest(convert_to(s.body::text,'UTF8'),'sha256'),'hex') then
    raise exception 'shadow_integrity_unavailable' using errcode='55000';end if;
  return jsonb_build_object('run_id',r.id,'request_id',r.request_id,
    'fence_version',r.fence_version,'status',case when r.status='running'
      and r.lease_expires_at<=p_observed_at then 'expired' else r.status end,
    'started_at',r.started_at,'lease_expires_at',r.lease_expires_at,
    'sampled_at',s.checked_at,'completed_at',r.completed_at,'summary',s.body->'summary');
end

routine:private.collect_admin_country_fo.source:
declare
  v_country text := upper(nullif(btrim(coalesce(p_row ->> 'country_code', '')), ''));
  v_rail text := lower(nullif(btrim(coalesce(p_row ->> 'rail', '')), ''));
  v_record_id uuid;
  v_intent_id uuid;
  v_transaction_id uuid;
  v_collection_id uuid;
  v_user_id uuid;
  v_whatsapp_phone text;
  v_platform_sponsored boolean := false;
begin
  if v_country ~ '^[A-Z]{2}$' then
    return v_country;
  end if;

  if v_rail = 'rw_momo' or p_rpc_name = 'admin_list_collect_payees' then
    return 'RW';
  end if;

  if p_rpc_name = 'admin_list_collections' then
    v_record_id := private.collect_admin_try_uuid(p_row ->> 'id');
    select collection.creator_user_id, collection.is_platform_sponsored
      into v_user_id, v_platform_sponsored
    from public.collections collection
    where collection.id = v_record_id;
    if v_platform_sponsored then return 'RW'; end if;
  elsif p_rpc_name = 'admin_list_notifications' then
    v_record_id := private.collect_admin_try_uuid(p_row ->> 'id');
    select event.user_id into v_user_id
    from public.notification_events event
    where event.id = v_record_id;
  elsif p_rpc_name in (
    'admin_list_collect_transactions',
    'admin_list_collect_reconciliations',
    'admin_list_collect_ledgers'
  ) then
    v_intent_id := private.collect_admin_try_uuid(p_row ->> 'payment_intent_id');
    v_transaction_id := private.collect_admin_try_uuid(p_row ->> 'transaction_id');
    v_collection_id := private.collect_admin_try_uuid(p_row ->> 'collection_id');

    if v_intent_id is not null then
      select intent.contributor_user_id into v_user_id
      from public.bank_transfer_intents intent
      where intent.id = v_intent_id;
    end if;

    if v_user_id is null and nullif(btrim(coalesce(p_row ->> 'reference', '')), '') is not null then
      select intent.contributor_user_id into v_user_id
      from public.bank_transfer_intents intent
      where upper(intent.transfer_reference) = upper(btrim(p_row ->> 'reference'))
      order by intent.created_at desc
      limit 1;
    end if;

    if v_user_id is null and v_transaction_id is not null then
      select allocation.contributor_user_id into v_user_id
      from public.bank_transaction_allocations allocation
      where allocation.bank_transaction_id = v_transaction_id
      order by allocation.created_at desc
      limit 1;
    end if;

    if v_user_id is null and v_collection_id is not null then
      select collection.creator_user_id into v_user_id
      from public.collections collection
      where collection.id = v_collection_id;
    end if;
  end if;

  if v_user_id is not null then
    select
      upper(nullif(btrim(profile.country_code), '')),
      profile.whatsapp_phone
      into v_country, v_whatsapp_phone
    from public.profiles profile
    where profile.id = v_user_id;
  end if;

  if v_country ~ '^[A-Z]{2}$' then return v_country; end if;
  if regexp_replace(coalesce(v_whatsapp_phone, ''), '[^0-9+]', '', 'g') like '+250%' then
    return 'RW';
  end if;
  if regexp_replace(coalesce(v_whatsapp_phone, ''), '[^0-9+]', '', 'g') like '+356%' then
    return 'MT';
  end if;

  -- ZZ is an internal safe bucket for an unresolved non-Rwanda/non-Malta row.
  -- It is displayed only through the "Other countries" scope.
  return 'ZZ';
end;

routine:private.collect_admin_try_uuid(t.source:
begin
  return nullif(btrim(coalesce(p_value, '')), '')::uuid;
exception
  when invalid_text_representation then return null;
end;

routine:public._authenticated_momo_phone.source:
declare
  profile_digits text;
  auth_digits text;
  canonical_profile_phone text;
  canonical_auth_phone text;
  auth_phone_confirmed_at timestamptz;
begin
  select
    regexp_replace(coalesce(profile.momo_number, ''), '[^0-9]', '', 'g'),
    regexp_replace(coalesce(auth_user.phone, ''), '[^0-9]', '', 'g'),
    auth_user.phone_confirmed_at
    into profile_digits, auth_digits, auth_phone_confirmed_at
  from public.profiles profile
  join auth.users auth_user on auth_user.id = profile.id
  where profile.id = p_user_id
    and auth_user.deleted_at is null
    and profile.country_code = 'RW';

  if profile_digits ~ '^250[0-9]{9}$' then
    canonical_profile_phone := '+' || profile_digits;
  elsif profile_digits ~ '^0[0-9]{9}$' then
    canonical_profile_phone := '+250' || substr(profile_digits, 2);
  elsif profile_digits ~ '^[0-9]{9}$' then
    canonical_profile_phone := '+250' || profile_digits;
  else
    return null;
  end if;

  if auth_digits ~ '^250[0-9]{9}$' then
    canonical_auth_phone := '+' || auth_digits;
  elsif auth_digits ~ '^0[0-9]{9}$' then
    canonical_auth_phone := '+250' || substr(auth_digits, 2);
  elsif auth_digits ~ '^[0-9]{9}$' then
    canonical_auth_phone := '+250' || auth_digits;
  else
    return null;
  end if;

  if auth_phone_confirmed_at is null
     or canonical_profile_phone <> canonical_auth_phone then
    return null;
  end if;

  return encode(extensions.digest(canonical_auth_phone, 'sha256'), 'hex');
end;

routine:public._lock_notification_regist.source:
declare session_text text:=auth.jwt()->>'session_id'; session_id uuid; begin
  perform public._lock_notification_session_gate();
  if auth.role() is distinct from 'authenticated' or auth.uid() is null
    or session_text is null or session_text !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
    raise exception 'notification_registration_session_required' using errcode='42501';
  end if;
  session_id:=session_text::uuid;
  -- SHARE blocks both deletion and non-key revocation updates before we lock
  -- a token. A late registration sees the deletion after waiting and refuses.
  perform 1 from auth.sessions s where s.id=session_id and s.user_id=auth.uid() for share;
  if not found or not public._notification_session_is_live(session_id,auth.uid()) then
    raise exception 'notification_registration_session_required' using errcode='42501';
  end if;
  return session_id;
end

routine:public._notification_dispatch_co.source:
declare project_url text; api_key text; internal_secret text; begin
  if to_regclass('vault.decrypted_secrets') is null then
    raise exception 'notification_scheduler_not_configured';
  end if;
  select decrypted_secret into project_url from vault.decrypted_secrets where name = 'collect_notification_project_url';
  select decrypted_secret into api_key from vault.decrypted_secrets where name = 'collect_notification_api_key';
  select decrypted_secret into internal_secret from vault.decrypted_secrets where name = 'collect_notification_internal_secret';
  if project_url is null or project_url !~ '^https://[a-z0-9]{20}\.supabase\.co$'
    or coalesce(length(api_key), 0) < 20 or coalesce(length(internal_secret), 0) < 32
    or api_key ~ '[\r\n]' or internal_secret ~ '[\r\n]' then
    raise exception 'notification_scheduler_not_configured';
  end if;
  return jsonb_build_object('url', project_url || '/functions/v1/dispatch-notifications',
    'headers', jsonb_build_object('Content-Type', 'application/json', 'apikey', api_key, 'x-collect-signature', internal_secret));
end

routine:public._notification_retry_delay.source:
declare floor_seconds integer; begin
  if p_attempt is null or p_attempt < 1 or p_attempt > 5 or p_retry_after < 0 or p_retry_after > 3600 then
    raise exception 'notification_retry_delay_invalid';
  end if;
  floor_seconds := greatest(least(3600, 30 * (2 ^ p_attempt)::integer), coalesce(p_retry_after, 0));
  return floor_seconds + floor(random() * (least(3600 - floor_seconds, greatest(1, floor_seconds / 4)) + 1))::integer;
end

routine:public._rwanda_momo_local(text).source:
declare
  digits text := regexp_replace(coalesce(p_value, ''), '[^0-9]', '', 'g');
begin
  if digits ~ '^2507[2389][0-9]{7}$' then
    return '0' || substr(digits, 4);
  end if;
  if digits ~ '^07[2389][0-9]{7}$' then
    return digits;
  end if;
  if digits ~ '^7[2389][0-9]{7}$' then
    return '0' || digits;
  end if;
  return null;
end;

routine:public.accept_attested_receipt_v.source:
declare r public.raw_payment_sms; accepted jsonb; result_id uuid;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'Service role required' using errcode='42501'; end if;
  if p_native_capability_id is null or p_receiver_user_id is null or p_client_envelope_id is null
     or p_raw_body is null or length(btrim(p_raw_body))=0 or octet_length(p_raw_body)>4096
     or p_raw_sender is null or length(btrim(p_raw_sender))=0 or octet_length(p_raw_sender)>96
     or p_body_hash is null or p_body_hash !~ '^[a-f0-9]{64}$'
     or p_receiver_momo_number_hash is null or p_receiver_momo_number_hash !~ '^[a-f0-9]{64}$'
     or encode(extensions.digest(p_raw_body,'sha256'),'hex')<>p_body_hash then
    raise exception 'Invalid receipt binding' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_receiver_user_id::text||':'||p_client_envelope_id::text,0));
  select * into r from public.raw_payment_sms
    where receiver_user_id=p_receiver_user_id and client_envelope_id=p_client_envelope_id for update;
  if r.id is null then
    accepted:=public.ingest_attested_raw_payment_sms(p_native_capability_id,p_receiver_user_id,p_collection_id,
      p_raw_sender,p_raw_body,p_body_hash,p_client_envelope_id,p_receiver_momo_number_hash,p_received_at_device);
    result_id:=(accepted->>'id')::uuid;
    select * into r from public.raw_payment_sms where id=result_id for update;
  end if;
  -- A committed, exactly bound receipt may be acknowledged again after a timeout.
  -- A new capability is not needed to prove a second settlement: none is posted here.
  if r.id is null or r.receiver_user_id is distinct from p_receiver_user_id
     or r.client_envelope_id is distinct from p_client_envelope_id
     or r.body_hash is distinct from p_body_hash or r.raw_body is distinct from p_raw_body
     or btrim(r.raw_sender) is distinct from btrim(p_raw_sender)
     or r.receiver_momo_number_hash is distinct from p_receiver_momo_number_hash
     or r.received_at_device is distinct from nullif(btrim(p_received_at_device),'')::timestamptz
     or r.native_action_capability_id is null or r.attestation_request_hash is null or r.device_attested_at is null then
    raise exception 'Receipt binding conflict' using errcode='22023';
  end if;
  -- collection_id can be assigned later by allocation; it is not an ACK identity.
  return jsonb_build_object('contract_version',2,'stored',true,'raw_sms_id',r.id,
    'client_envelope_id',r.client_envelope_id,'owner_user_id',r.receiver_user_id,'body_sha256',r.body_hash);
end;

routine:public.admin_assign_hybrid_recei.source:
declare
  actor_id uuid := auth.uid();
  clean_reason text := btrim(coalesce(p_reason, ''));
  request_hash text;
  prior collect_hybrid.receiving_assignment_requests;
  route public.collection_receivers;
  route_key_value text;
  current_assignment collect_hybrid.member_receiving_assignments;
  new_assignment_id uuid;
  response jsonb;
begin
  perform public.assert_admin_permission('collections.moderate');
  perform public.assert_admin_permission('users.read');
  if not coalesce((select flag.enabled from public.feature_flags flag
    where flag.key = 'hybrid_member_onboarding'), false) then
    raise exception 'Hybrid onboarding is disabled pending controlled rollout';
  end if;
  if p_request_id is null or p_collection_id is null or p_member_record_id is null
     or p_collection_receiver_id is null
     or char_length(clean_reason) not between 8 and 500 then
    raise exception 'Complete receiving assignment and audit reason required';
  end if;
  request_hash := encode(extensions.digest(
    jsonb_build_array(p_collection_id, p_member_record_id, p_collection_receiver_id, clean_reason)::text,
    'sha256'
  ), 'hex');
  perform pg_advisory_xact_lock(hashtextextended('hybrid-route-request:' || p_request_id::text, 0));
  select request.* into prior
  from collect_hybrid.receiving_assignment_requests request
  where request.request_id = p_request_id;
  if prior.request_id is not null then
    if prior.actor_id <> actor_id or prior.input_hash <> request_hash then
      raise exception 'Receiving assignment idempotency key conflict';
    end if;
    return prior.result || jsonb_build_object('replay', true);
  end if;

  select receiver.* into route
  from public.collection_receivers receiver
  where receiver.id = p_collection_receiver_id
    and receiver.collection_id = p_collection_id
    and receiver.is_active
  for update;
  if route.id is null then raise exception 'Active receiving route for this group required'; end if;
  route_key_value := encode(extensions.digest(
    route.receiver_user_id::text || '|' || route.momo_number_hash || '|' || route.network,
    'sha256'
  ), 'hex');
  perform pg_advisory_xact_lock(hashtextextended(
    'hybrid-member-route:' || p_member_record_id::text || ':' || route_key_value,
    0
  ));
  if exists (
    select 1 from collect_hybrid.member_receiving_assignments assignment
    where assignment.member_record_id = p_member_record_id
      and assignment.route_key = route_key_value
      and assignment.status = 'active'
      and assignment.collection_id <> p_collection_id
  ) then
    raise exception 'Member receiving route is already assigned to another group';
  end if;

  select assignment.* into current_assignment
  from collect_hybrid.member_receiving_assignments assignment
  where assignment.member_record_id = p_member_record_id
    and assignment.collection_id = p_collection_id
    and assignment.status = 'active'
  for update;
  if current_assignment.id is not null
     and current_assignment.collection_receiver_id = p_collection_receiver_id then
    new_assignment_id := current_assignment.id;
  else
    if current_assignment.id is not null then
      update collect_hybrid.member_receiving_assignments
      set status = 'ended', ended_at = now()
      where id = current_assignment.id;
    end if;
    insert into collect_hybrid.member_receiving_assignments(
      member_record_id, collection_id, collection_receiver_id, route_key,
      reason, created_by
    ) values (
      p_member_record_id, p_collection_id, p_collection_receiver_id,
      route_key_value, clean_reason, actor_id
    ) returning id into new_assignment_id;
  end if;

  response := jsonb_build_object(
    'ok', true,
    'assignment_id', new_assignment_id,
    'collection_id', p_collection_id,
    'member_record_id', p_member_record_id,
    'collection_receiver_id', p_collection_receiver_id,
    'replay', false
  );
  insert into collect_hybrid.receiving_assignment_requests(request_id, actor_id, input_hash, result)
  values (p_request_id, actor_id, request_hash, response);
  perform public.create_audit_log(
    'collection.hybrid.receiving_assignment_set',
    'collection',
    p_collection_id,
    jsonb_build_object(
      'member_record_id', p_member_record_id,
      'assignment_id', new_assignment_id,
      'collection_receiver_id', p_collection_receiver_id,
      'reason', clean_reason,
      'request_id', p_request_id
    )
  );
  return response;
end;

