routine:public.admin_grant_user_role(uui.source:
declare
  v_role_id uuid;
  v_reason text := trim(coalesce(p_reason, ''));
begin
  perform public.assert_admin_permission('admin_users.manage');
  if v_reason = '' then raise exception 'Reason is required'; end if;
  if not exists (select 1 from public.profiles where id = p_user_id) then
    raise exception 'Admin user profile not found';
  end if;
  select id into v_role_id from public.admin_roles where name = trim(p_role_name);
  if v_role_id is null then raise exception 'Admin role not found'; end if;
  if exists (
    select 1 from public.admin_user_roles
    where user_id = p_user_id and role_id = v_role_id and revoked_at is null
  ) then raise exception 'Admin role is already active'; end if;

  insert into public.admin_user_roles (user_id, role_id, granted_by, reason)
  values (p_user_id, v_role_id, auth.uid(), v_reason);
  perform public.create_audit_log(
    'admin.role.granted', 'profile', p_user_id,
    jsonb_build_object('role', trim(p_role_name), 'reason', v_reason)
  );
  return jsonb_build_object('ok', true, 'status', 'granted');
end;

routine:public.admin_import_bank_stateme.source:
declare
  import_row public.bank_statement_imports%rowtype;
  line jsonb;
  line_number integer := 0;
  line_amount bigint;
  line_booked timestamptz;
  line_value_date date;
  line_key text;
  reconciliation jsonb;
begin
  perform public.assert_admin_permission('bank_reconciliation.manage');
  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'Import reason is required';
  end if;
  if p_file_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'Statement file hash must be lowercase SHA-256';
  end if;
  if p_period_end < p_period_start then
    raise exception 'Statement period is invalid';
  end if;
  if jsonb_typeof(p_lines) <> 'array'
     or jsonb_array_length(p_lines) = 0
     or jsonb_array_length(p_lines) > 5000 then
    raise exception 'Statement must contain between 1 and 5000 lines';
  end if;

  insert into public.bank_statement_imports (
    file_name, file_hash, currency, period_start, period_end,
    status, line_count, imported_by, import_reason
  ) values (
    btrim(p_file_name), lower(p_file_hash), 'EUR', p_period_start, p_period_end,
    'processing', jsonb_array_length(p_lines), auth.uid(), btrim(p_reason)
  )
  on conflict (file_hash) do nothing
  returning * into import_row;

  if import_row.id is null then
    raise exception 'Statement file was already imported';
  end if;

  for line in select value from jsonb_array_elements(p_lines)
  loop
    line_number := line_number + 1;
    line_amount := (line ->> 'amount_minor')::bigint;
    line_booked := (line ->> 'booked_at')::timestamptz;
    line_value_date := coalesce((line ->> 'value_date')::date, line_booked::date);
    if line_amount <= 0 then
      raise exception 'Statement line % amount must be positive', line_number;
    end if;
    if upper(coalesce(line ->> 'currency', 'EUR')) <> 'EUR' then
      raise exception 'Statement line % currency must be EUR', line_number;
    end if;
    if line_value_date < p_period_start or line_value_date > p_period_end then
      raise exception 'Statement line % is outside the declared period', line_number;
    end if;

    line_key := encode(extensions.digest(convert_to(
      coalesce(upper(btrim(line ->> 'bank_transaction_id')), '') || '|' ||
      coalesce(upper(btrim(line ->> 'end_to_end_id')), '') || '|' ||
      coalesce(upper(btrim(line ->> 'transfer_reference')), '') || '|' ||
      line_amount::text || '|EUR|' || line_value_date::text,
      'UTF8'
    ), 'sha256'), 'hex');

    insert into public.bank_statement_lines (
      import_id,
      line_number,
      transaction_key,
      bank_transaction_id,
      end_to_end_id,
      transfer_reference,
      payer_name,
      amount_minor,
      currency,
      booked_at,
      value_date
    ) values (
      import_row.id,
      line_number,
      line_key,
      nullif(upper(btrim(line ->> 'bank_transaction_id')), ''),
      nullif(upper(btrim(line ->> 'end_to_end_id')), ''),
      nullif(upper(btrim(line ->> 'transfer_reference')), ''),
      nullif(btrim(line ->> 'payer_name'), ''),
      line_amount,
      'EUR',
      line_booked,
      line_value_date
    ) on conflict (transaction_key) do nothing;
  end loop;

  update public.bank_statement_imports
  set status = 'processed', completed_at = now()
  where id = import_row.id
  returning * into import_row;

  reconciliation := public.run_daily_bank_reconciliation(
    p_period_end,
    'Statement import ' || import_row.id::text || ': ' || btrim(p_reason)
  );

  perform public.create_audit_log(
    'bank_statement.imported',
    'bank_statement_import',
    import_row.id,
    jsonb_build_object(
      'file_name', import_row.file_name,
      'file_hash', import_row.file_hash,
      'line_count', import_row.line_count,
      'period_start', import_row.period_start,
      'period_end', import_row.period_end
    )
  );

  return to_jsonb(import_row) || jsonb_build_object('reconciliation', reconciliation);
end;

routine:public.admin_inspect_interrupted.source:
declare sid uuid; s collect_hybrid.roster_import_sources; initial uuid; latest uuid; payload text; begin
 sid:=collect_hybrid.require_fresh_roster_auth();
 if p_etag is null or p_etag !~ '^[a-f0-9]{64}$' then
  raise exception 'roster_draft_superseded' using errcode='55000'; end if;
 s:=collect_hybrid.require_interrupted_roster(p_import_id,sid,p_etag);
 select id into initial from collect_hybrid.roster_import_revisions where import_id=s.id and revision_number=1;
 select id into latest from collect_hybrid.roster_import_revisions where import_id=s.id order by revision_number desc limit 1;
 payload:=collect_hybrid.roster_interrupted_draft(s.id,latest);
 perform collect_hybrid.roster_recovery_payload(payload,collect_hybrid.roster_recovery_sha(payload),'draft');
 if s.expires_at<=clock_timestamp() then raise exception 'roster_import_expired' using errcode='55000'; end if;
 return jsonb_build_object('contract_version',1,'ok',true,'import_id',s.id,'actor_id',auth.uid(),
  'destination_session_id',sid,'etag',p_etag,'initial_preview',collect_hybrid.roster_revision_receipt(initial),
  'latest_preview',collect_hybrid.roster_revision_receipt(latest),'draft_payload',payload,
  'draft_sha256',collect_hybrid.roster_recovery_sha(payload),'expires_at',s.expires_at);
end

