routine:public.admin_reverse_momo_paymen.source:
declare
  actor_id uuid := auth.uid();
  clean_reason text := btrim(coalesce(p_reason, ''));
  input_hash text;
  prior collect_hybrid.momo_reversal_requests;
  payment_row public.payments;
  original_entry collect_hybrid.momo_journal_entries;
  reversal_id uuid;
  group_balance bigint;
  member_balance bigint;
  response jsonb;
begin
  perform public.assert_admin_permission('payments.allocate');
  if p_request_id is null or p_payment_id is null
     or char_length(clean_reason) not between 8 and 500 then
    raise exception 'Payment, request ID and complete reversal reason required';
  end if;
  input_hash := encode(extensions.digest(
    jsonb_build_array(p_payment_id, clean_reason)::text, 'sha256'
  ), 'hex');
  perform pg_advisory_xact_lock(hashtextextended('hybrid-momo-reversal:' || p_request_id::text, 0));
  select request.* into prior
  from collect_hybrid.momo_reversal_requests request
  where request.request_id = p_request_id;
  if prior.request_id is not null then
    if prior.actor_id <> actor_id or prior.payment_id <> p_payment_id
       or prior.input_hash <> input_hash then
      raise exception 'MoMo reversal idempotency key conflict';
    end if;
    return prior.result || jsonb_build_object('replay', true);
  end if;

  select payment.* into payment_row
  from public.payments payment
  where payment.id = p_payment_id
  for update;
  if payment_row.id is null then raise exception 'Payment not found'; end if;
  if payment_row.status <> 'posted' then raise exception 'Only a posted payment can be reversed'; end if;
  select entry.* into original_entry
  from collect_hybrid.momo_journal_entries entry
  where entry.payment_id = payment_row.id and entry.entry_type = 'receipt'
  for share;
  if original_entry.id is null then raise exception 'Canonical receipt journal required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'hybrid-momo-group-balance:' || payment_row.collection_id::text, 0
  ));
  if payment_row.member_record_id is not null then
    perform pg_advisory_xact_lock(hashtextextended(
      'hybrid-momo-member-balance:' || payment_row.collection_id::text || ':' || payment_row.member_record_id::text,
      0
    ));
  end if;

  insert into collect_hybrid.momo_journal_entries(
    payment_id, parsed_event_id, collection_id, member_record_id,
    entry_type, amount_rwf, external_reference, reverses_entry_id, created_by
  ) values (
    payment_row.id, payment_row.parsed_event_id, payment_row.collection_id,
    payment_row.member_record_id, 'reversal', payment_row.amount_rwf,
    'reversal:' || original_entry.id::text, original_entry.id, actor_id
  ) returning id into reversal_id;
  insert into collect_hybrid.momo_journal_lines(
    journal_entry_id, account_code, direction, amount_rwf
  ) values
    (reversal_id, 'member_savings_liability:RWF', 'debit', payment_row.amount_rwf),
    (reversal_id, 'momo_receiving_asset:RWF', 'credit', payment_row.amount_rwf);

  -- Keep every compatibility reader financially equivalent without mutating
  -- the original immutable projection rows.
  insert into public.ledger_entries(
    payment_id, collection_id, user_id, member_record_id,
    entry_type, amount_rwf, currency, visibility, metadata
  )
  select ledger.payment_id, ledger.collection_id, ledger.user_id,
    ledger.member_record_id, ledger.entry_type, -ledger.amount_rwf,
    ledger.currency, ledger.visibility,
    ledger.metadata || jsonb_build_object(
      'compensates_ledger_entry_id', ledger.id,
      'momo_reversal_journal_entry_id', reversal_id,
      'reversal_request_id', p_request_id
    )
  from public.ledger_entries ledger
  where ledger.payment_id = payment_row.id
    and ledger.entry_type in ('collection_credit', 'member_credit')
    and ledger.amount_rwf > 0
  on conflict do nothing;

  update collect_hybrid.collection_balances balance
  set confirmed_rwf = balance.confirmed_rwf - payment_row.amount_rwf,
      updated_at = now()
  where balance.collection_id = payment_row.collection_id
    and balance.confirmed_rwf >= payment_row.amount_rwf
  returning confirmed_rwf into group_balance;
  if group_balance is null then raise exception 'Group balance cannot support this reversal'; end if;
  if payment_row.member_record_id is not null then
    update collect_hybrid.member_balances balance
    set confirmed_rwf = balance.confirmed_rwf - payment_row.amount_rwf,
        updated_at = now()
    where balance.collection_id = payment_row.collection_id
      and balance.member_record_id = payment_row.member_record_id
      and balance.confirmed_rwf >= payment_row.amount_rwf
    returning confirmed_rwf into member_balance;
    if member_balance is null then raise exception 'Member balance cannot support this reversal'; end if;
  end if;
  insert into collect_hybrid.momo_balance_snapshots(
    journal_entry_id, payment_id, collection_id, member_record_id,
    event_type, delta_rwf, member_balance_after_rwf, group_balance_after_rwf
  ) values (
    reversal_id, payment_row.id, payment_row.collection_id, payment_row.member_record_id,
    'reversal', -payment_row.amount_rwf, member_balance, group_balance
  );
  update public.payments set status = 'reversed' where id = payment_row.id;
  response := jsonb_build_object(
    'ok', true,
    'payment_id', payment_row.id,
    'reversal_journal_entry_id', reversal_id,
    'member_balance_after_rwf', member_balance,
    'group_balance_after_rwf', group_balance,
    'replay', false
  );
  insert into collect_hybrid.momo_reversal_requests(request_id, payment_id, actor_id, input_hash, result)
  values (p_request_id, payment_row.id, actor_id, input_hash, response);
  perform public.create_audit_log(
    'payment.reversed.momo', 'payment', payment_row.id,
    jsonb_build_object(
      'reason', clean_reason,
      'request_id', p_request_id,
      'reversal_journal_entry_id', reversal_id
    )
  );
  return response;
end;

routine:public.admin_review_bank_allocat.source:
declare
  request public.bank_allocation_change_requests%rowtype;
  transaction_row public.bank_transactions%rowtype;
  intent public.bank_transfer_intents%rowtype;
  allocation public.bank_transaction_allocations%rowtype;
begin
  perform public.assert_admin_permission('bank_allocations.approve');
  if char_length(btrim(coalesce(p_review_note, ''))) < 8 then
    raise exception 'Review note must be at least 8 characters';
  end if;
  select * into request
  from public.bank_allocation_change_requests
  where id = p_request_id
  for update;
  if request.id is null or request.status <> 'pending' then
    raise exception 'Pending allocation request was not found';
  end if;
  if request.proposed_by = auth.uid() then
    raise exception 'Maker-checker control prohibits approving your own allocation';
  end if;
  if not p_approve then
    update public.bank_allocation_change_requests
    set status = 'rejected', reviewed_by = auth.uid(),
        review_note = btrim(p_review_note), reviewed_at = now()
    where id = request.id
    returning * into request;
    perform public.create_audit_log(
      'bank_allocation.rejected', 'bank_allocation_change_request', request.id,
      jsonb_build_object('review_note', request.review_note)
    );
    return to_jsonb(request);
  end if;

  select * into transaction_row
  from public.bank_transactions
  where id = request.bank_transaction_id
  for update;
  select * into intent
  from public.bank_transfer_intents
  where id = request.bank_transfer_intent_id
  for update;
  if transaction_row.currency <> intent.currency
     or transaction_row.amount_minor <> intent.amount_minor
     or transaction_row.status in ('reconciled', 'returned')
     or intent.status in ('reconciled', 'returned', 'cancelled', 'expired') then
    raise exception 'The proposed allocation is no longer valid';
  end if;

  insert into public.bank_transaction_allocations (
    bank_transaction_id, bank_transfer_intent_id, collection_id,
    contributor_user_id, allocation_method, confidence, reason, allocated_by
  ) values (
    transaction_row.id, intent.id, intent.collection_id,
    intent.contributor_user_id, 'manual_maker_checker', 1,
    request.reason || ' | Checker: ' || btrim(p_review_note), auth.uid()
  ) returning * into allocation;

  update public.bank_transactions
  set destination_id = intent.destination_id,
      status = 'received', updated_at = now()
  where id = transaction_row.id;
  update public.bank_transfer_intents
  set status = 'received_unreconciled',
      evidence_received_at = coalesce(evidence_received_at, transaction_row.evidence_received_at),
      exception_reason = null, updated_at = now()
  where id = intent.id;
  update public.bank_evidence_events event
  set allocation_status = 'allocated',
      review_reason = 'Approved manual maker-checker allocation'
  from public.payment_evidence_links link
  where link.bank_transaction_id = transaction_row.id
    and link.evidence_event_id = event.id;
  update public.reconciliation_exceptions
  set status = 'resolved', resolved_by = auth.uid(),
      resolution_note = btrim(p_review_note), resolved_at = now()
  where bank_transaction_id = transaction_row.id
    and status in ('open', 'reviewing')
    and exception_type in ('missing_reference', 'no_exact_intent', 'ambiguous_intent');
  update public.bank_allocation_change_requests
  set status = 'approved', reviewed_by = auth.uid(),
      review_note = btrim(p_review_note), reviewed_at = now()
  where id = request.id
  returning * into request;
  perform public.create_audit_log(
    'bank_allocation.approved', 'bank_transaction_allocation', allocation.id,
    jsonb_build_object(
      'request_id', request.id,
      'bank_transaction_id', transaction_row.id,
      'bank_transfer_intent_id', intent.id,
      'review_note', request.review_note
    )
  );
  return to_jsonb(request) || jsonb_build_object('allocation_id', allocation.id);
end;

routine:public.admin_revoke_user_role(uu.source:
declare
  v_role_id uuid;
  v_reason text := trim(coalesce(p_reason, ''));
  v_effective_owner_count integer;
begin
  perform public.assert_admin_permission('admin_users.manage');
  if v_reason = '' then raise exception 'Reason is required'; end if;
  select id into v_role_id from public.admin_roles where name = trim(p_role_name);
  if v_role_id is null then raise exception 'Admin role not found'; end if;

  if trim(p_role_name) = 'platform_owner' then
    perform pg_advisory_xact_lock(hashtext('collect_admin_platform_owner_roster'));
    if p_user_id = auth.uid() then
      raise exception 'You cannot revoke your own platform owner role';
    end if;
    select count(*) into v_effective_owner_count
    from public.profiles profile
    where coalesce(profile.is_platform_admin, false)
       or exists (
         select 1
         from public.admin_user_roles owner_role
         join public.admin_roles role on role.id = owner_role.role_id
         where owner_role.user_id = profile.id
           and owner_role.revoked_at is null
           and role.name = 'platform_owner'
       );
    if v_effective_owner_count <= 1
       and not coalesce((select is_platform_admin from public.profiles where id = p_user_id), false) then
      raise exception 'The last platform owner cannot be revoked';
    end if;
  end if;

  update public.admin_user_roles
  set revoked_at = now(), revoked_by = auth.uid(), revoke_reason = v_reason
  where user_id = p_user_id and role_id = v_role_id and revoked_at is null;
  if not found then raise exception 'Active admin role not found'; end if;

  perform public.create_audit_log(
    'admin.role.revoked', 'profile', p_user_id,
    jsonb_build_object('role', trim(p_role_name), 'reason', v_reason)
  );
  return jsonb_build_object('ok', true, 'status', 'revoked');
end;

routine:public.admin_set_collect_payee_s.source:
declare
  clean_reason text := btrim(coalesce(p_reason, ''));
  target_collection_id uuid;
begin
  perform public.assert_admin_permission('receivers.manage');
  if char_length(clean_reason) < 8 then
    raise exception 'Status reason must be at least 8 characters';
  end if;

  select receiver.collection_id
  into target_collection_id
  from public.collection_receivers receiver
  join public.collections collection on collection.id = receiver.collection_id
  where receiver.id = p_payee_id
    and collection.is_platform_sponsored
  for update of receiver;

  if target_collection_id is null then
    raise exception 'Official payee not found';
  end if;

  if p_active then
    update public.collection_receivers receiver
    set is_active = false
    where receiver.collection_id = target_collection_id
      and receiver.id <> p_payee_id
      and receiver.is_active;
  end if;

  update public.collection_receivers
  set is_active = p_active
  where id = p_payee_id;

  perform public.create_audit_log(
    case when p_active then 'payee.official.activated'
      else 'payee.official.deactivated' end,
    'collection_receiver',
    p_payee_id,
    jsonb_build_object(
      'reason', clean_reason,
      'collection_id', target_collection_id,
      'active', p_active,
      'route_immutable', true
    )
  );

  return jsonb_build_object(
    'ok', true,
    'payee_id', p_payee_id,
    'status', case when p_active then 'active' else 'inactive' end,
    'route_immutable', true
  );
end;

