routine:public.admin_set_group_active(uu.source:
declare
  collection_row public.collections;
  clean_reason text := btrim(coalesce(p_reason, ''));
  next_status public.collection_visibility;
begin
  perform public.assert_admin_permission('collections.moderate');
  if char_length(clean_reason) < 8 then
    raise exception 'Lifecycle reason must be at least 8 characters';
  end if;

  select collection.*
  into collection_row
  from public.collections collection
  where collection.id = p_collection_id
  for update;

  if collection_row.id is null then
    raise exception 'Group not found';
  end if;

  if p_active and collection_row.is_platform_sponsored and not exists (
    select 1
    from public.collection_receivers receiver
    where receiver.collection_id = p_collection_id
      and receiver.is_active
  ) then
    raise exception 'Activate an official payee before activating this public group';
  end if;

  next_status := case
    when not p_active then 'archived'::public.collection_visibility
    when collection_row.is_platform_sponsored then 'public_approved'::public.collection_visibility
    else 'private'::public.collection_visibility
  end;

  update public.collections
  set public_status = next_status,
      visibility = next_status,
      moderation_status = case
        when not p_active then moderation_status
        when collection_row.is_platform_sponsored then 'approved'
        else moderation_status
      end,
      archived_at = case when p_active then null else now() end,
      updated_at = now()
  where id = p_collection_id;

  perform public.create_audit_log(
    case when p_active then 'collection.activated' else 'collection.deactivated' end,
    'collection',
    p_collection_id,
    jsonb_build_object(
      'reason', clean_reason,
      'active', p_active,
      'previous_status', collection_row.public_status::text,
      'next_status', next_status::text,
      'is_platform_sponsored', collection_row.is_platform_sponsored
    )
  );

  return jsonb_build_object(
    'ok', true,
    'collection_id', p_collection_id,
    'active', p_active,
    'status', case when p_active then 'active' else 'inactive' end,
    'visibility', next_status::text
  );
end;

routine:public.admin_system_health(text).source:
declare authority_session uuid; t timestamptz:=clock_timestamp(); window_start timestamptz:=t-interval '24 hours';
 metrics jsonb:='{}'; alerts jsonb; samples jsonb; scheduler_count integer;
 scheduler_active integer; last_scheduler timestamptz; overall text;
begin
 -- Session/Auth locks precede the roster lock consistently with other RPCs.
 begin authority_session:=public._lock_notification_registration_session();
 exception when sqlstate '42501' then raise exception 'operational_health_session_required' using errcode='42501';end;
 perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
 -- Lock the actual grant, approval and permission rows. A stale snapshot
 -- receives40001 after revocation rather than reading an obsolete EXISTS.
 begin
  perform collect_hybrid.require_roster_actor_authority(auth.uid(),authority_session,
    'platform_owner',array['system_health.read']);
 exception when sqlstate '42501' then
  raise exception 'operational_health_permission_required' using errcode='42501';end;
 if not public.has_admin_permission('system_health.read',auth.uid()) then
  raise exception 'operational_health_permission_required' using errcode='42501';end if;
 if p_id is not null and p_id<>'system' then
  raise exception 'operational_health_invalid' using errcode='22023';end if;

 select jsonb_build_object('durable_receipts_24h',count(*) filter(where ingested_at>=window_start),
  'sms_pending',count(*) filter(where parse_status='pending'),
  'sms_pending_age_seconds',floor(extract(epoch from t-min(ingested_at) filter(where parse_status='pending')))::bigint,
  'sms_failed_24h',count(*) filter(where parse_status='failed' and ingested_at>=window_start),
  'sms_parsed_24h',count(*) filter(where parse_status='parsed' and ingested_at>=window_start),
  'sms_expired_parse_leases',count(*) filter(where parse_status='pending' and parse_lease_id is not null and parse_started_at<t-interval '5 minutes'))
 into samples from public.raw_payment_sms where parse_status='pending' or ingested_at>=window_start;
 metrics:=metrics||samples;
 select jsonb_build_object('unallocated_events',count(*)) into samples
 from public.parsed_payment_events where allocation_status in ('unallocated','ambiguous','needs_review');metrics:=metrics||samples;
 select jsonb_build_object('payments_review',count(*) filter(where status='review'),
  'payment_review_age_seconds',floor(extract(epoch from t-min(created_at) filter(where status='review')))::bigint,
  'payments_posted_24h',count(*) filter(where status='posted' and posted_at>=window_start))
 into samples from public.payments where status='review' or posted_at>=window_start;metrics:=metrics||samples;
 select jsonb_build_object('reconciliation_open',count(*)) into samples
 from collect_hybrid.momo_reconciliation_exceptions where status='open';metrics:=metrics||samples;
 select jsonb_build_object('reversals_24h',count(*)) into samples
 from collect_hybrid.momo_journal_entries where entry_type='reversal' and posted_at>=window_start;metrics:=metrics||samples;
 select jsonb_build_object('finality_processing',count(*) filter(where status='processing'),
  'finality_processed_24h',count(*) filter(where status='processed' and processed_at>=window_start))
 into samples from public.provider_finality_requests where status='processing' or processed_at>=window_start;metrics:=metrics||samples;
 select jsonb_build_object('push_queued',count(*) filter(where status='queued'),
  'push_due',count(*) filter(where status='queued' and next_attempt_at<=t),
  'push_due_age_seconds',floor(extract(epoch from t-min(next_attempt_at) filter(where status='queued' and next_attempt_at<=t)))::bigint,
  'push_processing',count(*) filter(where status='processing'),
  'push_expired_leases',count(*) filter(where status='processing' and claim_expires_at<=t),
  'push_missing_leases',count(*) filter(where status='processing' and claim_expires_at is null),
  'push_failed',count(*) filter(where status='failed'))
 into samples from public.notification_deliveries where status in ('queued','processing','failed');metrics:=metrics||samples;
 select jsonb_build_object('push_attempts_24h',count(*),'push_failed_24h',count(*) filter(where outcome='failed'),
  'push_provider_accepts_24h',count(*) filter(where outcome='sent'),'push_retry_24h',count(*) filter(where outcome='retry'),
  'push_latency_p95_ms',ceil(percentile_cont(0.95) within group(order by latency_ms))::bigint)
 into samples from public.notification_delivery_attempts where attempted_at>=window_start;metrics:=metrics||samples;
 select jsonb_build_object('receipt_ack_generated_24h',coalesce(sum(event_count) filter(where event_code='receipt_ack_generated'),0),
  'receipt_rejected_24h',coalesce(sum(event_count) filter(where event_code='receipt_rejected'),0),
  'receipt_telemetry_age_seconds',floor(extract(epoch from t-max(bucket_at)))::bigint,
  'receipt_ack_latency_mean_ms',ceil(sum(duration_total_ms) filter(where event_code='receipt_ack_generated')::numeric /
    nullif(sum(measured_count) filter(where event_code='receipt_ack_generated'),0))::bigint)
 into samples from collect_security.operational_metric_buckets where bucket_at>=window_start;metrics:=metrics||samples;
 select count(*),count(*) filter(where active) into scheduler_count,scheduler_active from cron.job
 where jobname='collect-dispatch-notifications';
 select max(d.end_time) into last_scheduler from cron.job_run_details d join cron.job j on j.jobid=d.jobid
 where j.jobname='collect-dispatch-notifications' and d.status='succeeded';
 metrics:=metrics||jsonb_build_object('push_scheduler_age_seconds',floor(extract(epoch from t-last_scheduler))::bigint);
 alerts:=collect_security.operational_health_alerts(metrics);
 overall:=case when exists(select 1 from jsonb_array_elements(alerts) a where a->>'state'='attention') then 'attention'
  when exists(select 1 from jsonb_array_elements(alerts) a where a->>'state'='unknown') then 'unknown' else 'ok' end;
 return jsonb_build_object('id','system','contract_version',1,'database','reachable','auth','authenticated',
  'parser_pending_sms',metrics->'sms_pending','failed_sms_parse',metrics->'sms_failed_24h',
  'unallocated_events',metrics->'unallocated_events','queued_notifications',metrics->'push_queued',
  'processing_notifications',metrics->'push_processing','failed_notifications',metrics->'push_failed',
  'checked_at',t,'metrics',metrics,'alerts',alerts,'health_status',overall,
  'sample_valid_until',t+interval '60 seconds','window_seconds',86400,'threshold_version',1,
  'scheduler',jsonb_build_object('state',case when scheduler_count<>1 then 'unknown'
    when scheduler_active=1 then 'enabled' else 'disabled' end,'configuration_verified',false),
  'evidence_limits',jsonb_build_array('ACK generation does not prove device receipt.',
   'Provider acceptance does not prove user delivery.','Scheduler activation does not prove provider configuration.'));
end

routine:public.admin_transfer_interrupte.source:
declare sid uuid; s collect_hybrid.roster_import_sources; root_source collect_hybrid.roster_import_sources;
 prior collect_hybrid.roster_recovery_transfers; base collect_hybrid.roster_import_revisions;
 old_draft collect_hybrid.roster_import_editor_drafts; old_revision uuid; intents_sha text;
 proof text; fingerprint text; destination uuid:=gen_random_uuid(); lookup_ref uuid:=gen_random_uuid();
 revision uuid:=gen_random_uuid(); checkpoint uuid:=gen_random_uuid(); payload text; preview jsonb; candidates jsonb; begin
 sid:=collect_hybrid.require_fresh_roster_auth();
 perform collect_hybrid.lock_roster_recovery_budget();
 if p_request_id is null or p_import_id is null or p_etag is null or p_etag !~ '^[a-f0-9]{64}$' or p_human_affirmed is distinct from true then
  raise exception 'roster_confirmation_required' using errcode='22023'; end if;
 fingerprint:=collect_hybrid.roster_digest(jsonb_build_array(p_request_id,p_import_id,p_etag,true,auth.uid(),sid));
 select * into prior from collect_hybrid.roster_recovery_transfers where request_id=p_request_id;
 if prior.request_id is not null then
  if prior.actor_id<>auth.uid() or prior.to_session_id<>sid or prior.request_sha256<>fingerprint then
   raise exception 'roster_request_conflict' using errcode='55000'; end if;
  perform collect_hybrid.roster_recovery_leaf(prior.to_import_id,true);
  return collect_hybrid.roster_transfer_ack(prior.request_id);
 end if;
 s:=collect_hybrid.require_interrupted_roster(p_import_id,sid,p_etag);
 select * into root_source from collect_hybrid.roster_import_sources where id=collect_hybrid.roster_recovery_root(s.id);
 if (select count(*) from collect_hybrid.roster_recovery_transfers where root_import_id=root_source.id)>=8
  or (select count(*) from collect_hybrid.roster_import_sources where actor_id=auth.uid() and created_at>clock_timestamp()-interval '24 hours')>=100
  or (select count(*) from collect_hybrid.roster_import_editor_drafts where actor_id=auth.uid() and expires_at>clock_timestamp())>=40
  or (select count(*) from collect_hybrid.roster_import_editor_drafts where session_id=sid and expires_at>clock_timestamp())>=20 then
  raise exception 'roster_recovery_limit' using errcode='55000'; end if;
 select * into base from collect_hybrid.roster_import_revisions where import_id=root_source.id and revision_number=1;
 select jsonb_agg(jsonb_build_object('source_row',x->'source_row','member_name',x->'member_name',
  'momo_name',x->'momo_name','momo_number',x->'momo_number','confidence',x->'confidence') order by ord)
 into candidates from jsonb_array_elements(base.preview->'rows') with ordinality a(x,ord);
 preview:=collect_hybrid.roster_preview(candidates,false);
 select id into old_revision from collect_hybrid.roster_import_revisions where import_id=s.id order by revision_number desc limit 1;
 select * into old_draft from collect_hybrid.roster_import_editor_drafts where import_id=s.id;
 select collect_hybrid.roster_digest(coalesce(jsonb_agg(jsonb_build_array(request_id,kind,payload_sha256,expires_at) order by request_id),'[]')) into intents_sha
  from collect_hybrid.roster_import_recovery_intents where import_id=s.id;
 proof:=collect_hybrid.roster_original_proof(root_source.id);
 if proof is null then raise exception 'roster_recovery_lineage_invalid' using errcode='55000'; end if;
 payload:=collect_hybrid.roster_interrupted_draft(s.id,revision);
 perform collect_hybrid.roster_recovery_payload(payload,collect_hybrid.roster_recovery_sha(payload),'draft');
 -- Audit comes first with a deferred destination FK. Triggers validate the
 -- exact copy against this immutable lineage, never a caller-supplied flag/GUC.
 insert into collect_hybrid.roster_recovery_transfers(request_id,root_import_id,from_import_id,to_import_id,
  actor_id,from_session_id,to_session_id,destination_reference_id,initial_revision_id,checkpoint_id,draft_sha256,
  from_revision_id,from_checkpoint_id,from_draft_sha256,from_intents_sha256,source_etag,request_sha256,original_proof_sha256,expires_at)
 values(p_request_id,root_source.id,s.id,destination,auth.uid(),s.session_id,sid,lookup_ref,revision,checkpoint,
  collect_hybrid.roster_recovery_sha(payload),old_revision,old_draft.checkpoint_id,old_draft.payload_sha256,intents_sha,p_etag,fingerprint,collect_hybrid.roster_recovery_sha(proof),root_source.expires_at);
 insert into collect_hybrid.roster_import_sources(id,request_id,actor_id,session_id,source_kind,source_sha256,source_size,
  client_filename,declared_mime,detected_type,derived_sha256,derived_size,ai_consent,consent_version,
  parser_version,schema_version,input_sha256,expires_at)
 values(destination,lookup_ref,s.actor_id,sid,root_source.source_kind,root_source.source_sha256,root_source.source_size,
  root_source.client_filename,root_source.declared_mime,root_source.detected_type,root_source.derived_sha256,
  root_source.derived_size,root_source.ai_consent,root_source.consent_version,root_source.parser_version,
  root_source.schema_version,root_source.input_sha256,root_source.expires_at);
 insert into collect_hybrid.roster_import_revisions(id,import_id,extraction_id,revision_number,actor_id,session_id,
  processing_method,preview,normalized_rows,reviewed_rows_sha256,input_sha256)
 values(revision,destination,base.extraction_id,1,auth.uid(),sid,base.processing_method,preview,
  preview->'normalized_rows',collect_hybrid.roster_digest(preview->'normalized_rows'),base.input_sha256);
 insert into collect_hybrid.roster_import_results(import_id,actor_id,session_id,state,revision_id,processing_metadata,input_sha256)
 select destination,auth.uid(),sid,'preview_ready',revision,processing_metadata,input_sha256
 from collect_hybrid.roster_import_results where import_id=root_source.id and state='preview_ready';
 insert into collect_hybrid.roster_import_editor_drafts(import_id,checkpoint_id,actor_id,session_id,payload,payload_sha256,expires_at)
 values(destination,checkpoint,auth.uid(),sid,payload,collect_hybrid.roster_recovery_sha(payload),root_source.expires_at);
 perform public.create_audit_log('roster.import.recovery_transferred','roster_import',destination,
  jsonb_build_object('request_id',p_request_id,'from_import_id',s.id,'root_import_id',root_source.id,
   'original_proof_sha256',collect_hybrid.roster_recovery_sha(proof),'human_review_reset',true));
 if root_source.expires_at<=clock_timestamp() then raise exception 'roster_import_expired' using errcode='55000'; end if;
 return collect_hybrid.roster_transfer_ack(p_request_id);
end

routine:public.admin_update_collect_paye.source:
declare
  clean_label text := btrim(coalesce(p_label, ''));
  clean_reason text := btrim(coalesce(p_reason, ''));
  target_collection_id uuid;
begin
  perform public.assert_admin_permission('receivers.manage');
  if char_length(clean_label) not between 2 and 120 then
    raise exception 'Official payee name must be between 2 and 120 characters';
  end if;
  if char_length(clean_reason) < 8 then
    raise exception 'Change reason must be at least 8 characters';
  end if;

  select receiver.collection_id
  into target_collection_id
  from public.collection_receivers receiver
  join public.collections collection on collection.id = receiver.collection_id
  where receiver.id = p_payee_id
    and collection.is_platform_sponsored
  for update of receiver;

  if target_collection_id is null then
    raise exception 'Official payee not found';
  end if;

  update public.collection_receivers
  set label = clean_label
  where id = p_payee_id;

  update public.collections collection
  set receiver_display_label = clean_label,
      updated_at = now()
  where collection.id = target_collection_id;

  perform public.create_audit_log(
    'payee.official.renamed',
    'collection_receiver',
    p_payee_id,
    jsonb_build_object(
      'reason', clean_reason,
      'collection_id', target_collection_id,
      'label', clean_label,
      'route_immutable', true
    )
  );

  return jsonb_build_object(
    'ok', true,
    'payee_id', p_payee_id,
    'label', clean_label,
    'route_immutable', true
  );
end;

routine:public.admin_update_collection_s.source:
declare
  current_row public.collections;
  owner_user_id uuid;
begin
  if coalesce(trim(p_reason), '') = '' then raise exception 'Reason is required'; end if;
  if p_status not in ('private', 'public_approved', 'public_rejected', 'archived') then
    raise exception 'Unsupported collection support status';
  end if;
  if p_status in ('public_approved', 'public_rejected') then
    perform public.assert_admin_permission('public_requests.review');
  else
    perform public.assert_admin_permission('collections.moderate');
  end if;

  select c.* into current_row from public.collections c where c.id = p_collection_id;
  if current_row.id is null then raise exception 'Collection not found'; end if;
  if p_status in ('public_approved', 'public_rejected')
     and current_row.public_status <> 'public_requested'::public.collection_visibility then
    raise exception 'Group does not have a pending public request';
  end if;

  update public.collections
  set public_status = p_status::public.collection_visibility,
      visibility = case
        when p_status = 'public_approved' then 'public_approved'::public.collection_visibility
        when p_status = 'archived' then 'archived'::public.collection_visibility
        else 'private'::public.collection_visibility
      end,
      archived_at = case when p_status = 'archived' then now() else null end,
      updated_at = now()
  where id = p_collection_id
  returning creator_user_id into owner_user_id;

  perform public.create_audit_log(
    'collection.support_status.updated',
    'collection',
    p_collection_id,
    jsonb_build_object('status', p_status, 'reason', trim(p_reason))
  );

  perform public.enqueue_notification_template_event(
    owner_user_id,
    'group.update.default',
    jsonb_build_object('group', current_row.title),
    p_collection_id,
    '/groups/' || p_collection_id::text,
    'en'
  );
  return jsonb_build_object('ok', true, 'status', p_status);
end;

routine:public.admin_update_platform_pub.source:
declare
  collection_row public.collections;
  receiver_row public.collection_receivers;
  clean_type text := lower(trim(coalesce(p_collection_type, '')));
begin
  perform public.assert_admin_permission('collections.moderate');
  if nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception 'Reason is required';
  end if;
  if char_length(trim(coalesce(p_title, ''))) not between 3 and 120 then
    raise exception 'Group name must be between 3 and 120 characters';
  end if;
  if clean_type not in ('ikimina', 'sport', 'church', 'wedding', 'other') then
    raise exception 'Unsupported collection type';
  end if;
  select collection.*
  into collection_row
  from public.collections collection
  where collection.id = p_collection_id
  for update;

  if collection_row.id is null or not collection_row.is_platform_sponsored then
    raise exception 'Platform-sponsored public group not found';
  end if;

  update public.collections
  set title = trim(p_title),
      description = trim(coalesce(p_description, '')),
      category = case clean_type
        when 'sport' then 'Sports team'
        when 'church' then 'Church'
        when 'wedding' then 'Wedding'
        when 'ikimina' then 'Family / friends'
        else 'Other'
      end,
      collection_type = clean_type,
      category_subtype = nullif(trim(coalesce(p_category_subtype, '')), ''),
      purpose_label = nullif(trim(coalesce(p_purpose_label, '')), ''),
      receiver_display_label = trim(p_receiver_label),
      visibility = 'public_approved',
      public_status = 'public_approved',
      moderation_status = 'approved',
      archived_at = null,
      updated_at = now()
  where id = p_collection_id;

  select receiver.*
  into receiver_row
  from public.collection_receivers receiver
  where receiver.collection_id = p_collection_id
    and receiver.is_active
  order by receiver.created_at
  limit 1
  for update;

  if receiver_row.id is null then
    raise exception 'Create the immutable MoMo route from the Payees workspace first';
  end if;

  update public.collection_receivers
  set label = trim(p_receiver_label)
  where id = receiver_row.id
  returning * into receiver_row;

  perform public.create_audit_log(
    'collection.platform_public.updated',
    'collection',
    p_collection_id,
    jsonb_build_object(
      'reason', trim(p_reason),
      'title', trim(p_title),
      'collection_type', clean_type,
      'category_subtype', nullif(trim(coalesce(p_category_subtype, '')), ''),
      'purpose_label', nullif(trim(coalesce(p_purpose_label, '')), ''),
      'receiver_label', trim(p_receiver_label)
    )
  );

  return jsonb_build_object(
    'ok', true,
    'collection_id', p_collection_id,
    'public_status', 'public_approved',
    'receiver_id', receiver_row.id
  );
end;

declare
  prior_visibility public.collection_visibility;
  prior_public_status public.collection_visibility;
  prior_archived_at timestamptz;
  result jsonb;
begin
  perform public.assert_admin_permission('collections.moderate');

  select collection.visibility, collection.public_status, collection.archived_at
  into prior_visibility, prior_public_status, prior_archived_at
  from public.collections collection
  where collection.id = p_collection_id
    and collection.is_platform_sponsored
  for update;

  if prior_public_status is null then
    raise exception 'Platform-sponsored public group not found';
  end if;

  result := public.admin_update_platform_public_group(
    p_collection_id,
    p_title,
    p_description,
    p_collection_type,
    p_category_subtype,
    p_purpose_label,
    p_receiver_label,
    p_reason
  );

  update public.collections
  set visibility = prior_visibility,
      public_status = prior_public_status,
      archived_at = prior_archived_at,
      updated_at = now()
  where id = p_collection_id;

  return result || jsonb_build_object(
    'visibility', prior_visibility::text,
    'status', case when prior_archived_at is null then 'active' else 'inactive' end
  );
end;

routine:public.admin_update_runtime_cont.source:
declare spec jsonb:=collect_security.runtime_control_spec(p_family); sid uuid; old_row jsonb; desired jsonb; head collect_security.runtime_control_heads;
 reason_text text:=btrim(coalesce(p_reason,'')); columns_sql text; values_sql text; assignments_sql text; result_row jsonb; context jsonb; prior_context text; changed boolean;
 parent_id uuid; identifier record;
begin
 sid:=collect_security.runtime_control_actor(p_family);
 if p_expected_revision is null or p_expected_revision not between 0 and 1000000000 or char_length(reason_text) not between 8 and 500
  or regexp_replace(reason_text,E'[\n\r\t]','','g') ~ '[[:cntrl:]]' then raise exception 'runtime_control_revision_reason_required' using errcode='22023';end if;
 perform collect_security.runtime_control_check_identity(p_family,p_identity);
 if coalesce((spec->>'user_owned')::boolean,false) and p_identity->>'user_id' is distinct from auth.uid()::text then raise exception 'runtime_control_owner_required' using errcode='42501';end if;
 if p_patch is null or jsonb_typeof(p_patch)<>'object' or octet_length(p_patch::text)>65536 or p_patch='{}'::jsonb
  or exists(select 1 from jsonb_object_keys(p_patch) field where not (spec->'writable') ? field) then raise exception 'runtime_control_patch_invalid' using errcode='22023';end if;
 perform collect_security.runtime_control_check_values(p_family,p_patch);
 -- Parent publication locks precede child/head locks, preventing a late section
 -- edit from racing publication. Wiring identifiers stay immutable after create.
 execute format('select to_jsonb(t) from %s t where to_jsonb(t) @> $1',spec->>'relation') into old_row using p_identity;
 if old_row is not null and exists(select 1 from jsonb_array_elements_text(spec->'immutable_after_create') k where p_patch ? k and old_row->k is distinct from p_patch->k) then
  raise exception 'runtime_control_wiring_immutable' using errcode='55000';end if;
 if old_row is null and not (spec->>'create_allowed')::boolean then raise exception 'runtime_control_create_owner_only' using errcode='42501';end if;
 perform collect_security.runtime_control_lock_parent(p_family,coalesce(old_row,p_identity)||p_patch,old_row);
 select * into head from collect_security.runtime_control_heads h where h.family=p_family and h.identity=p_identity for update;
 if coalesce(head.revision,0) is distinct from p_expected_revision then raise exception 'runtime_control_conflict' using errcode='40001';end if;
 execute format('select to_jsonb(t) from %s t where to_jsonb(t) @> $1 for update',spec->>'relation') into old_row using p_identity;
 if old_row is not null and head.content_sha256 is distinct from collect_security.runtime_control_hash(old_row) then raise exception 'runtime_control_head_invalid' using errcode='55000';end if;
 -- Recheck effective authority after every possible row wait, under the shared
 -- Auth/roster gates also used by revocation; stale JWT fields confer no rights.
 perform collect_security.runtime_control_actor(p_family);
 if p_family='system_settings' and coalesce((old_row->>'is_sensitive')::boolean,false) then raise exception 'runtime_control_sensitive_setting_owner_only' using errcode='42501';end if;
 desired:=coalesce(old_row,p_identity)||p_patch;
 perform collect_security.runtime_control_validate(p_family,desired,old_row);
 changed:=old_row is null or collect_security.runtime_control_hash(desired) is distinct from collect_security.runtime_control_hash(old_row);
 if not changed then return jsonb_build_object('contract_version',1,'ok',true,'family',p_family,'identity',p_identity,'previous_revision',head.revision,'revision',head.revision,'changed',false,'updated_at',head.updated_at,'content_sha256',head.content_sha256);end if;
 context:=jsonb_build_object('family',p_family,'identity',p_identity,'expected_revision',p_expected_revision,'actor_id',auth.uid(),'session_id',sid,
  'reason_sha256',encode(extensions.digest(convert_to(reason_text,'UTF8'),'sha256'),'hex'),'reason_characters',char_length(reason_text));
 prior_context:=current_setting('collect.runtime_control_context',true);
 perform set_config('collect.runtime_control_context',context::text,true);
 begin
  if old_row is null then
   select string_agg(format('%I',key),',' order by key),string_agg(format('(jsonb_populate_record(null::%s,$1)).%I',spec->>'relation',key),',' order by key)
   into columns_sql,values_sql from jsonb_object_keys(p_identity||p_patch) key;
   execute format('insert into %s (%s) select %s returning to_jsonb(%s.*)',spec->>'relation',columns_sql,values_sql,split_part(spec->>'relation','.',2)) into result_row using p_identity||p_patch;
  else
   select string_agg(format('%I=(jsonb_populate_record(null::%s,$1)).%I',key,spec->>'relation',key),',' order by key) into assignments_sql from jsonb_object_keys(p_patch) key;
   execute format('update %s t set %s where to_jsonb(t) @> $2 returning to_jsonb(t)',spec->>'relation',assignments_sql) into result_row using p_patch,p_identity;
  end if;
 exception
 when unique_violation then perform set_config('collect.runtime_control_context',coalesce(prior_context,''),true);raise exception 'runtime_control_conflict' using errcode='40001';
 when not_null_violation or check_violation or foreign_key_violation or invalid_text_representation or datetime_field_overflow or numeric_value_out_of_range then
  perform set_config('collect.runtime_control_context',coalesce(prior_context,''),true);raise exception 'runtime_control_invalid' using errcode='22023';
 when others then perform set_config('collect.runtime_control_context',coalesce(prior_context,''),true);raise;end;
 perform set_config('collect.runtime_control_context',coalesce(prior_context,''),true);
 select * into strict head from collect_security.runtime_control_heads h where h.family=p_family and h.identity=p_identity;
 return jsonb_build_object('contract_version',1,'ok',true,'family',p_family,'identity',p_identity,'previous_revision',p_expected_revision,'revision',head.revision,'changed',true,'updated_at',head.updated_at,'content_sha256',head.content_sha256);
end

routine:public.allocate_parsed_payment_e.source:
declare
  event_row public.parsed_payment_events;
  evidence_time timestamptz;
  intent_count integer := 0;
  intent_id uuid;
  intent_collection_id uuid;
  intent_receiver_hash text;
  intent_member_id uuid;
  direct_count integer := 0;
  direct_assignment_id uuid;
  direct_collection_id uuid;
  direct_member_id uuid;
  direct_enabled boolean;
  result_status text;
  existing_payment_status text;
begin
  select event.* into event_row
  from public.parsed_payment_events event
  where event.id = event_id
  for update;
  if event_row.id is null then raise exception 'Parsed event not found'; end if;
  select coalesce(raw.received_at_device, raw.ingested_at)
  into evidence_time
  from public.raw_payment_sms raw
  where raw.id = event_row.raw_sms_id;
  select payment.status into existing_payment_status
  from public.payments payment
  where payment.parsed_event_id = event_id;
  if existing_payment_status = 'posted'
     or event_row.allocation_status = 'allocated' then
    return 'already_allocated';
  elsif existing_payment_status = 'review' then
    return 'awaiting_provider_confirmation';
  elsif existing_payment_status = 'reversed'
     or event_row.allocation_status = 'ignored' then
    return 'ignored';
  end if;
  if not event_row.is_mobile_money_payment
     or event_row.direction <> 'incoming'
     or event_row.currency <> 'RWF'
     or event_row.amount_rwf is null
     or event_row.amount_rwf <= 0
     or event_row.transaction_id is null
     or event_row.confidence < 0.90
     or evidence_time is null then
    update public.parsed_payment_events
    set allocation_status = 'needs_review',
        review_reason = 'SMS evidence is incomplete or not reliable enough for candidate matching'
    where id = event_id;
    perform collect_hybrid.record_momo_exception(
      event_id, 'no_candidate', jsonb_build_object('stage', 'evidence_validation')
    );
    return 'needs_review';
  end if;

  -- Serialize every route on the same provider reference and treat the
  -- reference as consumed even after rejection or compensating reversal.
  perform pg_advisory_xact_lock(hashtextextended(
    event_row.network || ':' || upper(btrim(event_row.transaction_id)), 0
  ));
  if exists (
    select 1 from public.payments payment
    where payment.provider_network = event_row.network
      and upper(btrim(payment.transaction_id)) = upper(btrim(event_row.transaction_id))
  ) then
    update public.parsed_payment_events
    set allocation_status = 'ignored',
        review_reason = 'Provider transaction evidence was already consumed'
    where id = event_id;
    return 'ignored';
  end if;

  update public.payment_intents set status = 'expired'
  where status = 'pending' and expires_at <= now();
  if event_row.transaction_id is not null then
    with candidates as (
      select distinct
        intent.id,
        intent.collection_id,
        intent.receiver_momo_number_hash,
        intent.contributor_user_id,
        intent.contributor_public_id,
        intent.created_at
      from public.payment_intents intent
      join public.collection_receivers route
        on route.collection_id = intent.collection_id
       and route.momo_number_hash = intent.receiver_momo_number_hash
       and route.is_active
       and route.receiver_user_id = event_row.receiver_user_id
      where intent.status = 'pending'
        and (event_row.collection_id is null or intent.collection_id = event_row.collection_id)
        and (event_row.receiver_phone_hash is null
          or intent.receiver_momo_number_hash = event_row.receiver_phone_hash)
        and intent.expected_amount_rwf = event_row.amount_rwf
        and evidence_time between intent.created_at - interval '15 minutes'
          and intent.expires_at + interval '2 hours'
        and event_row.sender_phone_hash is not null
        and intent.sender_phone_hash = event_row.sender_phone_hash
        and intent.sender_phone_hash =
          public._authenticated_momo_phone_hash(intent.contributor_user_id)
        and (event_row.detected_user_public_id is null
          or intent.contributor_public_id = event_row.detected_user_public_id)
    )
    select count(*),
      (array_agg(candidate.id order by candidate.created_at))[1],
      (array_agg(candidate.collection_id order by candidate.created_at))[1],
      (array_agg(candidate.receiver_momo_number_hash order by candidate.created_at))[1],
      (array_agg(member.id order by candidate.created_at))[1]
    into intent_count, intent_id, intent_collection_id, intent_receiver_hash, intent_member_id
    from candidates candidate
    left join collect_hybrid.member_records member
      on member.linked_user_id = candidate.contributor_user_id
      or (
        candidate.contributor_user_id is null
        and candidate.contributor_public_id is not null
        and member.collect_id = candidate.contributor_public_id
      );
  end if;

  direct_enabled := coalesce((select flag.enabled from public.feature_flags flag
    where flag.key = 'hybrid_direct_ussd_allocation'), false);
  if direct_enabled and event_row.transaction_id is not null
     and event_row.receiver_phone_hash is not null
     and event_row.payer_match_key is not null then
    with candidates as (
      select distinct
        assignment.id,
        assignment.collection_id,
        assignment.member_record_id,
        assignment.created_at
      from collect_hybrid.member_receiving_assignments assignment
      join public.collection_receivers route
        on route.id = assignment.collection_receiver_id
       and route.collection_id = assignment.collection_id
       and route.is_active
       and route.receiver_user_id = event_row.receiver_user_id
       and route.momo_number_hash = event_row.receiver_phone_hash
       and route.network = event_row.network
       and assignment.route_key = encode(extensions.digest(
         route.receiver_user_id::text || '|' || route.momo_number_hash || '|' || route.network,
         'sha256'
       ), 'hex')
      join collect_hybrid.member_records member
        on member.id = assignment.member_record_id and member.lifecycle = 'active'
      join collect_hybrid.member_momo_identities identity
        on identity.member_id = member.id and identity.match_key = event_row.payer_match_key
      join public.collection_members membership
        on membership.member_record_id = member.id
       and membership.collection_id = assignment.collection_id
       and membership.status = 'active'
      where assignment.status = 'active'
        and evidence_time >= assignment.starts_at
        and (assignment.ended_at is null or evidence_time <= assignment.ended_at)
        and (event_row.collection_id is null or assignment.collection_id = event_row.collection_id)
    )
    select count(*),
      (array_agg(candidate.id order by candidate.created_at))[1],
      (array_agg(candidate.collection_id order by candidate.created_at))[1],
      (array_agg(candidate.member_record_id order by candidate.created_at))[1]
    into direct_count, direct_assignment_id, direct_collection_id, direct_member_id
    from candidates candidate;
  end if;

  if intent_count > 1 or direct_count > 1 then
    update public.parsed_payment_events
    set allocation_status = 'ambiguous',
        review_reason = 'Multiple payer-verified destinations matched this SMS evidence'
    where id = event_id;
    perform collect_hybrid.record_momo_exception(
      event_id, 'ambiguous_candidate',
      jsonb_build_object('intent_candidates', intent_count, 'direct_candidates', direct_count)
    );
    return 'ambiguous';
  end if;
  if intent_count = 1 and direct_count = 1
     and (intent_collection_id <> direct_collection_id
       or intent_member_id is distinct from direct_member_id) then
    update public.parsed_payment_events
    set allocation_status = 'ambiguous',
        review_reason = 'Payment intent and direct receiving assignment disagree'
    where id = event_id;
    perform collect_hybrid.record_momo_exception(
      event_id, 'intent_direct_disagreement',
      jsonb_build_object(
        'intent_collection_id', intent_collection_id,
        'direct_collection_id', direct_collection_id,
        'intent_member_record_id', intent_member_id,
        'direct_member_record_id', direct_member_id
      )
    );
    return 'ambiguous';
  end if;
  if direct_count = 1 and event_row.detected_user_public_id is not null
     and exists (
       select 1 from collect_hybrid.member_records member
       where member.id = direct_member_id
         and member.collect_id is distinct from event_row.detected_user_public_id
     ) then
    update public.parsed_payment_events
    set allocation_status = 'ambiguous',
        review_reason = 'SMS payer identifier conflicts with the direct receiving assignment'
    where id = event_id;
    perform collect_hybrid.record_momo_exception(
      event_id, 'payer_identity_conflict',
      jsonb_build_object(
        'direct_member_record_id', direct_member_id,
        'detected_user_public_id', event_row.detected_user_public_id
      )
    );
    return 'ambiguous';
  end if;
  if intent_count = 1 then
    if event_row.receiver_phone_hash is null then
      update public.parsed_payment_events
      set receiver_phone_hash = intent_receiver_hash,
          collection_id = coalesce(collection_id, intent_collection_id)
      where id = event_id;
    end if;
    perform public.post_payment_from_event(
      event_id, intent_id, intent_collection_id,
      case when direct_count = 1 then
        'Matched by one agreeing payment intent and direct receiving assignment'
      when event_row.receiver_phone_hash is null then
        'Matched by native SMS transaction ID plus one unique owned receiver, amount, payer, and time window'
      else
        'Matched by native SMS transaction ID, receiver, amount, payer, and time window'
      end
    );
    select event.allocation_status::text into result_status
    from public.parsed_payment_events event where event.id = event_id;
    if result_status = 'allocated' then
      update collect_hybrid.momo_reconciliation_exceptions
      set status = 'resolved', resolved_at = now()
      where parsed_event_id = event_id and status = 'open';
      return 'allocated';
    elsif result_status = 'needs_review' then
      return 'awaiting_provider_confirmation';
    end if;
    return 'ignored';
  end if;
  if direct_count = 1 then
    perform collect_hybrid.post_direct_ussd_payment(
      event_id, direct_assignment_id,
      'Matched by exact normalized MoMo name plus last three digits and one explicit active receiving assignment'
    );
    select event.allocation_status::text into result_status
    from public.parsed_payment_events event where event.id = event_id;
    if result_status = 'allocated' then
      return 'allocated';
    elsif result_status = 'needs_review' then
      return 'awaiting_provider_confirmation';
    end if;
    return 'ignored';
  end if;

  update public.parsed_payment_events
  set allocation_status = 'needs_review',
      review_reason = case when direct_enabled then
        'No payer-verified payment intent or direct receiving assignment matched this SMS evidence'
      else 'No payer-verified pending payment intent matched this SMS evidence' end
  where id = event_id;
  perform collect_hybrid.record_momo_exception(
    event_id, 'no_candidate',
    jsonb_build_object(
      'intent_candidates', intent_count,
      'direct_candidates', direct_count,
      'direct_allocation_enabled', direct_enabled
    )
  );
  return 'needs_review';
end;

routine:public.approve_payment_reconcili.source:
declare session_id uuid; r collect_security.reconciliation_reviews; p public.payments;
 reason_text text:=btrim(coalesce(p_reason,''));
begin
 session_id:=collect_security.require_reconciliation_actor();
 if p_review_id is null or length(reason_text) not between 10 and 500 then
  raise exception 'reconciliation_invalid_reason' using errcode='22023'; end if;
 select * into r from collect_security.reconciliation_reviews where id=p_review_id for update;
 if r.id is null or r.proposed_by=auth.uid() or r.consumed_at is not null
   or r.proposed_at<clock_timestamp()-interval '24 hours'
   or not isfinite(r.occurred_at) or r.occurred_at>clock_timestamp()+interval '5 minutes' then
  raise exception 'reconciliation_independent_approval_required' using errcode='22023'; end if;
 if not collect_security.reconciliation_actor_current(r.proposed_by,r.proposed_session_id) then
  raise exception 'reconciliation_actor_unavailable' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('provider-finality-payment:'||r.payment_id::text,0));
 select * into p from public.payments where id=r.payment_id for update;
 if p.id is null or p.status<>'review' or collect_security.reconciliation_fingerprint(p) is distinct from r.payment_fingerprint then
  raise exception 'reconciliation_payment_changed' using errcode='22023'; end if;
 if r.approved_by is not null then
  if r.approved_by=auth.uid() and r.approved_session_id=session_id and r.approval_reason=reason_text
     and r.approved_at>=clock_timestamp()-interval '15 minutes' then return true; end if;
  raise exception 'reconciliation_approval_conflict' using errcode='22023'; end if;
 update collect_security.reconciliation_reviews set approved_by=auth.uid(),approved_session_id=session_id,
  approved_at=clock_timestamp(),approval_reason=reason_text where id=r.id;
 perform public.create_audit_log('reconciliation.approved','payment',r.payment_id,
  jsonb_build_object('review_id',r.id,'evidence_sha256',r.evidence_sha256,'reason',reason_text,
    'session_id',session_id),auth.uid());
 return true;
end

routine:public.assert_admin_permission(t.source:
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;
  if not public.has_admin_permission(permission, auth.uid()) then
    raise exception 'Admin permission % required', permission;
  end if;
end;

routine:public.audit_admin_runtime_metad.source:
declare
  metadata_key text;
begin
  metadata_key := case
    when tg_op = 'DELETE' then coalesce(
      to_jsonb(old)->>'key',
      to_jsonb(old)->>'rpc_name',
      to_jsonb(old)->>'id'
    )
    else coalesce(
      to_jsonb(new)->>'key',
      to_jsonb(new)->>'rpc_name',
      to_jsonb(new)->>'id'
    )
  end;

  if auth.uid() is not null then
    perform create_audit_log(
      'admin_runtime_metadata.' || lower(tg_op),
      tg_table_name,
      null,
      jsonb_build_object('key', metadata_key)
    );
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;

