routine:public.authorize_reconciliation_.source:
declare session_id uuid; r collect_security.reconciliation_reviews;
begin
 session_id:=collect_security.require_reconciliation_actor();
 select * into r from collect_security.reconciliation_reviews where id=p_review_id;
 if r.id is null or r.approved_by is distinct from auth.uid() or r.approved_session_id is distinct from session_id then
  raise exception 'reconciliation_approver_required' using errcode='42501'; end if;
 -- A consumed review is a read-only acknowledgement; service finalization
 -- reports its current payment state instead of creating a second posting.
 if r.consumed_at is null and (r.approved_at<clock_timestamp()-interval '15 minutes'
   or r.proposed_at<clock_timestamp()-interval '24 hours') then
  raise exception 'reconciliation_approval_expired' using errcode='22023'; end if;
 return true;
end

routine:public.begin_collect_shadow_run_.source:
declare sid uuid; l collect_security.shadow_supervisor_lease;
  r collect_security.shadow_supervisor_runs; t timestamptz;
begin
  sid:=collect_security.require_shadow_actor();
  if p_request_id is null then raise exception 'shadow_request_invalid' using errcode='22023';end if;
  -- A physical same-value write serializes quota/idempotency decisions, including
  -- established Repeatable Read snapshots, which receive40001 after a writer.
  update collect_security.shadow_supervisor_lease set fence_version=fence_version
    where id returning * into l;
  if l.id is null then raise exception 'shadow_integrity_unavailable' using errcode='55000';end if;
  t:=clock_timestamp();
  select * into r from collect_security.shadow_supervisor_runs where request_id=p_request_id;
  if r.id is not null then
    if r.actor_id is distinct from auth.uid() or r.session_id is distinct from sid then
      raise exception 'shadow_request_conflict' using errcode='40001';end if;
    return jsonb_build_object('contract_version',1,'mode','shadow','scope','collect_platform',
      'ok',true,'outcome','replayed','replayed',true,'run',collect_security.shadow_run_json(r.id));
  end if;
  if l.active_run_id is not null and l.lease_expires_at>t then
    return jsonb_build_object('contract_version',1,'mode','shadow','scope','collect_platform',
      'ok',false,'outcome','busy','reason_code','shadow_run_busy','request_id',p_request_id,
      'retry_after_seconds',greatest(1,least(120,ceil(extract(epoch from l.lease_expires_at-t))::integer)));
  end if;
  if (select count(*) from collect_security.shadow_supervisor_runs
      where started_at>t-interval '1 hour')>=60 then
    raise exception 'shadow_limit_reached' using errcode='55000';end if;
  if l.fence_version>=1000000000 then raise exception 'shadow_limit_reached' using errcode='55000';end if;
  if l.active_run_id is not null then
    update collect_security.shadow_supervisor_runs set status='expired'
      where id=l.active_run_id and status='running';
  end if;
  insert into collect_security.shadow_supervisor_runs(request_id,actor_id,session_id,
    fence_version,started_at,lease_expires_at)
  values(p_request_id,auth.uid(),sid,l.fence_version+1,t,t+interval '120 seconds')
  returning * into r;
  update collect_security.shadow_supervisor_lease set fence_version=r.fence_version,
    active_run_id=r.id,lease_expires_at=r.lease_expires_at where id;
  return jsonb_build_object('contract_version',1,'mode','shadow','scope','collect_platform',
    'ok',true,'outcome','started','replayed',false,'run',collect_security.shadow_run_json(r.id));
end

routine:public.begin_signed_otp_v3(text,.source:
declare p collect_security.otp_policy; r collect_security.signed_otp_requests;
begin
 perform collect_security.require_otp_service_v3();
 update collect_security.otp_policy set enabled=enabled where singleton returning * into p;
 if p.singleton is null or not p.enabled then raise exception 'OTP policy unavailable' using errcode='55000'; end if;
 select * into r from collect_security.signed_otp_requests where hook_id=p_hook_id for update;
 if r.hook_id is null or r.payload_hash is distinct from p_payload_hash or r.attempt_id is distinct from p_attempt_id then
   raise exception 'OTP identity conflict' using errcode='22023';
 end if;
 perform collect_security.otp_expire_v3(r.hook_id);
 select * into r from collect_security.signed_otp_requests where hook_id=p_hook_id;
 if r.contract_version<>3 or r.status<>'reserved' or r.revision is distinct from p_revision then
   return collect_security.otp_receipt_v3(r)||jsonb_build_object('started',false);
 end if;
 update collect_security.signed_otp_requests set status='sending',started_at=clock_timestamp(),revision=revision+1
 where hook_id=r.hook_id returning * into r;
 return collect_security.otp_receipt_v3(r)||jsonb_build_object('started',true);
end

routine:public.check_sms_ingest_rate_lim.source:
declare
  hourly_count integer;
  daily_count integer;
begin
  if user_uuid is null then return false; end if;
  perform pg_advisory_xact_lock(hashtextextended('sms-ingest:' || user_uuid::text, 0));
  select
    count(*) filter (where ingested_at >= now() - interval '1 hour'),
    count(*) filter (where ingested_at >= now() - interval '24 hours')
  into hourly_count, daily_count
  from raw_payment_sms
  where receiver_user_id = user_uuid
    and ingested_at >= now() - interval '24 hours';
  return hourly_count < 60 and daily_count < 250;
end;

routine:public.claim_notification_delive.source:
declare
  device_ids uuid[];
  session_ids uuid[];
  changed_events uuid[] := '{}';
  claimed_ids uuid[] := '{}';
  candidate record;
  affected_event uuid;
  batch_limit integer := least(greatest(coalesce(p_limit, 100), 1), 500);
  current_time_value timestamptz := clock_timestamp();
  final_status text;
  reason text;
begin
  perform public._lock_notification_session_gate();
  if p_contract_version is distinct from 2 then
    raise exception 'notification_claim_contract_unsupported';
  end if;
  -- Lock sessions before devices; skip a session being logged out rather than
  -- invert the Auth-trigger lock order. Missing bindings are terminalized below.
  select array_agg(locked.id) into session_ids from (
    select s.id from auth.sessions s where exists (
      select 1 from public.notification_device_tokens device
      join public.notification_deliveries d on d.device_id=device.id
      where device.registration_session_id=s.id and (
        (d.status='queued' and d.next_attempt_at<=current_time_value)
        or (d.status='processing' and d.claim_expires_at<=current_time_value)))
    order by s.id for share of s skip locked limit 500
  ) locked;
  select array_agg(locked.id) into device_ids from (
    select device.id from public.notification_device_tokens device
    where (device.registration_session_id=any(session_ids)
      or device.registration_session_id is null
      or not exists(select 1 from auth.sessions s where s.id=device.registration_session_id))
    and exists (select 1 from public.notification_deliveries d
      where d.device_id = device.id and (
        (d.status = 'queued' and d.next_attempt_at <= current_time_value)
        or (d.status = 'processing' and d.claim_expires_at <= current_time_value)))
    order by device.id for update of device skip locked limit batch_limit
  ) locked;
  for candidate in
    select d.*, device.enabled, device.provider, device.token, device.registration_session_id,
      device.user_id as device_user_id, event.user_id as event_user_id
    from public.notification_deliveries d
    join public.notification_device_tokens device on device.id = d.device_id
    join public.notification_events event on event.id = d.event_id
    where d.device_id = any(device_ids) and (
      (d.status = 'queued' and d.next_attempt_at <= current_time_value)
      or (d.status = 'processing' and d.claim_expires_at <= current_time_value))
    order by d.next_attempt_at, d.created_at, d.id
    for update of d skip locked limit batch_limit
  loop
    reason := null;
    if candidate.event_user_id is distinct from candidate.device_user_id then
      reason := 'device_owner_changed';
    elsif not candidate.enabled or candidate.provider not in ('apns', 'fcm') or candidate.token is null then
      reason := 'device_unavailable';
    elsif not public._notification_session_is_live(candidate.registration_session_id,candidate.device_user_id) then
      reason := 'registration_session_revoked';
    elsif candidate.attempt_count >= 5 then
      reason := 'attempts_exhausted';
    elsif candidate.status = 'processing' then
      reason := 'claim_timeout';
    end if;
    if reason is not null then
      final_status := case when reason = 'claim_timeout' then 'queued' else 'failed' end;
      update public.notification_deliveries d set status = final_status,
        next_attempt_at = case when final_status = 'queued' then current_time_value +
          make_interval(secs => public._notification_retry_delay(candidate.attempt_count, null))
          else d.next_attempt_at end,
        claim_token = null, claim_expires_at = null, claim_user_id = null,
        last_error_code = reason, updated_at = current_time_value
      where d.id = candidate.id;
      if candidate.status = 'processing' and candidate.attempt_count > 0 then
        insert into public.notification_delivery_attempts(delivery_id, attempt_number, outcome, error_code)
        values (candidate.id, candidate.prior_attempt_count + candidate.attempt_count,
          case when final_status = 'queued' then 'retry' else 'failed' end, reason)
        on conflict on constraint notification_delivery_attempts_delivery_id_attempt_number_key do nothing;
      end if;
    else
      update public.notification_deliveries d set status = 'processing',
        attempt_count = d.attempt_count + 1, last_attempt_at = current_time_value,
        claim_token = gen_random_uuid(), claim_expires_at = current_time_value + interval '5 minutes',
        claim_user_id = candidate.event_user_id, updated_at = current_time_value
      where d.id = candidate.id;
      claimed_ids := array_append(claimed_ids, candidate.id);
    end if;
    changed_events := array_append(changed_events, candidate.event_id);
  end loop;
  for affected_event in select distinct unnest(changed_events) order by 1 loop
    perform public._refresh_notification_event(affected_event);
  end loop;
  return query select d.id, event.id, device.id, event.user_id, device.token, device.provider,
    device.environment, 'Collect'::text, 'Open Collect to view your updates'::text, event.deep_link, event.type,
    d.attempt_count, d.claim_token
  from public.notification_deliveries d
  join public.notification_events event on event.id = d.event_id
  join public.notification_device_tokens device on device.id = d.device_id
  where d.id = any(claimed_ids) order by d.next_attempt_at, d.created_at, d.id;
end

routine:public.claim_raw_payment_sms_for.source:
declare
  claimed_row public.raw_payment_sms;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Service role required';
  end if;
  if p_raw_sms_id is null or p_lease_id is null then
    raise exception 'Raw SMS and lease identifiers are required';
  end if;

  update public.raw_payment_sms raw
  set parse_status = 'processing',
      parse_started_at = now(),
      parse_lease_id = p_lease_id
  where raw.id = p_raw_sms_id
    and not exists (
      select 1
      from public.parsed_payment_events event
      where event.raw_sms_id = raw.id
    )
    and (
      raw.parse_status in ('pending', 'failed')
      or (
        raw.parse_status = 'processing'
        and raw.parse_started_at < now() - interval '60 seconds'
      )
    )
  returning raw.* into claimed_row;

  if claimed_row.id is null then
    return null;
  end if;
  return to_jsonb(claimed_row);
end;

routine:public.collect_admin_mask_name(t.source:
select case
  when nullif(btrim(coalesce(p_value, '')), '') is null then null
  when char_length(btrim(p_value)) = 1 then left(btrim(p_value), 1) || '•••'
  else left(btrim(p_value), 1) || '•••' || right(btrim(p_value), 1)
end;

routine:public.collect_claim_receipt(uui.source:
declare
  clean_worker text := btrim(coalesce(p_worker_id, ''));
  job collect_hybrid.sms_notification_outbox;
  prior collect_hybrid.sms_notification_claim_requests;
  token uuid;
  result jsonb;
begin
  if not collect_hybrid.operator_authorized(
    p_operator_user_id, 'notifications.manage'
  ) then raise exception 'Notification operator manage permission required'; end if;
  if p_job_id is null or p_request_id is null
     or clean_worker !~ '^[A-Za-z0-9._:-]{3,80}$' then
    raise exception 'Valid job, worker and request IDs are required';
  end if;
  select item.* into prior
  from collect_hybrid.sms_notification_claim_requests item
  where item.request_id = p_request_id;
  if prior.request_id is not null then
    if prior.operator_user_id <> p_operator_user_id
       or prior.outbox_id <> p_job_id or prior.worker_id <> clean_worker then
      raise exception 'Notification claim idempotency key conflict';
    end if;
    return prior.result || jsonb_build_object('replay', true);
  end if;
  select item.* into job
  from collect_hybrid.sms_notification_outbox item
  where item.id = p_job_id
  for update;
  if job.id is null then raise exception 'Notification job not found'; end if;
  if job.state = 'awaiting_confirmation'
     and job.claim_expires_at <= clock_timestamp()
     and not exists (
       select 1 from collect_hybrid.sms_notification_attempts attempt
       where attempt.outbox_id = job.id
     ) then
    update collect_hybrid.sms_notification_outbox
    set state = 'queued', claim_token = null, claimed_by = null,
        claim_expires_at = null
    where id = job.id;
    job.state := 'queued';
  end if;
  if job.state = 'queued'
     and not collect_hybrid.sms_receipt_job_is_current(job.id) then
    update collect_hybrid.sms_notification_outbox
    set state = 'suppressed',
        suppression_reason = 'Consent, collection policy, destination or payment state changed before claim',
        claim_token = null,
        claimed_by = null,
        claim_expires_at = null
    where id = job.id
    returning * into job;
    result := jsonb_build_object(
      'ok', false,
      'job_id', job.id,
      'state', 'suppressed',
      'replay', false
    );
    insert into collect_hybrid.sms_notification_claim_requests(
      request_id, operator_user_id, outbox_id, worker_id, result
    ) values (p_request_id, p_operator_user_id, job.id, clean_worker, result);
    perform public.create_audit_log(
      'notification.sms.suppressed', 'sms_notification_outbox', job.id,
      jsonb_build_object(
        'reason', job.suppression_reason,
        'fence_version', job.fence_version
      ),
      p_operator_user_id
    );
    return result;
  end if;
  if job.state <> 'queued' then
    raise exception 'Notification job is not available to claim';
  end if;
  token := gen_random_uuid();
  update collect_hybrid.sms_notification_outbox
  set state = 'awaiting_confirmation', claim_token = token,
      claimed_by = clean_worker, claim_expires_at = clock_timestamp() + interval '5 minutes',
      fence_version = fence_version + 1
  where id = job.id
  returning * into job;
  result := jsonb_build_object(
    'ok', true, 'job_id', job.id, 'claim_token', token,
    'fence_version', job.fence_version,
    'claim_expires_at', job.claim_expires_at,
    'destination_masked', left(job.destination_e164, 4) || '•••' || right(job.destination_e164, 3),
    'replay', false
  );
  insert into collect_hybrid.sms_notification_claim_requests(
    request_id, operator_user_id, outbox_id, worker_id, result
  ) values (p_request_id, p_operator_user_id, job.id, clean_worker, result);
  return result;
end;

routine:public.collect_confirm_receipt(u.source:
declare
  job collect_hybrid.sms_notification_outbox;
  confirmation collect_hybrid.sms_notification_confirmations;
begin
  if not collect_hybrid.operator_authorized(
    p_operator_user_id, 'notifications.manage'
  ) then raise exception 'Notification operator manage permission required'; end if;
  if p_confirmation_id is null then raise exception 'Confirmation ID required'; end if;
  select item.* into confirmation
  from collect_hybrid.sms_notification_confirmations item
  where item.id = p_confirmation_id;
  if confirmation.id is not null then
    if confirmation.outbox_id <> p_job_id
       or confirmation.operator_user_id <> p_operator_user_id
       or confirmation.claim_token <> p_claim_token
       or confirmation.fence_version <> p_fence_version
       or confirmation.destination_revision <> p_destination_revision
       or confirmation.body_sha256 is distinct from lower(btrim(coalesce(p_body_sha256, ''))) then
      raise exception 'Notification confirmation idempotency key conflict';
    end if;
    return jsonb_build_object(
      'ok', true, 'confirmation_id', confirmation.id,
      'expires_at', confirmation.expires_at, 'replay', true
    );
  end if;
  select item.* into job
  from collect_hybrid.sms_notification_outbox item
  where item.id = p_job_id
  for update;
  if job.id is null or job.state <> 'awaiting_confirmation'
     or job.claim_token is distinct from p_claim_token
     or job.fence_version <> p_fence_version
     or job.claim_expires_at <= clock_timestamp()
     or job.destination_revision <> p_destination_revision
     or job.body_sha256 is distinct from lower(btrim(coalesce(p_body_sha256, '')))
     or not collect_hybrid.sms_receipt_job_is_current(job.id) then
    raise exception 'Exact current notification confirmation required';
  end if;
  insert into collect_hybrid.sms_notification_confirmations(
    id, outbox_id, operator_user_id, claim_token, fence_version,
    destination_revision, body_sha256, expires_at
  ) values (
    p_confirmation_id, job.id, p_operator_user_id, p_claim_token,
    p_fence_version, p_destination_revision, job.body_sha256,
    least(job.claim_expires_at, clock_timestamp() + interval '2 minutes')
  ) returning * into confirmation;
  return jsonb_build_object(
    'ok', true, 'confirmation_id', confirmation.id,
    'expires_at', confirmation.expires_at, 'replay', false
  );
end;

routine:public.collect_get_claimed_recei.source:
declare job collect_hybrid.sms_notification_outbox;
begin
  if not collect_hybrid.operator_authorized(
    p_operator_user_id, 'notifications.manage'
  ) then raise exception 'Notification operator manage permission required'; end if;
  select item.* into job
  from collect_hybrid.sms_notification_outbox item
  where item.id = p_job_id;
  if job.id is null or job.state <> 'awaiting_confirmation'
     or job.claim_token is distinct from p_claim_token
     or job.fence_version <> p_fence_version
     or job.claim_expires_at <= clock_timestamp()
     or not collect_hybrid.sms_receipt_job_is_current(job.id) then
    raise exception 'Current notification claim required';
  end if;
  return jsonb_build_object(
    'job_id', job.id,
    'destination_e164', job.destination_e164,
    'destination_revision', job.destination_revision,
    'message_body', job.message_body,
    'body_sha256', job.body_sha256,
    'template_key', job.template_key,
    'template_version', job.template_version,
    'amount_rwf', job.amount_rwf,
    'member_balance_rwf', job.member_balance_rwf,
    'group_balance_rwf', job.group_balance_rwf,
    'reference', job.reference,
    'fence_version', job.fence_version,
    'claim_expires_at', job.claim_expires_at
  );
end;

routine:public.collect_list_pending_rece.source:
begin
  if not collect_hybrid.operator_authorized(
    p_operator_user_id, 'notifications.read'
  ) then raise exception 'Notification operator read permission required'; end if;
  if p_limit is null or p_limit not between 1 and 50 then
    raise exception 'Pending receipt page size must be 1 to 50';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'job_id', candidate.id,
      'state', candidate.state,
      'destination_masked', left(candidate.destination_e164, 4) || '•••' || right(candidate.destination_e164, 3),
      'created_at', candidate.created_at,
      'amount_rwf', candidate.amount_rwf,
      'template_key', candidate.template_key,
      'template_version', candidate.template_version
    ) order by candidate.created_at, candidate.id)
    from (
      select item.*
      from collect_hybrid.sms_notification_outbox item
      where item.state = 'queued'
        and (p_after_created_at is null or item.created_at > p_after_created_at)
      order by item.created_at, item.id
      limit p_limit
    ) candidate
  ), '[]'::jsonb);
end;

routine:public.collect_notification_heal.source:
begin
  if not collect_hybrid.operator_authorized(
    p_operator_user_id, 'notifications.read'
  ) then raise exception 'Notification operator read permission required'; end if;
  return jsonb_build_object(
    'enabled', coalesce((select flag.enabled from public.feature_flags flag
      where flag.key = 'hybrid_sms_notifications'), false),
    'queued', (select count(*) from collect_hybrid.sms_notification_outbox where state = 'queued'),
    'awaiting_confirmation', (select count(*) from collect_hybrid.sms_notification_outbox where state = 'awaiting_confirmation'),
    'send_started', (select count(*) from collect_hybrid.sms_notification_outbox where state = 'send_started'),
    'uncertain', (select count(*) from collect_hybrid.sms_notification_outbox where state = 'uncertain'),
    'suppressed', (select count(*) from collect_hybrid.sms_notification_outbox where state = 'suppressed'),
    'oldest_queued_at', (select min(created_at) from collect_hybrid.sms_notification_outbox where state = 'queued'),
    'active_workers', (select count(*) from collect_hybrid.sms_operator_heartbeats where observed_at > clock_timestamp() - interval '3 minutes'),
    'observed_at', clock_timestamp()
  );
end;

routine:public.collect_record_observed_o.source:
declare
  clean_outcome text := lower(btrim(coalesce(p_outcome, '')));
  clean_evidence text := btrim(coalesce(p_evidence_reference, ''));
  clean_note text := nullif(btrim(coalesce(p_outcome_note, '')), '');
  attempt collect_hybrid.sms_notification_attempts;
begin
  if not collect_hybrid.operator_authorized(
    p_operator_user_id, 'notifications.manage'
  ) then raise exception 'Notification operator manage permission required'; end if;
  if clean_outcome not in ('observed_sent', 'failed_no_send', 'uncertain')
     or char_length(clean_evidence) not between 8 and 500
     or (clean_note is not null and char_length(clean_note) > 500) then
    raise exception 'Valid outcome and bounded evidence reference required';
  end if;
  select item.* into attempt
  from collect_hybrid.sms_notification_attempts item
  where item.id = p_attempt_id
  for update;
  if attempt.id is null then raise exception 'SMS attempt not found'; end if;
  if attempt.operator_user_id <> p_operator_user_id then
    raise exception 'SMS attempt belongs to another operator';
  end if;
  if attempt.state <> 'send_started' then
    if attempt.state <> clean_outcome then
      raise exception 'SMS attempt outcome is already final';
    end if;
    if attempt.evidence_reference is distinct from clean_evidence
       or attempt.outcome_note is distinct from clean_note then
      raise exception 'SMS attempt outcome idempotency conflict';
    end if;
    return jsonb_build_object(
      'ok', true, 'attempt_id', attempt.id,
      'state', attempt.state, 'replay', true
    );
  end if;
  update collect_hybrid.sms_notification_attempts
  set state = clean_outcome, outcome_at = clock_timestamp(),
      evidence_reference = clean_evidence, outcome_note = clean_note
  where id = attempt.id;
  update collect_hybrid.sms_notification_outbox
  set state = clean_outcome,
      observed_sent_at = case when clean_outcome = 'observed_sent'
        then clock_timestamp() else null end,
      claim_expires_at = null
  where id = attempt.outbox_id and state = 'send_started';
  return jsonb_build_object(
    'ok', true, 'attempt_id', attempt.id,
    'state', clean_outcome, 'replay', false
  );
end;

routine:public.collect_record_send_start.source:
declare
  job collect_hybrid.sms_notification_outbox;
  confirmation collect_hybrid.sms_notification_confirmations;
  attempt collect_hybrid.sms_notification_attempts;
begin
  if not collect_hybrid.operator_authorized(
    p_operator_user_id, 'notifications.manage'
  ) then raise exception 'Notification operator manage permission required'; end if;
  select item.* into attempt
  from collect_hybrid.sms_notification_attempts item
  where item.confirmation_id = p_confirmation_id;
  if attempt.id is not null then
    if attempt.outbox_id <> p_job_id
       or attempt.operator_user_id <> p_operator_user_id
       or attempt.claim_token <> p_claim_token
       or attempt.fence_version <> p_fence_version
       or attempt.confirmation_id <> p_confirmation_id then
      raise exception 'Send-start confirmation conflict';
    end if;
    return jsonb_build_object(
      'ok', true, 'attempt_id', attempt.id,
      'state', attempt.state, 'replay', true
    );
  end if;
  select item.* into job
  from collect_hybrid.sms_notification_outbox item
  where item.id = p_job_id
  for update;
  select item.* into confirmation
  from collect_hybrid.sms_notification_confirmations item
  where item.id = p_confirmation_id
  for update;
  -- Freeze the current authorization rows across the durable pre-send
  -- transition. Revocation or payment reversal must complete before or after
  -- this boundary, never race invisibly through it.
  perform 1 from public.payments item
  where item.id = job.payment_id
  for share;
  perform 1 from collect_hybrid.member_records item
  where item.id = job.member_record_id
  for share;
  perform 1 from collect_hybrid.member_momo_identities item
  where item.member_id = job.member_record_id
  for share;
  perform 1 from collect_hybrid.sms_receipt_policies item
  where item.collection_id = job.collection_id
  for share;
  perform 1 from collect_hybrid.sms_receipt_member_consents item
  where item.member_record_id = job.member_record_id
  for share;
  if job.id is null or confirmation.id is null
     or job.state <> 'awaiting_confirmation'
     or job.claim_token is distinct from p_claim_token
     or job.fence_version <> p_fence_version
     or job.claim_expires_at <= clock_timestamp()
     or confirmation.outbox_id <> job.id
     or confirmation.operator_user_id <> p_operator_user_id
     or confirmation.claim_token <> p_claim_token
     or confirmation.fence_version <> p_fence_version
     or confirmation.destination_revision <> job.destination_revision
     or confirmation.body_sha256 <> job.body_sha256
     or confirmation.expires_at <= clock_timestamp()
     or confirmation.consumed_at is not null
     or not collect_hybrid.sms_receipt_job_is_current(job.id) then
    raise exception 'Fresh exact receipt confirmation required before send start';
  end if;
  insert into collect_hybrid.sms_notification_attempts(
    outbox_id, confirmation_id, operator_user_id, worker_id,
    claim_token, fence_version, attempt_number, destination_sha256,
    destination_revision, body_sha256
  ) values (
    job.id, confirmation.id, p_operator_user_id, job.claimed_by,
    p_claim_token, p_fence_version, job.attempt_count + 1,
    job.destination_sha256, job.destination_revision, job.body_sha256
  ) returning * into attempt;
  update collect_hybrid.sms_notification_confirmations
  set consumed_at = clock_timestamp()
  where id = confirmation.id;
  update collect_hybrid.sms_notification_outbox
  set state = 'send_started', attempt_count = attempt.attempt_number
  where id = job.id;
  return jsonb_build_object(
    'ok', true, 'attempt_id', attempt.id,
    'job_id', job.id, 'state', 'send_started', 'replay', false
  );
end;

routine:public.collect_release_unsent_cl.source:
declare
  clean_reason text := btrim(coalesce(p_reason, ''));
  job collect_hybrid.sms_notification_outbox;
begin
  if not collect_hybrid.operator_authorized(
    p_operator_user_id, 'notifications.manage'
  ) then raise exception 'Notification operator manage permission required'; end if;
  if char_length(clean_reason) not between 8 and 500 then
    raise exception 'A bounded release reason is required';
  end if;
  select item.* into job
  from collect_hybrid.sms_notification_outbox item
  where item.id = p_job_id
  for update;
  if job.id is null or job.state <> 'awaiting_confirmation'
     or job.claim_token is distinct from p_claim_token
     or job.fence_version <> p_fence_version
     or exists (
       select 1 from collect_hybrid.sms_notification_attempts attempt
       where attempt.outbox_id = job.id
     ) then
    raise exception 'Only a current safely unsent claim can be released';
  end if;
  update collect_hybrid.sms_notification_confirmations
  set expires_at = least(expires_at, clock_timestamp())
  where outbox_id = job.id and claim_token = p_claim_token and consumed_at is null;
  update collect_hybrid.sms_notification_outbox
  set state = 'queued', claim_token = null, claimed_by = null,
      claim_expires_at = null
  where id = job.id;
  perform public.create_audit_log(
    'notification.sms.claim_released', 'sms_notification_outbox', job.id,
    jsonb_build_object('reason', clean_reason, 'fence_version', p_fence_version),
    p_operator_user_id
  );
  return jsonb_build_object('ok', true, 'job_id', job.id, 'state', 'queued');
end;

routine:public.collect_worker_heartbeat(.source:
declare
  clean_worker text := btrim(coalesce(p_worker_id, ''));
  clean_mode text := lower(btrim(coalesce(p_mode, '')));
begin
  if not collect_hybrid.operator_authorized(
    p_operator_user_id, 'notifications.read'
  ) then raise exception 'Notification operator read permission required'; end if;
  if clean_worker !~ '^[A-Za-z0-9._:-]{3,80}$'
     or p_run_id is null or clean_mode not in ('no_send', 'assisted_send')
     or jsonb_typeof(coalesce(p_safe_status, '{}'::jsonb)) <> 'object' then
    raise exception 'Valid worker heartbeat required';
  end if;
  insert into collect_hybrid.sms_operator_heartbeats(
    worker_id, operator_user_id, run_id, mode, safe_status
  ) values (
    clean_worker, p_operator_user_id, p_run_id, clean_mode,
    coalesce(p_safe_status, '{}'::jsonb)
  )
  on conflict (worker_id) do update
  set operator_user_id = excluded.operator_user_id,
      run_id = excluded.run_id,
      mode = excluded.mode,
      safe_status = excluded.safe_status,
      observed_at = clock_timestamp();
  return jsonb_build_object(
    'ok', true, 'worker_id', clean_worker,
    'mode', clean_mode, 'observed_at', clock_timestamp()
  );
end;

routine:public.complete_notification_del.source:
declare
  delivery_row public.notification_deliveries;
  device_row public.notification_device_tokens;
  final_status text;
  session_id uuid;
begin
  perform public._lock_notification_session_gate();
  if p_success is null or p_retryable is null or p_claim_token is null
    or p_retry_after_seconds < 0 or p_attempt_number is null or p_attempt_number < 1 or p_attempt_number > 5 then
    raise exception 'notification_delivery_invalid_completion';
  end if;
  select device.registration_session_id into session_id from public.notification_device_tokens device
    join public.notification_deliveries d on d.device_id=device.id where d.id=p_delivery_id;
  perform 1 from auth.sessions s where s.id=session_id for share;
  if not found then raise exception 'notification_delivery_fence_lost'; end if;
  select device.* into device_row from public.notification_device_tokens device
    join public.notification_deliveries d on d.device_id = device.id
    where d.id = p_delivery_id for update of device;
  if not found then raise exception 'notification_delivery_not_claimed'; end if;
  select * into delivery_row from public.notification_deliveries where id = p_delivery_id for update;
  if not found or delivery_row.status <> 'processing'
    or delivery_row.claim_token is distinct from p_claim_token
    or delivery_row.attempt_count is distinct from p_attempt_number
    or delivery_row.claim_expires_at is null or delivery_row.claim_expires_at <= clock_timestamp()
    or device_row.registration_session_id is distinct from session_id
    or not public._notification_session_is_live(session_id,device_row.user_id)
    or not device_row.enabled or device_row.user_id is distinct from delivery_row.claim_user_id
    or not exists (select 1 from public.notification_events e
      where e.id = delivery_row.event_id and e.user_id = delivery_row.claim_user_id) then
    raise exception 'notification_delivery_fence_lost';
  end if;
  final_status := case when p_success then 'sent'
    when p_retryable and coalesce(p_retry_after_seconds, 0) <= 3600 and delivery_row.attempt_count < 5 then 'queued' else 'failed' end;
  if not p_success and p_retry_after_seconds > 3600 then p_error_code := 'retry_after_exceeds_budget'; end if;
  update public.notification_deliveries set status = final_status,
    next_attempt_at = case when final_status = 'queued' then clock_timestamp() +
      make_interval(secs => public._notification_retry_delay(delivery_row.attempt_count, p_retry_after_seconds))
      else next_attempt_at end,
    sent_at = case when p_success then clock_timestamp() else sent_at end,
    provider_message_id = nullif(trim(coalesce(p_provider_message_id, '')), ''),
    last_error_code = nullif(trim(coalesce(p_error_code, '')), ''),
    claim_token = null, claim_expires_at = null, claim_user_id = null, updated_at = clock_timestamp()
  where id = p_delivery_id;
  insert into public.notification_delivery_attempts(delivery_id, attempt_number, outcome,
    provider_message_id, error_code, latency_ms)
  values (p_delivery_id, delivery_row.prior_attempt_count + delivery_row.attempt_count,
    case when p_success then 'sent' when final_status = 'queued' then 'retry' else 'failed' end,
    nullif(trim(coalesce(p_provider_message_id, '')), ''),
    nullif(trim(coalesce(p_error_code, '')), ''), p_latency_ms);
  perform public._refresh_notification_event(delivery_row.event_id);
end

routine:public.configure_notification_di.source:
declare job_id bigint; begin
  if p_enabled is null then raise exception 'notification_scheduler_enabled_required'; end if;
  if p_enabled then perform public._notification_dispatch_configuration(); end if;
  for job_id in select jobid from cron.job where jobname = 'collect-dispatch-notifications' loop
    perform cron.unschedule(job_id);
  end loop;
  job_id := cron.schedule('collect-dispatch-notifications', '* * * * *',
    'select public.run_notification_dispatch_schedule();');
  perform cron.alter_job(job_id, active := p_enabled);
end

routine:public.confirm_provider_payment(.source:
declare
  payment_row public.payments;
  clean_network text := lower(btrim(coalesce(p_provider_network, '')));
  clean_transaction_id text := upper(btrim(coalesce(p_transaction_id, '')));
  clean_confirmation_id text := upper(btrim(coalesce(p_provider_confirmation_id, '')));
  clean_receiver_hash text := lower(btrim(coalesce(p_receiver_momo_number_hash, '')));
  clean_evidence_hash text := lower(btrim(coalesce(p_evidence_sha256, '')));
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'Service role required'; end if;
  if p_payment_id is null
     or char_length(clean_network) not between 2 and 32
     or char_length(clean_transaction_id) not between 3 and 128
     or char_length(clean_confirmation_id) not between 3 and 128
     or clean_receiver_hash !~ '^[0-9a-f]{64}$'
     or p_amount_rwf is null or p_amount_rwf <= 0
     or p_confirmed_at is null or not isfinite(p_confirmed_at) or p_confirmed_at > now() + interval '5 minutes'
     or (clean_evidence_hash <> '' and clean_evidence_hash !~ '^[0-9a-f]{64}$') then
    raise exception 'Invalid provider confirmation';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('provider-finality-payment:' || p_payment_id::text, 0));

  select payment.* into payment_row
  from public.payments payment
  where payment.id = p_payment_id
  for update;
  if payment_row.id is null then raise exception 'Payment not found'; end if;
  if payment_row.status = 'posted' then
    if exists (
      select 1 from public.payment_provider_confirmations confirmation
      where confirmation.payment_id = payment_row.id
        and confirmation.provider_network = clean_network
        and upper(btrim(confirmation.provider_confirmation_id)) = clean_confirmation_id
        and upper(btrim(confirmation.transaction_id)) = clean_transaction_id
        and confirmation.receiver_momo_number_hash = clean_receiver_hash
        and confirmation.amount_rwf = p_amount_rwf
        and confirmation.confirmed_at = p_confirmed_at
        and confirmation.evidence_sha256 is not distinct from nullif(clean_evidence_hash, '')
    ) then return payment_row.id; end if;
    raise exception 'Payment was already finalized by a different confirmation';
  end if;
  if payment_row.status <> 'review' then
    raise exception 'Payment is not awaiting provider confirmation';
  end if;
  if lower(btrim(payment_row.provider_network)) is distinct from clean_network
     or upper(btrim(payment_row.transaction_id)) is distinct from clean_transaction_id
     or payment_row.receiver_momo_number_hash is distinct from clean_receiver_hash
     or payment_row.amount_rwf is distinct from p_amount_rwf then
    raise exception 'Provider confirmation does not match the payment candidate';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(clean_network || ':' || clean_transaction_id, 0));
  insert into public.payment_provider_confirmations(
    payment_id, provider_network, provider_confirmation_id, transaction_id,
    receiver_momo_number_hash, amount_rwf, confirmed_at, evidence_sha256
  ) values (
    payment_row.id, clean_network, clean_confirmation_id, clean_transaction_id,
    clean_receiver_hash, p_amount_rwf, p_confirmed_at, nullif(clean_evidence_hash, '')
  );
  insert into public.ledger_entries(
    payment_id, collection_id, user_id, member_record_id,
    entry_type, amount_rwf, visibility, metadata
  ) values
    (
      payment_row.id, payment_row.collection_id, payment_row.contributor_user_id,
      payment_row.member_record_id, 'collection_credit', payment_row.amount_rwf,
      'public_safe', jsonb_build_object(
        'allocation_method', 'provider_confirmed',
        'provider_confirmation_id', clean_confirmation_id
      )
    ),
    (
      payment_row.id, payment_row.collection_id, payment_row.contributor_user_id,
      payment_row.member_record_id, 'member_credit', payment_row.amount_rwf,
      'private', jsonb_build_object(
        'allocation_method', 'provider_confirmed',
        'provider_confirmation_id', clean_confirmation_id
      )
    );
  update public.payments
  set status = 'posted', posted_at = p_confirmed_at
  where id = payment_row.id;
  update public.parsed_payment_events
  set allocation_status = 'allocated',
      review_reason = 'Posted after independent provider confirmation'
  where id = payment_row.parsed_event_id;
  perform public.create_audit_log(
    'payment.provider_confirmed', 'payment', payment_row.id,
    jsonb_build_object(
      'provider_network', clean_network,
      'provider_confirmation_id', clean_confirmation_id,
      'confirmed_at', p_confirmed_at,
      'ledger_posted', true
    ),
    null
  );
  return payment_row.id;
end;

routine:public.create_audit_log(text,tex.source:
declare
  audit_id uuid;
begin
  insert into audit_logs (actor_user_id, action, entity_type, entity_id, metadata)
  values (p_actor, p_action, p_entity_type, p_entity_id, coalesce(p_metadata, '{}'::jsonb))
  returning id into audit_id;
  return audit_id;
end;

routine:public.create_bank_transfer_grou.source:
declare
  created_group_id uuid;
  clean_title text := btrim(coalesce(p_group_name, ''));
  clean_description text := btrim(coalesce(p_group_description, ''));
  catalog_choice jsonb;
  base_slug text;
  final_slug text;
  next_visibility public.collection_visibility := case
    when coalesce(p_group_is_public, false) then 'public_requested'::public.collection_visibility
    else 'private'::public.collection_visibility
  end;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if char_length(clean_title) not between 3 and 120 then
    raise exception 'Group name must be between 3 and 120 characters';
  end if;
  if char_length(clean_description) > 1000 then
    raise exception 'Group description must be 1000 characters or fewer';
  end if;
  if p_accent_color_hex is not null and btrim(p_accent_color_hex) !~ '^#[0-9A-Fa-f]{6}$' then
    raise exception 'Accent color must be a six-digit hex color';
  end if;
  catalog_choice := public.resolve_collection_catalog_choice(
    p_group_collection_type,
    p_group_category_subtype,
    p_group_purpose_label,
    'RW'
  );
  base_slug := public.normalize_slug(clean_title);
  if base_slug = '' then base_slug := 'group'; end if;
  final_slug := base_slug || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 16);
  insert into public.collections (
    slug, creator_user_id, title, description, cover_image_url,
    accent_color_hex, collection_type, category_subtype, purpose_label,
    receiver_display_label, visibility, public_status, bank_transfer_currency
  ) values (
    final_slug, auth.uid(), clean_title, clean_description,
    nullif(btrim(coalesce(p_cover_image_url, '')), ''),
    nullif(btrim(coalesce(p_accent_color_hex, '')), ''),
    catalog_choice ->> 'collection_type',
    catalog_choice ->> 'category_subtype',
    catalog_choice ->> 'purpose_label',
    'Collect EUR bank account',
    'private'::public.collection_visibility,
    next_visibility,
    'EUR'
  ) returning id into created_group_id;
  insert into public.collection_members (collection_id, user_id, role, status)
  values (created_group_id, auth.uid(), 'owner', 'active');
  insert into public.collection_share_secrets (collection_id, rotated_by)
  values (created_group_id, auth.uid());
  perform public.create_audit_log(
    'group.created', 'collection', created_group_id,
    jsonb_build_object(
      'collection_type', catalog_choice ->> 'collection_type',
      'category_subtype', catalog_choice ->> 'category_subtype',
      'purpose_label', catalog_choice ->> 'purpose_label',
      'public_status', next_visibility::text,
      'payment_rail', 'sepa_credit_transfer'
    )
  );
  return created_group_id;
end;

routine:public.create_bank_transfer_inte.source:
declare
  collection_row public.collections%rowtype;
  destination public.bank_transfer_destinations%rowtype;
  intent public.bank_transfer_intents%rowtype;
  reference_value text;
begin
  perform collect_profile_access.assert_ready('diaspora');
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;
  if p_amount_minor is null or p_amount_minor <= 0 then
    raise exception 'Contribution amount must be above zero';
  end if;
  if p_amount_minor > 999999999999 then
    raise exception 'Contribution amount exceeds the supported limit';
  end if;
  if not coalesce((
    select enabled from public.feature_flags where key = 'bank_transfer_v1'
  ), false) then
    raise exception 'Bank transfers are not active yet';
  end if;

  select * into collection_row
  from public.collections
  where id = p_collection_id
    and archived_at is null
    and public_status <> 'archived';
  if collection_row.id is null then
    raise exception 'Collection is unavailable';
  end if;
  if collection_row.public_status <> 'public_approved'
     and collection_row.creator_user_id <> auth.uid()
     and not exists (
       select 1 from public.collection_members member
       where member.collection_id = collection_row.id
         and member.user_id = auth.uid()
         and member.status = 'active'
     ) then
    raise exception 'Private group membership is required';
  end if;

  select * into destination
  from public.bank_transfer_destinations
  where currency = 'EUR'
    and status = 'active'
    and not is_placeholder
  order by version desc
  limit 1;
  if destination.id is null then
    raise exception 'Approved bank transfer details are not available';
  end if;

  perform public.ensure_public_contributor_membership(
    collection_row.id,
    auth.uid()
  );

  update public.bank_transfer_intents
  set status = 'expired', updated_at = now()
  where contributor_user_id = auth.uid()
    and status in ('awaiting_transfer', 'handoff_opened', 'awaiting_bank_evidence')
    and expires_at <= now();

  select * into intent
  from public.bank_transfer_intents
  where collection_id = collection_row.id
    and contributor_user_id = auth.uid()
    and destination_id = destination.id
    and amount_minor = p_amount_minor
    and currency = 'EUR'
    and status in ('awaiting_transfer', 'handoff_opened', 'awaiting_bank_evidence')
    and expires_at > now()
  order by created_at desc
  limit 1;

  if intent.id is null then
    loop
      reference_value := 'COL-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));
      exit when not exists (
        select 1 from public.bank_transfer_intents where transfer_reference = reference_value
      );
    end loop;

    insert into public.bank_transfer_intents (
      collection_id,
      contributor_user_id,
      destination_id,
      destination_snapshot,
      transfer_reference,
      amount_minor,
      currency
    ) values (
      collection_row.id,
      auth.uid(),
      destination.id,
      public.bank_transfer_destination_json(destination),
      reference_value,
      p_amount_minor,
      'EUR'
    ) returning * into intent;

    perform public.create_audit_log(
      'bank_transfer.intent.created',
      'bank_transfer_intent',
      intent.id,
      jsonb_build_object(
        'collection_id', intent.collection_id,
        'amount_minor', intent.amount_minor,
        'currency', intent.currency,
        'destination_version', destination.version
      )
    );
  end if;

  return to_jsonb(intent) || jsonb_build_object(
    'destination', public.bank_transfer_destination_json(destination),
    'collection_title', collection_row.title
  );
end;

routine:public.create_contribution_inten.source:
declare
  requested_collection_id uuid := collection;
  verified_sender_phone_hash text;
  receiver_row public.collection_receivers;
  intent_row public.payment_intents;
  member_public_id char(6);
begin
  perform collect_profile_access.assert_ready('rwanda');
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if not exists (
    select 1
    from public.collections collection_row
    where collection_row.id = requested_collection_id
      and collection_row.archived_at is null
      and (
        collection_row.public_status = 'public_approved'
        or collection_row.creator_user_id = auth.uid()
        or exists (
          select 1
          from public.collection_members member_check
          where member_check.collection_id = collection_row.id
            and member_check.user_id = auth.uid()
            and member_check.status = 'active'
        )
      )
  ) then
    raise exception 'Private group membership is required';
  end if;
  if p_expected_amount_rwf is null or p_expected_amount_rwf <= 0 then
    raise exception 'Contribution amount must be above zero';
  end if;

  verified_sender_phone_hash := public._authenticated_momo_phone_hash(auth.uid());
  if verified_sender_phone_hash is null then
    raise exception 'Use your verified WhatsApp number as your MoMo payer number before contributing';
  end if;
  if nullif(trim(p_sender_phone_hash), '') is null
     or lower(trim(p_sender_phone_hash)) <> verified_sender_phone_hash then
    raise exception 'Contributor MoMo identity verification failed';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'contribution-intent:' || auth.uid()::text || ':' || requested_collection_id::text,
    0
  ));
  update public.payment_intents intent
  set status = case
    when intent.expires_at <= now() then 'expired'::public.payment_intent_status
    else 'cancelled'::public.payment_intent_status
  end
  where intent.contributor_user_id = auth.uid()
    and intent.collection_id = requested_collection_id
    and intent.status = 'pending'
    and (
      intent.expires_at <= now()
      or intent.sender_phone_hash is distinct from verified_sender_phone_hash
    );

  select profile.public_id into member_public_id
  from public.profiles profile where profile.id = auth.uid();
  if member_public_id is null then
    raise exception 'Collect ID is required before contributing';
  end if;

  select receiver.* into receiver_row
  from public.collection_receivers receiver
  where receiver.collection_id = requested_collection_id
    and receiver.is_active
  order by receiver.created_at
  limit 1
  for update;
  if receiver_row.id is null then raise exception 'Group has no active receiver'; end if;

  perform public.ensure_public_contributor_membership(
    requested_collection_id,
    auth.uid()
  );

  select intent.* into intent_row
  from public.payment_intents intent
  where intent.collection_id = requested_collection_id
    and intent.contributor_user_id = auth.uid()
    and intent.expected_amount_rwf = p_expected_amount_rwf
    and intent.receiver_momo_number_hash = receiver_row.momo_number_hash
    and intent.sender_phone_hash = verified_sender_phone_hash
    and intent.status = 'pending'
    and intent.expires_at > now()
  order by intent.created_at desc
  limit 1
  for update;

  if intent_row.id is null then
    insert into public.payment_intents (
      collection_id,
      contributor_user_id,
      contributor_public_id,
      expected_amount_rwf,
      receiver_momo_number_hash,
      sender_phone_hash
    ) values (
      requested_collection_id,
      auth.uid(),
      member_public_id,
      p_expected_amount_rwf,
      receiver_row.momo_number_hash,
      verified_sender_phone_hash
    ) returning * into intent_row;
  end if;

  return query select
    intent_row.id,
    intent_row.collection_id,
    intent_row.expected_amount_rwf,
    receiver_row.momo_number,
    intent_row.receiver_momo_number_hash,
    receiver_row.label,
    receiver_row.network,
    intent_row.sender_phone_hash,
    intent_row.status,
    intent_row.contributor_public_id,
    intent_row.created_at,
    intent_row.expires_at;
end;

routine:public.create_group_with_owner(t.source:
declare
  created_group_id uuid;
  base_slug text;
  final_slug text;
  catalog_choice jsonb;
  clean_type text;
  clean_subtype text;
  clean_purpose_label text;
  clean_title text := trim(coalesce(group_name, ''));
  clean_description text := trim(coalesce(group_description, ''));
  clean_receiver_label text := trim(coalesce(receiver_label, ''));
  receiver_digits text := regexp_replace(coalesce(receiver_momo_number, ''), '[^0-9]', '', 'g');
  profile_receiver_digits text;
  canonical_receiver text;
  computed_receiver_hash text;
  receiver_is_code boolean;
  next_visibility public.collection_visibility := case
    when coalesce(group_is_public, false) then 'public_requested'::public.collection_visibility
    else 'private'::public.collection_visibility
  end;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;
  if char_length(clean_title) not between 3 and 120 then
    raise exception 'Group name must be between 3 and 120 characters';
  end if;
  if char_length(clean_description) > 1000 then
    raise exception 'Group description must be 1000 characters or fewer';
  end if;
  if clean_receiver_label = '' or receiver_digits = '' then
    raise exception 'A linked MoMo receiver is required';
  end if;
  if not coalesce((
    select consent.enabled
    from public.receiver_mode_consents consent
    where consent.user_id = auth.uid()
    order by consent.created_at desc, consent.id desc
    limit 1
  ), false) then
    raise exception 'Enable MoMo SMS access before creating a group';
  end if;

  receiver_is_code := lower(clean_receiver_label) like '%code%';
  if receiver_is_code then
    if receiver_digits !~ '^[0-9]{4,9}$' then
      raise exception 'MoMo code must be between 4 and 9 digits';
    end if;
    select regexp_replace(coalesce(p.momo_pay_code, ''), '[^0-9]', '', 'g')
    into profile_receiver_digits
    from public.profiles p
    where p.id = auth.uid();
    canonical_receiver := '+' || receiver_digits;
  else
    if receiver_digits ~ '^250[0-9]{9}$' then
      canonical_receiver := '+' || receiver_digits;
    elsif receiver_digits ~ '^0[0-9]{9}$' then
      canonical_receiver := '+250' || substr(receiver_digits, 2);
    else
      raise exception 'Use a valid Rwanda MoMo number';
    end if;
    select regexp_replace(coalesce(p.momo_number, ''), '[^0-9]', '', 'g')
    into profile_receiver_digits
    from public.profiles p
    where p.id = auth.uid();
    if profile_receiver_digits ~ '^250[0-9]{9}$' then
      profile_receiver_digits := substr(profile_receiver_digits, 4);
    elsif profile_receiver_digits ~ '^0[0-9]{9}$' then
      profile_receiver_digits := substr(profile_receiver_digits, 2);
    end if;
    if receiver_digits ~ '^250' then
      receiver_digits := substr(receiver_digits, 4);
    elsif receiver_digits ~ '^0' then
      receiver_digits := substr(receiver_digits, 2);
    end if;
  end if;

  if coalesce(profile_receiver_digits, '') = ''
     or profile_receiver_digits <> receiver_digits then
    raise exception 'Group receiver must match the MoMo receiver linked to your profile';
  end if;

  computed_receiver_hash := encode(digest(canonical_receiver, 'sha256'), 'hex');
  if nullif(trim(coalesce(receiver_momo_number_hash, '')), '') is not null
     and lower(trim(receiver_momo_number_hash)) <> computed_receiver_hash then
    raise exception 'Receiver verification failed';
  end if;

  catalog_choice := public.resolve_collection_catalog_choice(
    group_collection_type,
    group_category_subtype,
    group_purpose_label,
    'RW'
  );
  clean_type := catalog_choice->>'collection_type';
  clean_subtype := catalog_choice->>'category_subtype';
  clean_purpose_label := catalog_choice->>'purpose_label';

  base_slug := public.normalize_slug(clean_title);
  if base_slug = '' then base_slug := 'group'; end if;
  final_slug := base_slug || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 16);

  insert into public.collections (
    slug,
    creator_user_id,
    title,
    description,
    collection_type,
    category_subtype,
    purpose_label,
    receiver_display_label,
    visibility,
    public_status
  ) values (
    final_slug,
    auth.uid(),
    clean_title,
    clean_description,
    clean_type,
    clean_subtype,
    clean_purpose_label,
    clean_receiver_label,
    case
      when next_visibility = 'public_approved' then 'public_approved'::public.collection_visibility
      else 'private'::public.collection_visibility
    end,
    next_visibility
  ) returning id into created_group_id;

  insert into public.collection_members (collection_id, user_id, role, status)
  values (created_group_id, auth.uid(), 'owner', 'active');

  insert into public.collection_receivers (
    collection_id,
    receiver_user_id,
    momo_number,
    momo_number_hash,
    label
  ) values (
    created_group_id,
    auth.uid(),
    trim(receiver_momo_number),
    computed_receiver_hash,
    clean_receiver_label
  );

  insert into public.collection_share_secrets (collection_id, rotated_by)
  values (created_group_id, auth.uid());

  perform public.create_audit_log(
    'group.created',
    'collection',
    created_group_id,
    jsonb_build_object(
