routine:public.ensure_current_profile(te.source:
declare
  profile_row public.profiles%rowtype;
  country_rule public.profile_country_rules%rowtype;
  requested_phone text := nullif(btrim(coalesce(p_whatsapp_phone, '')), '');
  verified_phone text;
  clean_phone text;
  clean_country text := upper(nullif(btrim(coalesce(p_country_code, '')), ''));
  resolved_country text;
  default_momo text;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;

  select nullif(btrim(phone), '') into verified_phone
  from auth.users where id = auth.uid();
  clean_phone := coalesce(verified_phone, requested_phone);

  if clean_country is not null then
    select * into country_rule from public.profile_country_rules
    where country_code = clean_country and enabled;
    if country_rule.country_code is null then
      raise exception 'Unsupported profile country';
    end if;
  end if;

  select * into profile_row from public.profiles where id = auth.uid();
  resolved_country := coalesce(profile_row.country_code, clean_country);
  if resolved_country is not null
     and country_rule.country_code is distinct from resolved_country then
    select * into country_rule from public.profile_country_rules
    where country_code = resolved_country and enabled;
  end if;
  default_momo := case
    when resolved_country = 'RW' then public._rwanda_momo_local(clean_phone)
    else null
  end;

  if profile_row.id is null then
    insert into public.profiles (
      id, public_id, whatsapp_phone, country_code, currency_code,
      momo_provider, momo_number, momo_number_hash, momo_number_verified_at
    ) values (
      auth.uid(), public.generate_public_id(), clean_phone, resolved_country,
      country_rule.currency_code,
      case
        when resolved_country <> 'RW' then null
        when default_momo ~ '^07[23]' then 'airtel_money'
        else 'mtn_momo'
      end,
      default_momo,
      case when default_momo is null then null else
        encode(extensions.digest('+250' || substr(default_momo, 2), 'sha256'), 'hex')
      end,
      case when default_momo is null then null else now() end
    ) returning * into profile_row;
  else
    update public.profiles
    set whatsapp_phone = case
          when verified_phone is not null then verified_phone
          when coalesce(profile_row.whatsapp_phone, '') = '' then clean_phone
          else profile_row.whatsapp_phone
        end,
        country_code = resolved_country,
        currency_code = coalesce(profile_row.currency_code, country_rule.currency_code),
        momo_provider = case
          when resolved_country <> 'RW' then null
          when profile_row.momo_provider is not null then profile_row.momo_provider
          when coalesce(profile_row.momo_number, default_momo) ~ '^07[23]'
            then 'airtel_money'
          else 'mtn_momo'
        end,
        momo_number = case
          when resolved_country = 'RW' then coalesce(profile_row.momo_number, default_momo)
          else null
        end,
        momo_number_hash = case
          when resolved_country <> 'RW' then null
          when profile_row.momo_number_hash is not null then profile_row.momo_number_hash
          when default_momo is not null then
            encode(extensions.digest('+250' || substr(default_momo, 2), 'sha256'), 'hex')
          else null
        end,
        momo_number_verified_at = case
          when resolved_country <> 'RW' then null
          when profile_row.momo_number_verified_at is not null
            then profile_row.momo_number_verified_at
          when default_momo is not null then now()
          else null
        end,
        revolut_name = case when resolved_country = 'RW' then null else profile_row.revolut_name end,
        revolut_link = case when resolved_country = 'RW' then null else profile_row.revolut_link end,
        revolut_account = case when resolved_country = 'RW' then null else profile_row.revolut_account end,
        updated_at = now()
    where id = auth.uid()
    returning * into profile_row;
  end if;
  return profile_row;
end;

routine:public.ensure_public_contributor.source:
declare
  group_row public.collections%rowtype;
  prior_status text;
  changed_rows integer := 0;
begin
  if p_user_id is null then
    raise exception 'Authenticated contributor is required';
  end if;

  select collection.* into group_row
  from public.collections collection
  where collection.id = p_collection_id
    and collection.archived_at is null
    and collection.public_status = 'public_approved'
  for update;

  if group_row.id is null or group_row.creator_user_id = p_user_id then
    return false;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'public-contributor-membership:' || p_user_id::text || ':' || p_collection_id::text,
    0
  ));

  select member.status::text into prior_status
  from public.collection_members member
  where member.collection_id = p_collection_id
    and member.user_id = p_user_id
    and member.role = 'member'
  for update;

  if prior_status = 'removed' then
    raise exception 'Membership was removed by a group administrator';
  end if;
  if prior_status = 'active' then
    return false;
  end if;

  insert into public.collection_members (collection_id, user_id, role, status)
  values (p_collection_id, p_user_id, 'member', 'active')
  on conflict on constraint collection_members_collection_id_user_id_role_key
  do update set status = 'active'
  where collection_members.status <> 'active';
  get diagnostics changed_rows = row_count;

  if changed_rows > 0 then
    perform public.create_audit_log(
      'group.joined',
      'collection',
      p_collection_id,
      jsonb_build_object('join_method', 'initial_contribution')
    );
    perform public.enqueue_notification_template_event(
      group_row.creator_user_id,
      'group.update.default',
      jsonb_build_object('group', group_row.title),
      p_collection_id,
      '/groups/' || p_collection_id::text || '/members',
      'en'
    );
    return true;
  end if;

  return false;
end;

routine:public.finalize_approved_reconci.source:
declare r collect_security.reconciliation_reviews; p public.payments; result jsonb;
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'service_role' then raise exception 'reconciliation_service_required' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
 select * into r from collect_security.reconciliation_reviews where id=p_review_id for update;
 if r.id is null or r.approved_by is null or r.approved_by=r.proposed_by
   or r.proposed_session_id is null or r.approved_session_id is null
   or not isfinite(r.occurred_at) or r.occurred_at>clock_timestamp()+interval '5 minutes' then
  raise exception 'reconciliation_approved_evidence_required' using errcode='22023'; end if;
 -- Recheck both recorded sessions as well as durable roles/identities.
 if not collect_security.reconciliation_actor_current(r.proposed_by,r.proposed_session_id)
   or not collect_security.reconciliation_actor_current(r.approved_by,r.approved_session_id) then
  raise exception 'reconciliation_actor_unavailable' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('provider-finality-payment:'||r.payment_id::text,0));
 select * into p from public.payments where id=r.payment_id for update;
 if r.consumed_at is not null then
  return jsonb_build_object('review_id',r.id,'payment_id',r.payment_id,'replayed',true,
    'payment_status',p.status,'evidence_level','independently_reconciled');
 end if;
 if r.approved_at<clock_timestamp()-interval '15 minutes' or r.proposed_at<clock_timestamp()-interval '24 hours' then
  raise exception 'reconciliation_approval_expired' using errcode='22023'; end if;
 if p.id is null or p.status<>'review' or collect_security.reconciliation_fingerprint(p) is distinct from r.payment_fingerprint then
  raise exception 'reconciliation_payment_changed' using errcode='22023'; end if;
 result:=public.process_provider_finality_event(r.id,'payment.confirmed',r.evidence_sha256,p.id,
   p.provider_network,p.transaction_id,r.source_reference,p.receiver_momo_number_hash,p.amount_rwf,
   r.occurred_at,r.evidence_sha256,null,null);
 update collect_security.reconciliation_reviews set consumed_at=clock_timestamp() where id=r.id;
 perform public.create_audit_log('reconciliation.finalized','payment',p.id,
  jsonb_build_object('review_id',r.id,'evidence_sha256',r.evidence_sha256,
    'proposed_by',r.proposed_by,'approved_by',r.approved_by),r.approved_by);
 return result||jsonb_build_object('review_id',r.id,'payment_status','posted','evidence_level','independently_reconciled');
end

routine:public.finalize_attested_payment.source:
begin
