routine:public.get_payment_reconciliatio.source:
declare r collect_security.reconciliation_reviews; p public.payments;
begin
 perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
 if not coalesce(public.has_admin_permission('payments.read'),false) then
  raise exception 'reconciliation_permission_required' using errcode='42501'; end if;
 select * into r from collect_security.reconciliation_reviews where id=p_review_id;
 if r.id is null then raise exception 'reconciliation_review_unavailable' using errcode='22023'; end if;
 select * into p from public.payments where id=r.payment_id;
 return (to_jsonb(r)-'proposed_session_id'-'approved_session_id')||jsonb_build_object(
  'payment_status',p.status,'collection_id',p.collection_id,'amount_rwf',p.amount_rwf,'currency',p.currency,
  'transaction_id',p.transaction_id,'provider_network',p.provider_network,
  'parsed_event_id',p.parsed_event_id,'payment_intent_id',p.payment_intent_id,
  'raw_sms_id',(select e.raw_sms_id from public.parsed_payment_events e where e.id=p.parsed_event_id),
  'receiver_routes',coalesce((select jsonb_agg(jsonb_build_object('id',rte.id,'network',rte.network,'is_active',rte.is_active) order by rte.id)
    from public.collection_receivers rte where rte.collection_id=p.collection_id and rte.receiver_user_id=p.receiver_user_id
      and rte.momo_number_hash=p.receiver_momo_number_hash and rte.network=p.provider_network),'[]'::jsonb),
  'receiver_user_id',p.receiver_user_id,'member_record_id',p.member_record_id,
  'audit',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'action',a.action,'actor_user_id',a.actor_user_id,
    'created_at',a.created_at,'metadata',a.metadata-'session_id') order by a.created_at,a.id)
    from public.audit_logs a where a.entity_id=p.id and a.action like 'reconciliation.%'
      and a.metadata->>'review_id'=r.id::text),'[]'::jsonb),
  'journals',coalesce((select jsonb_agg(jsonb_build_object('id',j.id,'entry_type',j.entry_type,'amount_rwf',j.amount_rwf)
   order by j.created_at,j.id) from collect_hybrid.momo_journal_entries j where j.payment_id=p.id),'[]'::jsonb));
end

routine:public.guard_notification_device.source:
declare
  identity_changed boolean := row(new.id, new.user_id, new.provider, new.platform, new.token_hash, new.token, new.environment, new.registration_session_id, new.registration_session_created_at)
    is distinct from row(old.id, old.user_id, old.provider, old.platform, old.token_hash, old.token, old.environment, old.registration_session_id, old.registration_session_created_at);
  affected_event uuid;
  delivery_row public.notification_deliveries;
  reason text;
begin
  if not identity_changed and not (old.enabled and not new.enabled) then return new; end if;
  if identity_changed and exists (select 1 from public.notification_deliveries d
      where d.device_id = old.id and d.claim_expires_at > clock_timestamp()) then
    raise exception 'notification_device_in_flight';
  end if;
  reason := case when identity_changed then 'device_owner_or_route_changed' else 'device_disabled' end;
  for delivery_row in select * from public.notification_deliveries d
      where d.device_id = old.id and d.status in ('queued', 'processing')
      order by d.id for update loop
    update public.notification_deliveries set status = 'failed', last_error_code = reason,
      updated_at = clock_timestamp()
    where id = delivery_row.id;
    if delivery_row.status = 'processing' and delivery_row.attempt_count > 0 then
      insert into public.notification_delivery_attempts(delivery_id, attempt_number, outcome, error_code)
      values (delivery_row.id, delivery_row.prior_attempt_count + delivery_row.attempt_count, 'failed', reason)
      on conflict on constraint notification_delivery_attempts_delivery_id_attempt_number_key do nothing;
    end if;
  end loop;
  for affected_event in select distinct d.event_id from public.notification_deliveries d
      where d.device_id = old.id order by d.event_id loop
    perform public._refresh_notification_event(affected_event);
  end loop;
  return new;
end

routine:public.ingest_attested_raw_payme.source:
declare
  capability public.native_action_capabilities;
  expected_payload jsonb;
  result jsonb;
  raw_id uuid;
  existing_raw public.raw_payment_sms;
  clean_body_hash text := lower(btrim(coalesce(p_body_hash, '')));
  clean_receiver_hash text := lower(btrim(coalesce(p_receiver_momo_number_hash, '')));
  clean_received_at text := nullif(btrim(coalesce(p_received_at_device, '')), '');
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Service role required';
  end if;
  if p_native_capability_id is null
     or p_receiver_user_id is null
     or p_client_envelope_id is null
     or clean_body_hash !~ '^[0-9a-f]{64}$'
     or clean_receiver_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'Invalid attested SMS ingestion request';
  end if;
  if clean_received_at is not null then
    perform clean_received_at::timestamptz;
  end if;
  expected_payload := jsonb_build_object(
    'receiver_momo_number_hash', clean_receiver_hash,
    'client_envelope_id', p_client_envelope_id::text,
    'raw_sender', btrim(coalesce(p_raw_sender, '')),
    'raw_body_sha256', clean_body_hash,
    'received_at_device', clean_received_at
  );

  select item.* into capability
  from public.native_action_capabilities item
  where item.id = p_native_capability_id
  for update;
  if capability.id is null
     or capability.user_id <> p_receiver_user_id
     or capability.action <> 'sms.ingest'
     or capability.receiver_momo_number_hash <> clean_receiver_hash
     or capability.request_payload <> expected_payload
     or capability.expires_at <= now() then
    raise exception 'Attested SMS capability is invalid or expired';
  end if;

  if capability.consumed_at is not null then
    select raw.* into existing_raw
    from public.raw_payment_sms raw
    where raw.native_action_capability_id = capability.id;
    if existing_raw.id is null then
      raise exception 'Attested SMS capability was already consumed';
    end if;
    return jsonb_build_object(
      'id', existing_raw.id,
      'parse_status', existing_raw.parse_status,
      'replay', true,
      'attested', true
    );
  end if;

  result := public.ingest_raw_payment_sms(
    p_receiver_user_id, p_collection_id, p_raw_sender, p_raw_body,
    clean_body_hash, p_client_envelope_id, clean_receiver_hash,
    clean_received_at::timestamptz
  );
  raw_id := (result ->> 'id')::uuid;
  select raw.* into existing_raw
  from public.raw_payment_sms raw
  where raw.id = raw_id
  for update;
  if existing_raw.native_action_capability_id is not null
     and existing_raw.native_action_capability_id <> capability.id then
    raise exception 'SMS envelope is already bound to another attestation';
  end if;
  update public.raw_payment_sms
  set native_action_capability_id = capability.id,
      attestation_request_hash = capability.request_hash,
      device_attested_at = capability.verified_at
  where id = raw_id;
  update public.native_action_capabilities
  set consumed_at = now()
  where id = capability.id and consumed_at is null;
  perform public.create_audit_log(
    'sms.provider_evidence_attested', 'raw_payment_sms', raw_id,
    jsonb_build_object(
      'native_capability_id', capability.id,
      'request_hash', capability.request_hash,
      'play_package', capability.package_name,
      'play_app_verdict', capability.app_verdict
    ),
    p_receiver_user_id
  );
  return result || jsonb_build_object('attested', true);
end;

routine:public.ingest_bank_evidence(text.source:
declare
  evidence public.raw_payment_evidence%rowtype;
  event public.bank_evidence_events%rowtype;
  transaction public.bank_transactions%rowtype;
  intent public.bank_transfer_intents%rowtype;
  allocation public.bank_transaction_allocations%rowtype;
  clean_channel text := lower(btrim(coalesce(p_channel, '')));
  clean_currency text := upper(btrim(coalesce(p_currency, 'unknown')));
  clean_reference text := upper(regexp_replace(btrim(coalesce(p_transfer_reference, '')), '[^A-Za-z0-9-]', '', 'g'));
  clean_bank_id text := nullif(upper(btrim(coalesce(p_bank_transaction_id, ''))), '');
  clean_end_to_end text := nullif(upper(btrim(coalesce(p_end_to_end_id, ''))), '');
  clean_last4 text := nullif(upper(regexp_replace(coalesce(p_payer_account_last4, ''), '[^A-Za-z0-9]', '', 'g')), '');
  body_digest text;
  transaction_key_value text;
  candidate_count integer := 0;
  exception_kind text;
begin
  if auth.role() <> 'service_role'
     and not public.has_admin_permission('bank_evidence.ingest', auth.uid()) then
    raise exception 'Bank evidence ingestion permission required';
  end if;
  if clean_channel not in ('sms', 'email', 'statement') then
    raise exception 'Unsupported evidence channel';
  end if;
  if nullif(btrim(coalesce(p_source_uid, '')), '') is null then
    raise exception 'Evidence source UID is required';
  end if;
  if nullif(btrim(coalesce(p_raw_sender, '')), '') is null then
    raise exception 'Evidence sender is required';
  end if;
  if nullif(p_raw_body, '') is null or octet_length(p_raw_body) > 200000 then
    raise exception 'Evidence body is required and must be at most 200 KB';
  end if;
  if p_received_at is null or p_received_at > now() + interval '5 minutes' then
    raise exception 'Evidence received timestamp is invalid';
  end if;
  if p_confidence < 0 or p_confidence > 1 then
    raise exception 'Evidence confidence must be between zero and one';
  end if;
  if clean_last4 is not null and clean_last4 !~ '^[A-Z0-9]{4}$' then
    clean_last4 := null;
  end if;

  body_digest := encode(extensions.digest(convert_to(p_raw_body, 'UTF8'), 'sha256'), 'hex');

  insert into public.raw_payment_evidence (
    channel, source_uid, raw_sender, raw_body, body_hash,
    headers, received_at, parse_status
  ) values (
    clean_channel,
    btrim(p_source_uid),
    btrim(p_raw_sender),
    p_raw_body,
    body_digest,
    coalesce(p_headers, '{}'::jsonb),
    p_received_at,
    'pending'
  )
  on conflict (channel, source_uid) do nothing
  returning * into evidence;

  if evidence.id is null then
    select * into evidence
    from public.raw_payment_evidence
    where channel = clean_channel and source_uid = btrim(p_source_uid);
    if evidence.body_hash <> body_digest then
      raise exception 'Evidence source UID was reused with different content';
    end if;
  end if;

  select * into event
  from public.bank_evidence_events
  where raw_evidence_id = evidence.id;

  if event.id is null then
    insert into public.bank_evidence_events (
      raw_evidence_id,
      direction,
      amount_minor,
      currency,
      bank_transaction_id,
      end_to_end_id,
      transfer_reference,
      payer_name,
      payer_account_last4,
      occurred_at,
      confidence,
      parser_name,
      parsed_json,
      allocation_status,
      review_reason
    ) values (
      evidence.id,
      case when p_direction in ('incoming', 'outgoing') then p_direction else 'unknown' end,
      case when p_amount_minor > 0 then p_amount_minor else null end,
      case when clean_currency = 'EUR' then 'EUR' else 'unknown' end,
      clean_bank_id,
      clean_end_to_end,
      nullif(clean_reference, ''),
      nullif(btrim(coalesce(p_payer_name, '')), ''),
      clean_last4,
      coalesce(p_occurred_at, p_received_at),
      p_confidence,
      coalesce(nullif(btrim(p_parser_name), ''), 'collect.bank_rules.v1'),
      coalesce(p_parsed_json, '{}'::jsonb),
      'unallocated',
      null
    ) returning * into event;
  end if;

  if event.direction <> 'incoming'
     or event.amount_minor is null
     or event.currency <> 'EUR'
     or event.confidence < 0.90 then
    update public.bank_evidence_events
    set allocation_status = 'needs_review',
        review_reason = 'Evidence is incomplete, non-incoming, non-EUR, or below the 0.90 threshold'
    where id = event.id
    returning * into event;
    update public.raw_payment_evidence set parse_status = 'needs_review' where id = evidence.id;
    return jsonb_build_object(
      'evidence_id', evidence.id,
      'event_id', event.id,
      'status', 'needs_review'
    );
  end if;

  transaction_key_value := encode(extensions.digest(convert_to(
    case
      when clean_bank_id is not null then 'bank:' || clean_bank_id
      when clean_end_to_end is not null then 'end-to-end:' || clean_end_to_end
      else 'composite:' || event.currency || '|' || event.amount_minor::text || '|' ||
        coalesce(nullif(clean_reference, ''), '') || '|' ||
        coalesce(event.occurred_at::date::text, p_received_at::date::text) || '|' ||
        coalesce(lower(btrim(event.payer_name)), '')
    end,
    'UTF8'
  ), 'sha256'), 'hex');

  insert into public.bank_transactions (
    transaction_key,
    bank_transaction_id,
    end_to_end_id,
    transfer_reference,
    payer_name,
    payer_account_last4,
    amount_minor,
    currency,
    occurred_at,
    value_date,
    evidence_received_at
  ) values (
    transaction_key_value,
    clean_bank_id,
    clean_end_to_end,
    nullif(clean_reference, ''),
    event.payer_name,
    event.payer_account_last4,
    event.amount_minor,
    event.currency,
    coalesce(event.occurred_at, p_received_at),
    coalesce(event.occurred_at, p_received_at)::date,
    p_received_at
  )
  on conflict (transaction_key) do update set
    bank_transaction_id = coalesce(public.bank_transactions.bank_transaction_id, excluded.bank_transaction_id),
    end_to_end_id = coalesce(public.bank_transactions.end_to_end_id, excluded.end_to_end_id),
    transfer_reference = coalesce(public.bank_transactions.transfer_reference, excluded.transfer_reference),
    payer_name = coalesce(public.bank_transactions.payer_name, excluded.payer_name),
    payer_account_last4 = coalesce(public.bank_transactions.payer_account_last4, excluded.payer_account_last4),
    evidence_received_at = least(public.bank_transactions.evidence_received_at, excluded.evidence_received_at),
    updated_at = now()
  returning * into transaction;

  insert into public.payment_evidence_links (bank_transaction_id, evidence_event_id)
  values (transaction.id, event.id)
  on conflict (evidence_event_id) do nothing;

  if nullif(clean_reference, '') is not null then
    select count(*), (array_agg(candidate.id order by candidate.created_at))[1]
    into candidate_count, intent.id
    from public.bank_transfer_intents candidate
    where candidate.transfer_reference = clean_reference
      and candidate.amount_minor = event.amount_minor
      and candidate.currency = event.currency
      and candidate.status in (
        'awaiting_transfer', 'handoff_opened', 'awaiting_bank_evidence',
        'received_unreconciled'
      )
      and candidate.expires_at >= coalesce(event.occurred_at, p_received_at) - interval '2 hours';
  end if;

  if candidate_count = 1 then
    select * into intent from public.bank_transfer_intents where id = intent.id for update;
    insert into public.bank_transaction_allocations (
      bank_transaction_id,
      bank_transfer_intent_id,
      collection_id,
      contributor_user_id,
      allocation_method,
      confidence,
      reason,
      allocated_by
    ) values (
      transaction.id,
      intent.id,
      intent.collection_id,
      intent.contributor_user_id,
      'auto_exact_reference',
      event.confidence,
      'Exact unique transfer reference, amount, currency, and active intent window',
      case when auth.role() = 'service_role' then null else auth.uid() end
    )
    on conflict (bank_transaction_id) do update set
      bank_transfer_intent_id = excluded.bank_transfer_intent_id,
      collection_id = excluded.collection_id,
      contributor_user_id = excluded.contributor_user_id,
      confidence = greatest(public.bank_transaction_allocations.confidence, excluded.confidence),
      reason = excluded.reason
    returning * into allocation;

    update public.bank_transactions
    set destination_id = intent.destination_id,
        status = case when status = 'reconciled' then status else 'received' end,
        updated_at = now()
    where id = transaction.id
    returning * into transaction;

    update public.bank_transfer_intents
    set status = case when status = 'reconciled' then status else 'received_unreconciled' end,
        evidence_received_at = coalesce(evidence_received_at, p_received_at),
        updated_at = now()
    where id = intent.id
    returning * into intent;

    update public.bank_evidence_events
    set allocation_status = 'allocated',
        review_reason = 'Exact unique bank transfer intent match'
    where id = event.id
    returning * into event;
    update public.raw_payment_evidence set parse_status = 'parsed' where id = evidence.id;
  else
    exception_kind := case
      when nullif(clean_reference, '') is null then 'missing_reference'
      when candidate_count > 1 then 'ambiguous_intent'
      else 'no_exact_intent'
    end;
    insert into public.reconciliation_exceptions (
      bank_transaction_id,
      exception_type,
      details
    ) values (
      transaction.id,
      exception_kind,
      jsonb_build_object(
        'transfer_reference', nullif(clean_reference, ''),
        'amount_minor', event.amount_minor,
        'currency', event.currency,
        'candidate_count', candidate_count
      )
    );
    update public.bank_transactions
    set status = 'exception', updated_at = now()
    where id = transaction.id
    returning * into transaction;
    update public.bank_evidence_events
    set allocation_status = case when candidate_count > 1 then 'ambiguous' else 'needs_review' end,
        review_reason = exception_kind
    where id = event.id
    returning * into event;
    update public.raw_payment_evidence set parse_status = 'needs_review' where id = evidence.id;
  end if;

  perform public.create_audit_log(
    'bank_evidence.ingested',
    'bank_transaction',
    transaction.id,
    jsonb_build_object(
      'channel', clean_channel,
      'event_id', event.id,
      'allocation_status', event.allocation_status,
      'bank_transfer_intent_id', allocation.bank_transfer_intent_id,
      'transaction_key', transaction.transaction_key
    ),
    case when auth.role() = 'service_role' then null else auth.uid() end
  );

  return jsonb_build_object(
    'evidence_id', evidence.id,
    'event_id', event.id,
    'bank_transaction_id', transaction.id,
    'bank_transfer_intent_id', allocation.bank_transfer_intent_id,
    'status', event.allocation_status,
    'transaction_status', transaction.status
  );
end;

routine:public.ingest_raw_payment_sms(uu.source:
declare
  existing_row public.raw_payment_sms;
  inserted_row public.raw_payment_sms;
  hourly_count integer;
  daily_count integer;
  clean_body_hash text := lower(btrim(coalesce(p_body_hash, '')));
  clean_receiver_hash text := nullif(lower(btrim(coalesce(p_receiver_momo_number_hash, ''))), '');
begin
  -- The only API grant is service_role; the Edge Function verifies the receiver.
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Service role required';
  end if;
  if p_receiver_user_id is null
     or nullif(btrim(p_raw_sender), '') is null
     or nullif(btrim(p_raw_body), '') is null
     or octet_length(p_raw_sender) > 96
     or octet_length(p_raw_body) > 4096
     or clean_body_hash !~ '^[0-9a-f]{64}$'
     or clean_body_hash <> encode(extensions.digest(p_raw_body, 'sha256'), 'hex')
     or (clean_receiver_hash is not null and clean_receiver_hash !~ '^[0-9a-f]{64}$') then
    raise exception 'Invalid raw SMS ingestion request';
  end if;
  if not public.user_can_ingest_receiver_sms(clean_receiver_hash, p_collection_id, p_receiver_user_id) then
    raise exception 'Receiver or SMS consent is not authorized';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('sms-ingest:' || p_receiver_user_id::text, 0));

  select raw.* into existing_row from public.raw_payment_sms raw
  where raw.receiver_user_id = p_receiver_user_id
    and raw.client_envelope_id = p_client_envelope_id;
  if existing_row.id is not null then
    if existing_row.body_hash is distinct from clean_body_hash
       or existing_row.raw_sender is distinct from p_raw_sender
       or existing_row.receiver_momo_number_hash is distinct from clean_receiver_hash
       or existing_row.collection_id is distinct from p_collection_id
       or existing_row.received_at_device is distinct from p_received_at_device then
      raise exception 'Invalid replay: SMS envelope evidence changed';
    end if;
    return jsonb_build_object('id', existing_row.id, 'parse_status', existing_row.parse_status, 'replay', true);
  end if;

  select raw.* into existing_row from public.raw_payment_sms raw
  where raw.receiver_user_id = p_receiver_user_id
    and raw.body_hash = clean_body_hash
    and raw.receiver_momo_number_hash is not distinct from clean_receiver_hash
    and raw.raw_sender = p_raw_sender
    and raw.received_at_device is not distinct from p_received_at_device
  order by raw.ingested_at limit 1;
  if existing_row.id is not null then
    if existing_row.collection_id is distinct from p_collection_id then
      raise exception 'Invalid replay: SMS collection binding changed';
    end if;
    return jsonb_build_object('id', existing_row.id, 'parse_status', existing_row.parse_status, 'replay', true);
  end if;

  select count(*) filter (where raw.ingested_at >= now() - interval '1 hour'), count(*)
  into hourly_count, daily_count from public.raw_payment_sms raw
  where raw.receiver_user_id = p_receiver_user_id and raw.ingested_at >= now() - interval '24 hours';
  if hourly_count >= 60 or daily_count >= 250 then
    raise exception 'SMS ingestion rate limit exceeded';
  end if;
  insert into public.raw_payment_sms (
    collection_id, receiver_user_id, raw_sender, raw_body, body_hash,
    client_envelope_id, receiver_momo_number_hash, received_at_device, parse_status
  ) values (
    p_collection_id, p_receiver_user_id, p_raw_sender, p_raw_body, clean_body_hash,
    p_client_envelope_id, clean_receiver_hash, p_received_at_device, 'pending'
  ) returning * into inserted_row;
  return jsonb_build_object('id', inserted_row.id, 'parse_status', inserted_row.parse_status, 'replay', false);
end;

routine:public.join_group_by_share_code(.source:
declare
  clean_code text := lower(trim(coalesce(p_group_code, '')));
  parsed_code uuid;
  group_row public.collections;
  newly_joined boolean := false;
begin
  perform collect_profile_access.assert_ready(null);
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;
  if clean_code = '' or char_length(clean_code) > 140 then
    raise exception 'Group link is invalid';
  end if;

  if clean_code ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    parsed_code := clean_code::uuid;
    select collection.*
    into group_row
    from public.collection_share_secrets secret
    join public.collections collection on collection.id = secret.collection_id
    where secret.share_code = parsed_code;
  else
    select collection.*
    into group_row
    from public.collections collection
    where collection.slug = clean_code
      and collection.public_status = 'public_approved';
  end if;

  if group_row.id is null then
    raise exception 'Group link is invalid or has expired';
  end if;
  if group_row.archived_at is not null
     or group_row.public_status = 'archived'::public.collection_visibility then
    raise exception 'This group is archived';
  end if;
  if group_row.creator_user_id = auth.uid()
     or exists (
       select 1
       from public.collection_members active_member
       where active_member.collection_id = group_row.id
         and active_member.user_id = auth.uid()
         and active_member.status = 'active'
     ) then
    return group_row.id;
  end if;
  if exists (
    select 1
    from public.collection_members removed_member
    where removed_member.collection_id = group_row.id
      and removed_member.user_id = auth.uid()
      and removed_member.status = 'removed'
  ) then
    raise exception 'Membership was removed by a group admin';
  end if;

  insert into public.collection_members (collection_id, user_id, role, status)
  values (group_row.id, auth.uid(), 'member', 'active')
  on conflict on constraint collection_members_collection_id_user_id_role_key
  do update set status = 'active'
  where collection_members.status <> 'active'
  returning true into newly_joined;

  newly_joined := coalesce(newly_joined, false);
  if newly_joined then
    perform public.create_audit_log(
      'group.joined',
      'collection',
      group_row.id,
      jsonb_build_object(
        'join_method',
        case when parsed_code is null then 'public_slug' else 'share_code' end
      )
    );

    if group_row.creator_user_id <> auth.uid() then
      perform public.enqueue_notification_template_event(
        group_row.creator_user_id,
        'group.update.default',
        jsonb_build_object('group', group_row.title),
        group_row.id,
        '/groups/' || group_row.id::text || '/members',
        'en'
      );
    end if;
  end if;

  return group_row.id;
end;

routine:public.list_collect_shadow_runs_.source:
declare l collect_security.shadow_supervisor_lease; t timestamptz;
  rows jsonb; cursor jsonb; more boolean; total bigint;
begin
  perform collect_security.require_shadow_actor();
  if p_limit is null or p_limit not between 1 and 50
    or (p_before_started_at is null)<>(p_before_run_id is null)
    or p_before_started_at is not null and not isfinite(p_before_started_at) then
    raise exception 'shadow_request_invalid' using errcode='22023';end if;
  select * into l from collect_security.shadow_supervisor_lease where id for share;
  if l.id is null then raise exception 'shadow_integrity_unavailable' using errcode='55000';end if;
  t:=clock_timestamp();
  select count(*) into total from collect_security.shadow_supervisor_runs;
  with candidates as materialized (
    select id,started_at from collect_security.shadow_supervisor_runs
    where p_before_started_at is null or (started_at,id)<(p_before_started_at,p_before_run_id)
    order by started_at desc,id desc limit p_limit+1
  ), page as materialized (
    select * from candidates order by started_at desc,id desc limit p_limit
  ) select coalesce((select jsonb_agg(collect_security.shadow_run_json(id,t)
      order by started_at desc,id desc) from page),'[]'::jsonb),
    (select count(*)>p_limit from candidates),
    (select jsonb_build_object('started_at',started_at,'run_id',id)
      from page order by started_at,id limit 1)
  into rows,more,cursor;
  return jsonb_build_object('contract_version',1,'mode','shadow','scope','collect_platform',
    'checked_at',t,'lease',jsonb_build_object('state',case when l.active_run_id is null
      then 'idle' when l.lease_expires_at<=t then 'expired' else 'active' end,
      'fence_version',l.fence_version,'active_run_id',l.active_run_id,'lease_expires_at',l.lease_expires_at),
    'rows',rows,'total',total,'next_cursor',case when more then cursor else null end);
end

