routine:public.reserve_otp_request(text,.source:
declare
  request_time timestamptz;
  recent_count integer;
begin
  if p_phone_hash is null or p_phone_hash !~ '^[0-9a-f]{64}$'
    or (p_ip_hash is not null and p_ip_hash !~ '^[0-9a-f]{64}$') then
    raise exception 'Valid OTP phone and IP hashes required' using errcode = '22023';
  end if;

  insert into collect_auth_security.otp_phone_locks as phone_lock (phone_hash, revision)
  values (p_phone_hash, 1)
  on conflict (phone_hash) do update set revision = phone_lock.revision + 1;

  request_time := clock_timestamp();
  select count(*) into recent_count from public.otp_rate_limits
  where phone_hash = p_phone_hash
    and requested_at >= request_time - interval '10 minutes';
  if recent_count >= 5 then return false; end if;

  insert into public.otp_rate_limits (phone_hash, ip_hash, requested_at)
  values (p_phone_hash, p_ip_hash, request_time);
  return true;
end;

routine:public.reserve_signed_otp_v2(tex.source:
declare r jsonb;
begin
 r:=public.reserve_signed_otp_v3(p_hook_id,p_payload_hash,p_phone_hash);
 if r=to_jsonb('throttled'::text) then return 'throttled'; end if;
 return case when r->>'state' in ('accepted','delivered') then 'already_sent' else 'unresolved' end;
end

routine:public.reserve_signed_otp_v3(tex.source:
declare p collect_security.otp_policy; r collect_security.signed_otp_requests; t timestamptz;
begin
 perform collect_security.require_otp_service_v3();
 if p_hook_id is null or char_length(p_hook_id) not between 1 and 256
   or p_hook_id !~ '^[A-Za-z0-9_:.-]+$' or p_payload_hash is null
   or p_payload_hash !~ '^[a-f0-9]{64}$' or p_phone_hash is null or p_phone_hash !~ '^[a-f0-9]{64}$' then
   raise exception 'OTP identity unavailable' using errcode='22023';
 end if;
 -- Consistent policy->request->phone order fences simultaneous quota decisions.
 update collect_security.otp_policy set enabled=enabled where singleton returning * into p;
 if p.singleton is null then raise exception 'OTP policy unavailable' using errcode='55000'; end if;
 select * into r from collect_security.signed_otp_requests where hook_id=p_hook_id for update;
 if r.hook_id is not null then
   if r.payload_hash<>p_payload_hash or r.phone_hash<>p_phone_hash then
     raise exception 'OTP identity conflict' using errcode='22023';
   end if;
   perform collect_security.otp_expire_v3(r.hook_id);
   select * into r from collect_security.signed_otp_requests where hook_id=p_hook_id;
   return collect_security.otp_receipt_v3(r);
 end if;
 if not p.enabled then raise exception 'OTP policy unavailable' using errcode='55000'; end if;
 t:=clock_timestamp();
 if (select count(*) from collect_security.signed_otp_requests where requested_at>=t-interval '1 hour')>=p.global_hourly_limit
   or (select count(*) from collect_security.signed_otp_requests where requested_at>=t-interval '24 hours')>=p.global_daily_limit then
   return to_jsonb('throttled'::text);
 end if;
 if not public.reserve_otp_request(p_phone_hash,null) then return to_jsonb('throttled'::text); end if;
 insert into collect_security.signed_otp_requests(hook_id,payload_hash,phone_hash,requested_at)
 values(p_hook_id,p_payload_hash,p_phone_hash,t) returning * into r;
 return collect_security.otp_receipt_v3(r);
end

routine:public.resolve_collection_catalo.source:
declare
  clean_type text := coalesce(nullif(trim(p_collection_type), ''), 'ikimina');
  clean_subtype text := nullif(trim(p_category_subtype), '');
  clean_purpose text := nullif(trim(p_purpose_label), '');
  clean_country text := upper(coalesce(nullif(trim(p_country_code), ''), 'RW'));
  catalog_row collection_type_catalog%rowtype;
  subtype_row collection_category_subtypes%rowtype;
  purpose_row collection_purpose_templates%rowtype;
begin
  select *
  into catalog_row
  from collection_type_catalog ctc
  where ctc.key = clean_type
    and ctc.enabled
    and exists (
      select 1
      from collection_type_country_rules ctcr
      where ctcr.collection_type_key = ctc.key
        and ctcr.country_code = clean_country
        and ctcr.enabled
    );

  if catalog_row.key is null then
    raise exception 'Unsupported collection type';
  end if;

  clean_subtype := coalesce(clean_subtype, catalog_row.default_category_subtype);
  select *
  into subtype_row
  from collection_category_subtypes ccs
  where ccs.collection_type_key = clean_type
    and ccs.key = clean_subtype
    and ccs.enabled;

  if subtype_row.key is null then
    raise exception 'Unsupported collection subtype';
  end if;

  if clean_purpose is null then
    select *
    into purpose_row
    from collection_purpose_templates cpt
    where cpt.collection_type_key = clean_type
      and cpt.key = catalog_row.default_purpose_template_key
      and cpt.enabled;
  else
    select *
    into purpose_row
    from collection_purpose_templates cpt
    where cpt.collection_type_key = clean_type
      and cpt.label = clean_purpose
      and cpt.enabled;
  end if;

  if purpose_row.key is null then
    raise exception 'Unsupported collection purpose';
  end if;

  return jsonb_build_object(
    'collection_type', clean_type,
    'category_subtype', subtype_row.key,
    'purpose_label', purpose_row.label
  );
end;

routine:public.revoke_notification_user_.source:
declare device_id uuid;
begin
  if new.id=old.id and new.deleted_at is null and not coalesce(new.is_anonymous,false)
    and (new.phone_confirmed_at is not null or new.email_confirmed_at is not null)
    and (new.banned_until is null or new.banned_until<=clock_timestamp()) then return new; end if;
  for device_id in select device.id from public.notification_device_tokens device
      where device.user_id=old.id and device.enabled order by device.id for update loop
    update public.notification_device_tokens set enabled=false,disabled_at=clock_timestamp(),
      disabled_reason='registration_user_revoked',updated_at=clock_timestamp()
      where id=device_id and user_id=old.id and enabled;
  end loop;
  return new;
end

routine:public.rotate_group_share_code_v.source:
declare sid uuid; receipt collect_member_actions.group_share_rotations; code uuid;
begin
  if p_request_id is null then raise exception 'group_share_request_invalid' using errcode='22023';end if;
  sid:=collect_member_actions.require_group_share_actor(p_collection_id,true);
  select * into receipt from collect_member_actions.group_share_rotations where request_id=p_request_id;
  if receipt.request_id is not null then
    if receipt.actor_id is distinct from auth.uid() or receipt.collection_id is distinct from p_collection_id then
      raise exception 'group_share_request_conflict' using errcode='40001';end if;
    select share_code into code from public.collection_share_secrets where collection_id=p_collection_id for share;
    if code is distinct from receipt.share_code then
      raise exception 'group_share_rotation_superseded' using errcode='55000';end if;
    return jsonb_build_object('contract_version',1,'ok',true,'collection_id',receipt.collection_id,
      'request_id',receipt.request_id,'share_code',receipt.share_code);
  end if;
  -- The locked parent serializes this count and its subsequent receipt insert.
  -- Established snapshots also lock the actual secret row before rotating it.
  perform 1 from public.collection_share_secrets where collection_id=p_collection_id for update;
  if (select count(*) from collect_member_actions.group_share_rotations
      where collection_id=p_collection_id and created_at>clock_timestamp()-interval '1 hour')>=60 then
    raise exception 'group_share_rate_limited' using errcode='55000';end if;
  insert into public.collection_share_secrets(collection_id,share_code,rotated_at,rotated_by)
    values(p_collection_id,gen_random_uuid(),clock_timestamp(),auth.uid())
    on conflict(collection_id) do update set share_code=excluded.share_code,
      rotated_at=excluded.rotated_at,rotated_by=excluded.rotated_by
    returning share_code into code;
  begin
    insert into collect_member_actions.group_share_rotations(request_id,collection_id,actor_id,session_id,share_code)
      values(p_request_id,p_collection_id,auth.uid(),sid,code);
  exception when unique_violation then
    raise exception 'group_share_request_conflict' using errcode='40001';end;
  perform public.create_audit_log('group.share_link_rotated','collection',p_collection_id,
    jsonb_build_object('request_id',p_request_id,'rotated_at',clock_timestamp()));
  return jsonb_build_object('contract_version',1,'ok',true,'collection_id',p_collection_id,
    'request_id',p_request_id,'share_code',code);
end

routine:public.run_notification_dispatch.source:
declare config jsonb; request_id bigint; begin
  -- Prevent duplicate wake-ups inside one scheduler transaction. Claims remain
  -- independently fenced across overlapping Edge invocations.
  if not pg_try_advisory_xact_lock(193517, 139) then return null; end if;
  config := public._notification_dispatch_configuration();
  if not exists (select 1 from public.notification_deliveries d
    where (d.status = 'queued' and d.next_attempt_at <= clock_timestamp())
       or (d.status = 'processing' and d.claim_expires_at <= clock_timestamp())) then return null; end if;
  select net.http_post(url := config->>'url', headers := config->'headers',
    body := '{"limit":100}'::jsonb, timeout_milliseconds := 65000) into request_id;
  return request_id;
end

routine:public.sample_collect_shadow_run.source:
declare sid uuid; l collect_security.shadow_supervisor_lease;
  r collect_security.shadow_supervisor_runs; s collect_security.shadow_supervisor_samples;
  t timestamptz; health jsonb; sms jsonb; counts jsonb; summary jsonb; body jsonb;
begin
  sid:=collect_security.require_shadow_actor();
  if p_run_id is null or p_fence_version is null or p_fence_version not between 1 and 1000000000 then
    raise exception 'shadow_request_invalid' using errcode='22023';end if;
  -- A manual health sample must use current statement snapshots, not an older
  -- caller-created Repeatable Read view presented with a fresh checked_at.
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception 'shadow_snapshot_retry' using errcode='40001';end if;
  select * into l from collect_security.shadow_supervisor_lease where id for update;
  select * into r from collect_security.shadow_supervisor_runs where id=p_run_id for update;
  if r.id is null or r.actor_id is distinct from auth.uid() or r.session_id is distinct from sid then
    raise exception 'shadow_run_unavailable' using errcode='42501';end if;
  if r.fence_version<>p_fence_version or l.active_run_id is distinct from r.id
    or l.fence_version<>p_fence_version or r.status<>'running' then
    raise exception 'shadow_fence_lost' using errcode='40001';end if;
  if r.lease_expires_at<=clock_timestamp() or l.lease_expires_at<=clock_timestamp() then
    raise exception 'shadow_lease_expired' using errcode='55000';end if;
  select * into s from collect_security.shadow_supervisor_samples where run_id=r.id;
  if s.id is not null then
    perform collect_security.shadow_run_json(r.id);
    perform collect_security.require_shadow_health(s.body->'system_health',r.started_at,clock_timestamp());
    return jsonb_build_object('contract_version',1,'mode','shadow','scope','collect_platform',
      'ok',true,'outcome','sampled','replayed',true,'run_id',r.id,'fence_version',r.fence_version,
      'sample',s.body||jsonb_build_object('sample_id',s.id,'content_sha256',s.content_sha256));
  end if;
  health:=public.admin_system_health('system');
  t:=clock_timestamp();
  perform collect_security.require_shadow_health(health,r.started_at,t);
  -- Same aggregate semantics as the assisted operator's health, without its
  -- service-only identity wrapper, full destinations, bodies or receipt IDs.
  select jsonb_build_object('enabled',coalesce((select enabled from public.feature_flags
    where key='hybrid_sms_notifications'),false),
    'queued',count(*) filter(where state='queued'),
    'awaiting_confirmation',count(*) filter(where state='awaiting_confirmation'),
    'send_started',count(*) filter(where state='send_started'),
    'uncertain',count(*) filter(where state='uncertain'),
    'suppressed',count(*) filter(where state='suppressed'),
    'oldest_queued_at',min(created_at) filter(where state='queued'),
    'active_workers',(select count(*) from collect_hybrid.sms_operator_heartbeats
      where observed_at>t-interval '3 minutes'),'observed_at',t)
  into sms from collect_hybrid.sms_notification_outbox;
  select jsonb_build_object('ok',count(*) filter(where a->>'state'='ok'),
    'unknown',count(*) filter(where a->>'state'='unknown'),
    'attention',count(*) filter(where a->>'state'='attention'),
    'not_applicable',count(*) filter(where a->>'state'='not_applicable'))
  into counts from jsonb_array_elements(health->'alerts') a;
  summary:=jsonb_build_object('health_status',case when health->>'health_status'='attention'
    or (sms->>'uncertain')::bigint>0 or (sms->>'send_started')::bigint>0 then 'attention'
    else health->>'health_status' end,'alert_counts',counts,
    'sms_queue',sms-array['oldest_queued_at','observed_at'],
    'checks_recorded',13,'samples_recorded',1,'business_mutations',0,'provider_sends',0);
  t:=clock_timestamp();
  if r.lease_expires_at<=t or l.lease_expires_at<=t then
    raise exception 'shadow_lease_expired' using errcode='55000';end if;
  perform collect_security.require_shadow_health(health,r.started_at,t);
  body:=jsonb_build_object('checked_at',t,'system_health',health,'sms_queue',sms,'summary',summary);
  insert into collect_security.shadow_supervisor_samples(run_id,checked_at,body,content_sha256)
  values(r.id,t,body,encode(extensions.digest(convert_to(body::text,'UTF8'),'sha256'),'hex'))
  returning * into s;
  return jsonb_build_object('contract_version',1,'mode','shadow','scope','collect_platform',
    'ok',true,'outcome','sampled','replayed',false,'run_id',r.id,'fence_version',r.fence_version,
    'sample',s.body||jsonb_build_object('sample_id',s.id,'content_sha256',s.content_sha256));
end

routine:public.set_notification_preferen.source:
declare receipt jsonb;begin
 perform collect_security.runtime_control_actor('notification_preferences');
 if p_preferences is null or jsonb_typeof(p_preferences)<>'object' then raise exception 'runtime_control_patch_invalid' using errcode='22023';end if;
 if (select array_agg(key order by key) from jsonb_object_keys(p_preferences) key) is distinct from
  array['contribution_confirmations','group_updates','payment_reminders','security_notices']::text[] then raise exception 'runtime_control_patch_invalid' using errcode='22023';end if;
 receipt:=public.admin_update_runtime_control_v1('notification_preferences',jsonb_build_object('user_id',auth.uid()),p_preferences,p_expected_revision,'User notification preferences update');
 return (receipt-array['family','identity','content_sha256'])||jsonb_build_object('contract_version',2,'user_id',auth.uid());
end

