routine:public.update_collection_profile.source:
declare
  clean_name text := trim(coalesce(group_name, ''));
  clean_description text := trim(coalesce(group_description, ''));
  clean_cadence text := coalesce(nullif(trim(group_recurring_cadence), ''), 'monthly');
  clean_type text;
  clean_subtype text;
  clean_purpose_label text;
  catalog_choice jsonb;
  current_row public.collections;
  next_public_status public.collection_visibility;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if not public.user_is_collection_admin(collection, auth.uid()) then
    raise exception 'Only collection admins can update the group profile';
  end if;
  if char_length(clean_name) not between 3 and 120 then
    raise exception 'Group name must be between 3 and 120 characters';
  end if;
  if char_length(clean_description) > 1000 then
    raise exception 'Group description must be 1000 characters or fewer';
  end if;
  if clean_cadence not in ('daily', 'weekly', 'monthly') then
    raise exception 'Unsupported recurring cadence';
  end if;

  select c.* into current_row from public.collections c where c.id = collection;
  if current_row.id is null then raise exception 'Group not found'; end if;
  if current_row.archived_at is not null then raise exception 'Archived groups cannot be updated'; end if;

  next_public_status := case
    when not coalesce(group_is_public, false) then 'private'::public.collection_visibility
    when current_row.public_status = 'public_approved' then 'public_approved'::public.collection_visibility
    else 'public_requested'::public.collection_visibility
  end;

  catalog_choice := public.resolve_collection_catalog_choice(
    coalesce(nullif(trim(group_collection_type), ''), current_row.collection_type),
    coalesce(nullif(trim(group_category_subtype), ''), current_row.category_subtype),
    coalesce(nullif(trim(group_purpose_label), ''), current_row.purpose_label),
    'RW'
  );
  clean_type := catalog_choice->>'collection_type';
  clean_subtype := catalog_choice->>'category_subtype';
  clean_purpose_label := catalog_choice->>'purpose_label';

  update public.collections
  set title = clean_name,
      description = clean_description,
      cover_image_url = nullif(trim(group_image_url), ''),
      accent_color_hex = nullif(trim(group_accent_color_hex), ''),
      public_status = next_public_status,
      visibility = case
        when next_public_status = 'public_approved' then 'public_approved'::public.collection_visibility
        else 'private'::public.collection_visibility
      end,
      is_recurring = coalesce(group_is_recurring, false),
      recurring_cadence = clean_cadence,
      recurring_rule = case
        when coalesce(group_is_recurring, false)
          then jsonb_build_object('cadence', clean_cadence)
        else null
      end,
      collection_type = clean_type,
      category_subtype = clean_subtype,
      purpose_label = clean_purpose_label,
      updated_at = now()
  where id = collection;

  perform public.create_audit_log(
    'collection.profile_updated',
    'collection',
    collection,
    jsonb_build_object(
      'public_status', next_public_status::text,
      'is_recurring', coalesce(group_is_recurring, false),
      'recurring_cadence', clean_cadence,
      'collection_type', clean_type,
      'category_subtype', clean_subtype,
      'purpose_label', clean_purpose_label
    )
  );
end;

begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;
  if not exists (
    select 1
    from public.collections collection_row
    where collection_row.id = collection
      and collection_row.creator_user_id = auth.uid()
      and collection_row.archived_at is null
  ) then
    raise exception 'Only the current group owner can update group settings';
  end if;

  perform public.update_collection_profile(
    collection,
    group_name,
    group_description,
    group_image_url,
    group_accent_color_hex,
    group_is_public,
    group_recurring_cadence,
    group_collection_type,
    group_category_subtype,
    group_purpose_label,
    group_is_recurring
  );
  perform public.update_collection_receiver(
    collection,
    receiver_momo_number,
    receiver_momo_number_hash,
    receiver_label
  );
end;

routine:public.update_collection_receive.source:
declare
  collection_row public.collections;
  clean_label text := coalesce(
    nullif(trim(receiver_label), ''),
    'Primary MOMO receiver'
  );
  submitted_digits text := regexp_replace(
    coalesce(receiver_momo_number, ''),
    '[^0-9]',
    '',
    'g'
  );
  profile_digits text;
  canonical_receiver text;
  computed_receiver_hash text;
  previous_receiver_hash text;
  previous_receiver_user_id uuid;
  receiver_is_code boolean;
  member_user_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  select collection_row_value.*
  into collection_row
  from public.collections collection_row_value
  where collection_row_value.id = collection
  for update;

  if collection_row.id is null or collection_row.creator_user_id <> auth.uid() then
    raise exception 'Only the group owner can update the receiver';
  end if;

  receiver_is_code := lower(clean_label) like '%code%';
  if receiver_is_code then
    select regexp_replace(coalesce(profile.momo_pay_code, ''), '[^0-9]', '', 'g')
    into profile_digits
    from public.profiles profile
    where profile.id = auth.uid();
    if profile_digits !~ '^[0-9]{4,9}$' then
      raise exception 'Link a valid MoMo code to your profile first';
    end if;
    canonical_receiver := '+' || profile_digits;
  else
    select regexp_replace(coalesce(profile.momo_number, ''), '[^0-9]', '', 'g')
    into profile_digits
    from public.profiles profile
    where profile.id = auth.uid();
    if profile_digits ~ '^250[0-9]{9}$' then
      canonical_receiver := '+' || profile_digits;
    elsif profile_digits ~ '^0[0-9]{9}$' then
      canonical_receiver := '+250' || substr(profile_digits, 2);
    else
      raise exception 'Link a valid Rwanda MoMo number to your profile first';
    end if;
  end if;

  if submitted_digits <> regexp_replace(canonical_receiver, '[^0-9]', '', 'g')
     and not (
       not receiver_is_code
       and submitted_digits ~ '^0[0-9]{9}$'
       and substr(submitted_digits, 2) = substr(
         regexp_replace(canonical_receiver, '[^0-9]', '', 'g'),
         4
       )
     ) then
    raise exception 'Receiver must match the MoMo receiver linked to your profile';
  end if;

  computed_receiver_hash := encode(digest(canonical_receiver, 'sha256'), 'hex');
  if lower(trim(coalesce(receiver_momo_number_hash, ''))) <> computed_receiver_hash then
    raise exception 'Receiver verification failed';
  end if;

  select route.momo_number_hash, route.receiver_user_id
  into previous_receiver_hash, previous_receiver_user_id
  from public.collection_receivers route
  where route.collection_id = collection
    and route.is_active
  order by route.created_at desc
  limit 1;

  -- A profile-only save must not rotate an unchanged financial route or be
  -- blocked by pending intents. Label changes are non-financial metadata.
  if previous_receiver_hash = computed_receiver_hash
     and previous_receiver_user_id = auth.uid() then
    update public.collection_receivers
    set label = clean_label
    where collection_id = collection
      and is_active;
    update public.collections
    set receiver_display_label = clean_label,
        updated_at = now()
    where id = collection;
    return;
  end if;

  update public.payment_intents
  set status = 'expired'
  where collection_id = collection
    and status = 'pending'
    and expires_at <= now();
  if exists (
    select 1
    from public.payment_intents intent
    where intent.collection_id = collection
      and intent.status = 'pending'
  ) then
    raise exception 'Receiver cannot change while contribution requests are pending';
  end if;

  update public.collection_receivers
  set is_active = false
  where collection_id = collection
    and is_active;

  insert into public.collection_receivers (
    collection_id,
    receiver_user_id,
    momo_number,
    momo_number_hash,
    label,
    is_active
  ) values (
    collection,
    auth.uid(),
    canonical_receiver,
    computed_receiver_hash,
    clean_label,
    true
  );

  update public.collections
  set receiver_display_label = clean_label,
      updated_at = now()
  where id = collection;

  insert into public.audit_logs (
    actor_user_id,
    action,
    entity_type,
    entity_id,
    metadata
  ) values (
    auth.uid(),
    'collection.receiver_updated',
    'collection',
    collection,
    jsonb_build_object(
      'receiver_label', clean_label,
      'previous_receiver_hash', previous_receiver_hash,
      'new_receiver_hash', computed_receiver_hash,
      'profile_derived', true,
      'owner_only', true
    )
  );

  for member_user_id in
    select distinct member.user_id
    from public.collection_members member
    where member.collection_id = collection
      and member.status = 'active'
      and member.user_id <> auth.uid()
  loop
    perform public.enqueue_notification_template_event(
      member_user_id,
      'group.update.default',
      jsonb_build_object('group', collection_row.title),
      collection,
      '/groups/' || collection::text,
      'en'
    );
  end loop;
end;

routine:public.update_current_member_pro.source:
declare
  profile_row public.profiles%rowtype;
  clean_provider text := lower(btrim(coalesce(p_momo_provider, '')));
  clean_momo text := public._rwanda_momo_local(p_momo_number);
  clean_code text := nullif(btrim(coalesce(p_momo_pay_code, '')), '');
  auth_phone text;
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  if upper(btrim(coalesce(p_country_code, ''))) <> 'RW' then
    raise exception 'Collect supports Rwanda profiles only';
  end if;
  if clean_provider not in ('mtn_momo', 'airtel_money') or clean_momo is null
     or (clean_provider = 'mtn_momo' and clean_momo !~ '^07[89][0-9]{7}$')
     or (clean_provider = 'airtel_money' and clean_momo !~ '^07[23][0-9]{7}$') then
    raise exception 'Choose a valid Rwanda MoMo provider and number';
  end if;
  if clean_code is not null and clean_code !~ '^[0-9]{4,9}$' then
    raise exception 'Enter a MoMo code with 4 to 9 digits';
  end if;
  select phone into auth_phone from auth.users where id = auth.uid();
  update public.profiles
  set country_code = 'RW',
      currency_code = 'RWF',
      momo_provider = clean_provider,
      momo_number = clean_momo,
      momo_number_hash = encode(
        extensions.digest('+250' || substr(clean_momo, 2), 'sha256'), 'hex'
      ),
      momo_number_verified_at = case
        when clean_momo = public._rwanda_momo_local(auth_phone)
          then coalesce(momo_number_verified_at, now())
        else null end,
      momo_pay_code = clean_code,
      revolut_link = null,
      revolut_account = null,
      updated_at = now()
  where id = auth.uid()
  returning * into profile_row;
  if profile_row.id is null then raise exception 'Collect profile not found'; end if;
  insert into public.audit_logs(actor_user_id, action, entity_type, entity_id, metadata)
  values (
    auth.uid(), 'profile.rwanda_momo.updated', 'profile', auth.uid(),
    jsonb_build_object(
      'country_code', 'RW', 'currency_code', 'RWF',
      'momo_provider', clean_provider,
      'momo_number_matches_whatsapp', profile_row.momo_number_verified_at is not null,
      'has_momo_code', clean_code is not null
    )
  );
  return public._member_profile_payload(profile_row);
end;

routine:public.update_current_profile(te.source:
declare
  profile_row public.profiles%rowtype;
  country_rule public.profile_country_rules%rowtype;
  auth_phone text;
  clean_auth_momo text;
  clean_display text := btrim(coalesce(p_display_name, ''));
  clean_country text := upper(btrim(coalesce(p_country_code, '')));
  clean_provider text := lower(nullif(btrim(coalesce(p_momo_provider, '')), ''));
  clean_momo text := public._rwanda_momo_local(p_momo_number);
  clean_revolut_name text := nullif(btrim(coalesce(p_revolut_name, '')), '');
  clean_revolut_link text := nullif(btrim(coalesce(p_revolut_link, '')), '');
  clean_revolut_account text := nullif(btrim(coalesce(p_revolut_account, '')), '');
  previous_country text;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if char_length(clean_display) not between 2 and 80 then
    raise exception 'Display name must be between 2 and 80 characters';
  end if;
  select * into country_rule from public.profile_country_rules
  where country_code = clean_country and enabled;
  if country_rule.country_code is null then raise exception 'Unsupported profile country'; end if;

  if clean_country = 'RW' then
    if clean_provider not in ('mtn_momo', 'airtel_money') then
      raise exception 'Choose MTN MoMo or Airtel Money';
    end if;
    if clean_momo is null then
      raise exception 'Use a Rwanda MoMo number such as 078XXXXXXX';
    end if;
    if (clean_provider = 'mtn_momo' and clean_momo !~ '^07[89][0-9]{7}$')
       or (clean_provider = 'airtel_money' and clean_momo !~ '^07[23][0-9]{7}$') then
      raise exception 'MoMo provider does not match the Rwanda mobile number';
    end if;
  elsif clean_revolut_name is null
     or char_length(clean_revolut_name) not between 2 and 100
     or clean_revolut_link is null
     or clean_revolut_link !~ '^https://([a-z0-9-]+\.)?revolut\.me/[A-Za-z0-9._~-]+/?$'
     or clean_revolut_account is null
     or char_length(clean_revolut_account) not between 4 and 120 then
    raise exception 'Diaspora profiles require a Revolut name, Revolut.me link, and account details';
  end if;

  select country_code into previous_country from public.profiles where id = auth.uid();
  select phone into auth_phone from auth.users where id = auth.uid();
  clean_auth_momo := public._rwanda_momo_local(auth_phone);

  update public.profiles
  set display_name = clean_display,
      country_code = country_rule.country_code,
      currency_code = country_rule.currency_code,
      momo_provider = case when clean_country = 'RW' then clean_provider else null end,
      momo_number = case when clean_country = 'RW' then clean_momo else null end,
      momo_number_hash = case when clean_country = 'RW' then
        encode(extensions.digest('+250' || substr(clean_momo, 2), 'sha256'), 'hex')
        else null end,
      momo_number_verified_at = case
        when clean_country = 'RW' and clean_momo = clean_auth_momo
          then coalesce(momo_number_verified_at, now())
        else null
      end,
      revolut_name = case when clean_country <> 'RW' then clean_revolut_name else null end,
      revolut_link = case when clean_country <> 'RW' then clean_revolut_link else null end,
      revolut_account = case when clean_country <> 'RW' then clean_revolut_account else null end,
      updated_at = now()
  where id = auth.uid()
  returning * into profile_row;
  if profile_row.id is null then raise exception 'Collect profile not found'; end if;

  insert into public.audit_logs (actor_user_id, action, entity_type, entity_id, metadata)
  values (
    auth.uid(), 'profile.payment_route.updated', 'profile', auth.uid(),
    jsonb_build_object(
      'previous_country_code', previous_country,
      'country_code', profile_row.country_code,
      'currency_code', profile_row.currency_code,
      'payment_rail', case when clean_country = 'RW' then 'momo_ussd_sms' else 'diaspora_bank_revolut' end,
      'momo_provider', profile_row.momo_provider,
      'momo_number_matches_whatsapp', profile_row.momo_number_verified_at is not null,
      'has_revolut_link', profile_row.revolut_link is not null,
      'has_revolut_account', profile_row.revolut_account is not null
    )
  );
  return profile_row;
end;

routine:public.update_rwanda_momo_group_.source:
begin
  perform collect_profile_access.assert_ready('rwanda');
  if not exists (
    select 1 from public.collections collection
    where collection.id = p_collection_id
      and collection.creator_user_id = auth.uid()
      and collection.archived_at is null
      and collection.currency = 'RWF'
      and not collection.diaspora_enabled
  ) then
    raise exception 'Only the current Rwanda group owner can update group settings';
  end if;
  perform public.update_collection_profile(
    p_collection_id, p_group_name, p_group_description,
    p_group_image_url, p_group_accent_color_hex,
    (select public_status = 'public_approved' from public.collections where id = p_collection_id),
    p_group_recurring_cadence, p_group_collection_type,
    p_group_category_subtype, p_group_purpose_label, p_group_is_recurring
  );
end;
